window.__Q=window.__Q||{};window.__Q["tcm/4/A1"]=[{"q":"具有“辛凉透表，清热解毒”功用的方剂是","o":["桑菊饮","香薷散","败毒散","银翘散","黄连解毒汤"],"a":3,"e":"银翘散以金银花、连翘为君，辛凉透表兼清热解毒，主治温病初起、发热无汗。桑菊饮为辛凉轻剂，功在疏风清热、宣肺止咳，无清热解毒之力；黄连解毒汤纯泻火解毒而不透表；香薷散祛暑解表化湿，性偏辛温"},{"q":"阿胶鸡子黄汤证的病机是","o":["温病迁延日久，邪热灼伤真阴","温热病邪传入厥阴，肝经热盛，热极动风","肝肾阴虚，肝阳偏亢，阳亢化风，气血逆乱","肝肾不足，肝阳偏亢，生风化热","邪热久羁，耗伤阴血，虚风内动"],"a":4,"e":"阿胶鸡子黄汤主治热邪久羁、灼伤阴血、虚风内动，以滋阴养血、柔肝息风为法，见手足蠕动、心中憺憺。A项仅言温病日久伤阴，未及动风；B项热极动风属羚角钩藤汤证；C项气血逆乱偏镇肝熄风汤之中风；D项肝肾不足生风化热另有所主"},{"q":"橘皮竹茹汤组成中有","o":["黄芪","人参、生姜","白术","枳壳","半夏"],"a":1,"e":"橘皮竹茹汤由橘皮、竹茹、人参、生姜、大枣、甘草组成，降逆止呕、益气清热，故含人参、生姜。黄芪、白术为补中健脾之品，本方不用；枳壳破气，半夏燥湿化痰，均非本方药物，半夏多用于旋覆代赭汤、小半夏汤之类"},{"q":"下列各项，其中哪项不是定喘汤药物","o":["白果、麻黄","苏子、款冬花","杏仁、桑皮","黄芩、半夏","陈皮、茯苓"],"a":4,"e":"定喘汤含白果、麻黄、苏子、款冬花、杏仁、桑白皮、黄芩、半夏、甘草，宣肺降气、清热化痰，无陈皮、茯苓。陈皮、茯苓为二陈汤主药，理气燥湿化痰；A至D所列白果、麻黄、苏子、款冬花、桑皮、黄芩、半夏皆本方所有"},{"q":"下列不属于金锁固精丸组成的是","o":["莲子","沙苑蒺藜","龟甲","芡实","龙骨"],"a":2,"e":"金锁固精丸由沙苑子、芡实、莲须、龙骨、牡蛎、莲子组成，涩精止遗，无龟甲。龟甲滋阴潜阳、益肾健骨，多用于大定风珠、龟鹿二仙胶；莲子、芡实健脾固肾涩精，沙苑蒺藜补肾固精，龙骨煅用涩精，均属本方"},{"q":"木香槟榔丸主治","o":["痢疾、食积","脾虚食积","食积证","湿热食积","酒积伤脾"],"a":0,"e":"木香槟榔丸行气导滞、攻积泄热，重在行气破积，主治痢疾、食积而见脘腹胀满、大便不爽者。脾虚食积宜健脾丸扶正消食；单纯食积可用保和丸和胃；酒积伤脾宜葛花解酲汤解酒；湿热食积偏重者枳实导滞丸更切，本方偏于行气攻下"},{"q":"以大便秘结，小便频数，舌质红，苔薄黄，脉数为辨证要点的方剂是","o":["济川煎","肾气丸","黄龙汤","十枣汤","麻子仁丸"],"a":4,"e":"麻子仁丸为脾约证而设，胃肠燥热、脾津不足，故大便秘结而小便频数，舌红苔薄黄脉数。济川煎治肾虚便秘兼腰膝酸软；黄龙汤为阳明腑实兼气血虚；十枣汤攻逐水饮；肾气丸温补肾阳，均非此证。本方以麻子仁润肠、枳实厚朴行气，泻而不峻"},{"q":"大承气汤中，用以行气消除胀满的药物是","o":["大黄","芒硝","枳实","厚朴","甘遂"],"a":3,"e":"厚朴在大承气汤中行气除满，专消脘腹胀满，为消痞除满之要药。大黄泻热通便、荡涤肠胃，芒硝软坚润燥以化燥屎，枳实破气消痞，三者与厚朴各司其职；甘遂为峻下逐水药，主治水肿痰饮，大承气汤不用，故行气消胀当推厚朴"},{"q":"清燥救肺汤的功用是","o":["清热燥湿，调和气血","清宣温燥，润肺止咳","轻宣凉燥，理肺化痰","清养肺胃，降逆下气","清燥润肺，养阴益气"],"a":4,"e":"清燥救肺汤清燥润肺、养阴益气，主治温燥伤肺重证，见干咳无痰、气逆而喘、舌红少苔。清宣温燥、润肺止咳为桑杏汤所主轻证；轻宣凉燥、理肺化痰属杏苏散治凉燥；清养肺胃、降逆下气是麦门冬汤；清热燥湿、调和气血非本方功用"},{"q":"有关君药的认识，不确切的是","o":["药力居方中之首","用量较作为臣、佐药应用时大","能引方中诸药以达病所","针对主证或主病起主要治疗作用","君药在方中是首要的"],"a":2,"e":"君药针对主病主证起主要治疗作用，药力居方中之首、用量较臣佐为大。引诸药达病所是使药中引经药的职能，如桔梗载药上行；D项、E项所述均为君药要义，A项亦符合君药药力居首之象，故C项把使药职责安在君药头上，认识不确切"},{"q":"属于固涩剂适应范围的病证是","o":["血热崩漏","肺虚久咳","火动遗精","伤食泄泻","热病多汗"],"a":1,"e":"固涩剂主治正气亏虚、滑脱不禁之证，肺虚久咳宜用敛肺止咳之九仙散。血热崩漏、火动遗精、热病多汗皆属热邪所致，早用固涩反能留邪恋病；伤食泄泻当消食导滞以祛病因，亦非固涩所宜，故固涩剂以虚证滑脱为界"},{"q":"症见脘腹胀满，舌苔白厚腻者，治宜","o":["燥湿运脾，和胃止呕","燥湿运脾，行气和胃","燥湿运脾，行气导滞","解表化湿，行气和胃","解表化湿，行气利水"],"a":1,"e":"脘腹胀满、舌苔白厚腻为湿滞脾胃之象，平胃散主之，功在燥湿运脾、行气和胃。行气导滞偏枳实导滞丸，主湿热食积；解表化湿、行气和胃为藿香正气散，主外感湿滞；和胃止呕非本方主功；利水渗湿属五苓散之类，均非本方所宜"},{"q":"大承气汤与大柴胡汤共用的药物是","o":["大黄、芒硝","大黄、厚朴","大黄、枳实","大黄、炙甘草","枳实、厚朴"],"a":2,"e":"大承气汤含大黄、芒硝、枳实、厚朴，大柴胡汤含柴胡、黄芩、大黄、枳实、半夏、生姜、大枣、芍药，两方共用大黄、枳实，一泻热一破结。芒硝、厚朴仅大承气汤有，大柴胡汤无；炙甘草两方均无，故其余组合皆非共有"},{"q":"四君子汤的功用为","o":["益气养阴","健脾养胃","补益肝脾","益气健脾","益气补血"],"a":3,"e":"四君子汤由人参、白术、茯苓、炙甘草组成，益气健脾，为补气基础方，主治脾胃气虚之面白食少。益气养阴属生脉散；健脾养胃非其规范表述；益气补血为八珍汤、归脾汤；补益肝脾亦非本方功用，本方专补脾胃之气"},{"q":"消风散证的致病因素是","o":["风寒","风热","风湿","风寒湿","风湿热"],"a":4,"e":"消风散主治风湿热邪蕴肤之瘾疹、湿疹，皮肤瘙痒、疹出色红，致病因素为风湿热三者相合。单纯风湿多羌活胜湿汤；风寒表证麻黄汤；风热表证桑菊饮；风寒湿痹阻经络为痹证，均非消风散疏风养血、清热除湿所主"},{"q":"温里剂组方中，最常与温里药配伍的是","o":["滋阴药","解表药","活血药","补气药","固涩药"],"a":3,"e":"温里剂温散里寒，辛热之品易耗气伤中，故常配伍补气药以助温补、顾护中气，如理中丸之人参、白术配干姜。滋阴药助湿滞邪，与温里相悖；解表药主治表证；固涩药留邪，皆非温里剂常规配伍。如理中丸、附子理中丸皆此配伍之例"},{"q":"五积散的功用是","o":["发表清里，顺气化痰，活血消积","发表温里，顺气化痰，活血消积","解表散寒，顺气化痰，消食化积","解表散寒，温肺化饮，消食化积","清热泻火，顺气化痰，消食化积"],"a":1,"e":"五积散发表温里、顺气化痰、活血消积，主治外感风寒、内伤生冷之表里同病。发表清里非五积散之制，本方重在温散；解表散寒、温肺化饮为小青龙汤；清热泻火更非本方，其发表温里、消痰化积之能非他方可比"},{"q":"定喘汤的组成中不含有","o":["款冬花、桑白皮","苏子、半夏","桑叶、生石膏","白果、甘草","杏仁、黄芩"],"a":2,"e":"定喘汤含白果、麻黄、苏子、款冬花、杏仁、桑白皮、黄芩、半夏、甘草，宣肺降气、清热化痰，不含桑叶、生石膏。桑叶、生石膏多用于风热、肺热喘咳如麻杏甘石汤，与本方外束风寒、内蕴痰热之制不同，故不可混用"},{"q":"主治证病机为“素体阳气虚弱，复感风寒”的方剂是","o":["败毒散","参苏饮","麻黄附子细辛汤","再造散","加减葳蕤汤"],"a":3,"e":"再造散助阳益气、解表散寒，主治素体阳气虚弱、复感风寒，见恶寒重、发热轻、无汗。败毒散益气解表针对气虚外感；参苏饮理气解表；麻黄附子细辛汤助阳解表而无益气之功；加减葳蕤汤滋阴解表，均非阳虚气弱之感寒"},{"q":"桑螵蛸散的主治证是","o":["心脾两虚证","心肾两虚证","脾肾两虚证","肝肾两虚证","肺肾两虚证"],"a":1,"e":"桑螵蛸散调补心肾、涩精止遗，主治心肾两虚之尿频、遗尿、滑精，兼健忘、心神恍惚。心脾两虚属归脾汤；脾肾两虚多温补脾肾固涩之剂；肝肾两虚、肺肾两虚均非本方病机，本方重在交通心肾，非单纯补肾"},{"q":"龟鹿二仙胶的功用中包括","o":["滋阴降火","填精补血","涩精止遗","益气壮阳","养肝敛阴"],"a":3,"e":"龟鹿二仙胶滋阴填精、益气壮阳，鹿角胶补阳、龟板滋阴，故功用包括益气壮阳。滋阴降火为知柏地黄丸；涩精止遗属金锁固精丸；养肝敛阴非本方主功，本方以血肉有情之品填补精髓，兼益元气，非单纯滋阴"},{"q":"原方用法要求药后“饮粥二升”并“一日食糜粥”的是","o":["吴茱萸汤","小建中汤","大建中汤","小柴胡汤","大承气汤"],"a":2,"e":"大建中汤温中补虚、降逆止痛，主治中阳衰弱、阴寒内盛之心腹剧痛，原方服后饮粥二升、一日食糜粥以助胃气。小建中汤服后饮热粥；吴茱萸汤、小柴胡汤无此用法；大承气汤日三服，均非饮粥二升之制"},{"q":"下列方剂中，哪一项与滋养肺阴无关","o":["增液汤","百合固金汤","麦门冬汤","琼玉膏","清燥救肺汤"],"a":0,"e":"增液汤滋阴清热、润燥通便，主阳明温病津亏便秘，增水行舟，并不滋养肺阴。百合固金汤养阴润肺化痰；麦门冬汤滋养肺胃降逆；琼玉膏滋阴润肺补脾；清燥救肺汤清燥润肺益气，皆与肺阴相关。增液汤增水行舟，专为津枯便秘而设"},{"q":"三仁汤中的“三仁”是","o":["杏仁、火麻仁、薏苡仁","杏仁、郁李仁、薏苡仁","杏仁、桃仁、薏苡仁","杏仁、砂仁、薏苡仁","杏仁、白蔻仁、薏苡仁"],"a":4,"e":"三仁汤之三仁为杏仁、白蔻仁、薏苡仁，杏仁宣上、蔻仁畅中、薏仁导下，分消三焦湿邪。桃仁活血祛瘀，火麻仁润肠通便，郁李仁利水消肿，砂仁化湿行气，皆非三仁汤宣畅三焦所用之仁。三仁合用，宣上畅中导下，使湿从小便而去"},{"q":"主治肠痈初起的方剂是","o":["内补黄芪汤","五味消毒饮","大黄牡丹汤","苇茎汤","阳和汤"],"a":2,"e":"大黄牡丹汤泻热破瘀、散结消肿，主治肠痈初起湿热瘀滞，见右下腹疼痛拒按。苇茎汤清肺化痰、逐瘀排脓治肺痈；阳和汤温阳补血治阴疽；五味消毒饮清热解毒治疔疮；内补黄芪汤补益气血，均非肠痈初起之剂"},{"q":"具有降逆化痰、益气和胃功效的方剂是","o":["橘皮竹茹汤","旋覆代赭汤","半夏泻心汤","半夏厚朴汤","厚朴温中汤"],"a":1,"e":"旋覆代赭汤降逆化痰、益气和胃，主治胃虚痰阻气逆之嗳气、心下痞硬。橘皮竹茹汤降逆止呕、益气清热；半夏泻心汤寒热平调消痞；半夏厚朴汤行气散结化痰治梅核气；厚朴温中汤温中行气燥湿，各有所主"},{"q":"仙方活命饮的适应证是","o":["火毒结聚之疔疮","痈疡肿毒初起","热毒炽盛之脱疽","阳虚寒凝之阴疽","风火痰热之痈疮"],"a":1,"e":"仙方活命饮清热解毒、消肿溃坚、活血止痛，主治痈疡肿毒初起，红肿热痛。火毒结聚之疔疮用五味消毒饮；热毒炽盛之脱疽、阳虚寒凝之阴疽均非本方；风火痰热之痈疮非其典型适应证，本方为疮疡初起之首选"},{"q":"定喘汤与小青龙汤共有的药物是","o":["苏子、白果","麻黄、半夏","杏仁、冬花","桑白皮、黄芩","细辛、干姜"],"a":1,"e":"定喘汤与小青龙汤均含麻黄、半夏，共奏宣肺平喘、化痰降逆之功。苏子、白果、桑白皮、黄芩为定喘汤清热化痰独有；细辛、干姜为小青龙汤温化寒饮独有；杏仁、款冬花仅定喘汤有，小青龙汤用芍药、五味子敛肺"},{"q":"治痰剂中常配伍的药物是","o":["祛湿药","补气药","清热药","收涩药","温里药"],"a":0,"e":"痰由湿聚，脾为生痰之源，治痰剂常配祛湿药健脾燥湿，以绝生痰之源，如二陈汤之半夏、茯苓。补气药治气虚生痰属兼配；清热药、温里药针对热痰寒痰；收涩药敛邪留痰，均非治痰剂常规配伍。脾健则湿无由生，痰亦无由聚"},{"q":"养阴清肺汤与百合固金汤两方均含有的药物是","o":["生地、玄参","贝母、薄荷","当归、白芍","桔梗、丹皮","熟地、甘草"],"a":0,"e":"养阴清肺汤与百合固金汤均含生地、玄参、麦冬、贝母、甘草，故共有生地、玄参。薄荷仅养阴清肺汤有；当归、白芍养血和营属百合固金汤；桔梗、丹皮非两方共有；熟地仅百合固金汤用，两方虽同治阴虚咳嗽而配伍有别"},{"q":"以滋肾阴、补肾阳、开窍化痰为功用的方剂是","o":["左归丸","左归饮","右归丸","右归饮","地黄饮子"],"a":4,"e":"地黄饮子滋肾阴、补肾阳、开窍化痰，主治喑痱，见舌强不能言、足废不能用。左归丸、左归饮纯滋肾阴而无开窍；右归丸、右归饮温补肾阳而无化痰，皆不能治喑痱之窍闭，本方阴阳并补兼化痰开窍。本方又治肾虚痰阻之喑痱，标本兼顾"},{"q":"《医方考》中“泻责之脾，痛责之肝；肝责之实、脾责之虚。脾虚肝郁，故令痛泻”是对哪首方剂主治病机的描述","o":["四逆散","痛泻要方","半夏泻心汤","芍药汤","四神丸"],"a":1,"e":"《医方考》所论脾虚肝郁、泻而腹痛，正指痛泻要方，功能补脾柔肝、祛湿止泻。四逆散透邪解郁治热厥；半夏泻心汤和胃降逆消痞；芍药汤清热燥湿治痢疾；四神丸温肾暖脾治五更泻，均非痛泻之机。本方白术燥湿健脾，白芍柔肝缓急止痛"},{"q":"胃虚、痰阻、气逆之心下痞硬、呕呃之证，宜用","o":["半夏厚朴汤","厚朴温中汤","半夏泻心汤","橘皮竹茹汤","旋覆代赭汤"],"a":4,"e":"旋覆代赭汤降逆化痰、益气和胃，主治胃虚痰阻之心下痞硬、噫气不除。半夏厚朴汤治痰气郁结之梅核气；半夏泻心汤治寒热错杂之痞；橘皮竹茹汤治胃虚有热呃逆；厚朴温中汤温中行气燥湿，病机各异"},{"q":"半夏泻心汤与小柴胡汤两方组成中均含有的药物是","o":["人参、黄芩、半夏、干姜","人参、生姜、半夏、大枣","半夏、黄芩、人参、大枣","柴胡、黄芩、人参、生姜","半夏、黄连、黄芩、大枣"],"a":2,"e":"半夏泻心汤与小柴胡汤均含半夏、黄芩、人参、大枣、甘草、生姜。干姜仅半夏泻心汤用以散结；柴胡仅小柴胡汤用以和解；黄连仅半夏泻心汤用以清热，故半夏、黄芩、人参、大枣为两方共有药物。两方共用以半夏、黄芩为消痞和解之主"},{"q":"以下关于镇肝熄风汤证的辨证要点描述错误的是","o":["头目眩晕","脑部胀痛","面色如醉","心中烦热","脉弦数"],"a":4,"e":"镇肝熄风汤辨证要点为头目眩晕、脑部胀痛、面色如醉、心中烦热，脉弦长有力，非脉弦数。头目眩晕、脑部胀痛、面色如醉、心中烦热均为肝阳上亢、气血逆乱之象，脉弦数主热盛，与本方脉象不符。本方重用赭石、牛膝镇逆下气，脉当弦长有力"},{"q":"蒿芩清胆汤证之“小便黄少”病机为何","o":["湿阻三焦","内热煎熬","寒湿不化","瘀血内停","阴阳两虚"],"a":0,"e":"蒿芩清胆汤证湿阻三焦、水道不利，故小便黄少，兼见寒热如疟、口苦膈满。内热煎熬伤津致小便短赤，非本方主因；寒湿不化、瘀血内停、阴阳两虚均不涉三焦湿郁，皆非小便黄少之病机。青蒿、黄芩清透少阳，竹茹、半夏化湿和胃"},{"q":"下列哪一项不是理中丸的用法","o":["日三服，夜二服","腹中未热 ，益至三四丸","服汤后，饮冷开水一升","微自温，勿发揭衣被","服汤后，饮热粥一升许"],"a":2,"e":"理中丸服法为日三服、夜二服，腹中未热益至三四丸，服汤后饮热粥一升许，温覆勿揭衣被。饮冷开水一升悖于温中散寒之旨，且冷饮伤中阳，与理中丸温脾益气之制完全相反，绝非其用法。服后温覆勿揭衣被，正为助药力温复中阳"},{"q":"四神丸的功用是","o":["疏肝和胃，固肠止泻","健脾益气，固肠止泻","温肾暖脾，固肠止泻","益胃暖脾，固肠止泻","温中散寒，固肠止泻"],"a":2,"e":"四神丸温肾暖脾、固肠止泻，主治命门火衰、脾肾虚寒之五更泄泻。疏肝和胃属痛泻要方；健脾益气参苓白术散；温中散寒理中丸；益胃暖脾非本方，本方重在温肾助阳以暖脾土。命门火衰不能温煦脾土，故五更作泻"},{"q":"贝母瓜蒌散主治证是","o":["湿痰咳嗽","热痰咳嗽","燥痰咳嗽","寒痰咳嗽","风痰眩晕"],"a":2,"e":"贝母瓜蒌散润肺清热、理气化痰，主治燥痰咳嗽，痰少而黏、咯之难出。湿痰咳嗽二陈汤燥湿化痰；热痰咳嗽清气化痰丸清热化痰；寒痰咳嗽宜温化寒痰剂；风痰眩晕半夏白术天麻汤，证型各别。本方浙贝母、瓜蒌润燥化痰，肺燥得润"},{"q":"最有可能在服法中使用反佐法的是","o":["四逆散","四逆汤","当归四逆汤","桂枝汤","小建中汤"],"a":1,"e":"四逆汤治阴寒极盛、虚阳欲脱，恐格拒不受，故热药冷服，属反佐法。四逆散透邪解郁治阳郁厥逆；当归四逆汤温经养血治血虚寒厥；桂枝汤调和营卫；小建中汤温中补虚，均无此反佐服法。本方加大黄、附子，热药冷服以防格拒"},{"q":"药物配伍具有“分经论治”特点的方剂是","o":["小柴胡汤","败毒散","桂枝汤","小青龙汤","九味羌活汤"],"a":4,"e":"九味羌活汤分经论治，羌活入太阳、苍术入太阴、细辛入少阴、川芎入厥阴、白芷入阳明、黄芩入少阳，诸药各归其经。小柴胡汤和解少阳；败毒散益气解表；桂枝汤调和营卫；小青龙汤温化寒饮，皆无分经之制"},{"q":"下列哪项不是桑杏汤的辨证要点","o":["身热不甚","咽干鼻燥","干咳无痰","气逆而喘","舌红"],"a":3,"e":"桑杏汤辨证要点为身热不甚、咽干鼻燥、干咳无痰、舌红，气逆而喘非其所有。气逆而喘属肺热壅盛之麻杏甘石汤证；身热不甚、咽干鼻燥、干咳无痰、舌红均为温燥伤肺轻证之象，本方清宣温燥。桑杏汤为轻宣温燥之轻剂，故证情较轻"},{"q":"蒿芩清胆汤与八正散组成中共有的药物是","o":["枳实、大黄","黄芩、木通","半夏、栀子","滑石、甘草","青蒿、车前子"],"a":3,"e":"蒿芩清胆汤与八正散均含滑石、甘草，清热利湿。枳实、大黄属承气类；黄芩蒿芩清胆汤有而八正散无；木通、栀子、车前子为八正散利水通淋之品；半夏、青蒿仅蒿芩清胆汤用，两方功用一和解一通淋"},{"q":"体现“芳香清透以畅少阳之枢机，苦燥降利以化湿郁之痰浊”配伍特点的方剂是","o":["半夏泻心汤","茵陈蒿汤","蒿芩清胆汤","小柴胡汤","大柴胡汤"],"a":2,"e":"蒿芩清胆汤芳香清透以畅少阳枢机，苦燥降利以化湿郁痰浊，主治少阳湿热、寒热如疟。半夏泻心汤寒热平调消痞；茵陈蒿汤清热利湿退黄；小柴胡汤和解少阳但无化湿；大柴胡汤和解兼泻下，配伍各异"},{"q":"小柴胡汤中配伍生姜的意义是","o":["和胃止呕","发汗解表","温中散寒","解表利水","疏泄少阳"],"a":0,"e":"小柴胡汤中生姜和胃止呕，助半夏降逆，兼制半夏之毒。发汗解表非生姜在此之用；温中散寒属理中丸干姜；解表利水非其职；疏泄少阳为柴胡、黄芩之功，故生姜之意义在于和胃降逆。生姜与大枣调和脾胃，助参草补中和胃"},{"q":"被称为“辛凉轻剂”的方剂是","o":["桑菊饮","香薷散","银翘散","香苏散","葱豉桔梗汤"],"a":0,"e":"桑菊饮为辛凉轻剂，疏风清热、宣肺止咳，主治风温初起、咳嗽轻微。银翘散为辛凉平剂，清热解毒力胜；香薷散祛暑解表；香苏散疏肝理气解表；葱豉桔梗汤疏风清热，均非辛凉轻剂之称。桑菊饮以桑叶、菊花轻清透表，故称轻剂"},{"q":"四磨汤的功效是","o":["宣肺降气，清热化痰","行气降逆，宽胸散结","化痰散引，和胃降逆","降逆止呃，益气清热","降逆化痰，益气和胃"],"a":1,"e":"四磨汤行气降逆、宽胸散结，主治七情气逆、胸膈痞闷。宣肺降气、清热化痰属麻杏甘石汤类；降逆止呃、益气清热是橘皮竹茹汤；降逆化痰、益气和胃为旋覆代赭汤，皆非四磨汤破气降逆之制。本方以槟榔、枳实破气，乌药、沉香降逆"},{"q":"下列属于蒿芩清胆汤组成的药物是","o":["柴胡","黄连","白芍","茵陈","滑石"],"a":4,"e":"蒿芩清胆汤含青蒿、黄芩、竹茹、半夏、枳实、陈皮、茯苓及碧玉散，故有滑石、甘草、青黛。柴胡、黄连、白芍、茵陈均非本方药物：柴胡属小柴胡汤，黄连属泻心类，白芍柔肝，茵陈退黄。滑石、甘草即碧玉散，清利湿热导邪下行"},{"q":"《医便》中的五磨饮子是在四磨汤的基础上去掉人参，增加了什么药","o":["半夏、生姜","枳实、厚朴","旋覆花、代赭石","苏子、半夏","木香、枳实"],"a":4,"e":"五磨饮子由四磨汤去人参，加木香、枳实而成，行气降逆之力更增，主治气逆喘息。半夏、生姜、旋覆花、代赭石、苏子皆非五磨饮子新增之品，其中旋覆代赭汤方含代赭石、半夏，与本方不同。去人参者，恐其补气恋邪、碍气降逆"},{"q":"下列不属于一贯煎组成药物的是","o":["当归身","北沙参","生地黄","川楝子","熟地黄"],"a":4,"e":"一贯煎含北沙参、麦冬、当归身、生地黄、川楝子、枸杞子，滋阴疏肝，无熟地黄。熟地黄滋腻碍胃，与一贯煎滋阴疏肝、防助郁滞之旨不合；余药均为本方组成，体现滋阴柔肝、疏肝理气并用。川楝子疏肝泄热，枸杞子、生地滋养肝肾"},{"q":"具有涌吐痰涎宿食功用的方剂是","o":["安宫牛黄丸","瓜蒂散","保和丸","清气化痰丸","滚痰丸"],"a":1,"e":"瓜蒂散涌吐痰涎宿食，主治痰涎宿食壅滞胸脘，得吐则邪去。安宫牛黄丸清热开窍；保和丸消食和胃；清气化痰丸清热化痰；滚痰丸泻火逐痰，四方均无涌吐作用，与本方涌吐之法迥异。瓜蒂散服后当吐，中病即止，不可过量"},{"q":"丁香柿蒂汤主治","o":["外寒里饮之咳喘","上实下虚之痰喘","胃虚有热之呃逆","胃气虚寒之呃逆","肝经气滞寒凝证"],"a":3,"e":"丁香柿蒂汤温中益气、降逆止呃，主治胃气虚寒呃逆，见呃声低沉、气弱无力。胃虚有热呃逆用橘皮竹茹汤；外寒里饮咳喘小青龙汤；上实下虚痰喘苏子降气汤；肝经气滞寒凝非本方所主。丁香、柿蒂温中降逆，人参、生姜补虚和胃"},{"q":"川芎茶调散的主治证是","o":["风寒头痛","风热头痛","风湿头痛","风邪头痛","风痰头痛"],"a":3,"e":"川芎茶调散疏风止痛，主治风邪头痛，外感风邪循经上犯头目。风寒头痛、风热头痛、风湿头痛皆分型偏颇，本方集祛风药于一方，重在疏风止痛；风痰头痛多半夏白术天麻汤，非本方所主。本方用茶水送服，取茶之苦寒上行头目"},{"q":"下列方剂中，可以主治黄疸而见少阳证的是","o":["大柴胡汤","茵陈蒿汤","小柴胡汤","半夏厚朴汤","当归四逆汤"],"a":2,"e":"小柴胡汤和解少阳，可治黄疸而见少阳证者，见往来寒热、口苦、胁满。茵陈蒿汤清热利湿退黄但无少阳证；大柴胡汤治少阳阳明合病；半夏厚朴汤治梅核气；当归四逆汤温经养血，均非所宜。小柴胡汤去黄芪、生姜，加五味子、干姜"},{"q":"羌活胜湿汤证主治","o":["风寒湿痹","风湿热痹","顽痹","风湿犯表之痹证","外感风寒湿、里有蕴热证"],"a":3,"e":"羌活胜湿汤祛风胜湿，主治风湿犯表之痹证，见肩背痛、腰脊痛、一身尽痛。风寒湿痹、顽痹多独活寄生汤；风湿热痹宜清热祛湿；外感风寒湿、里有蕴热为九味羌活汤证，均非本方所主。本方羌活、独活祛风湿，川芎、甘草和血缓急"},{"q":"药物组成中不含有干姜的方剂","o":["四逆汤","吴茱萸汤","理中丸","回阳救急汤","半夏泻心汤"],"a":1,"e":"吴茱萸汤由吴茱萸、人参、生姜、大枣组成，温中补虚、降逆止呕，不含干姜。四逆汤、理中丸、回阳救急汤均用干姜温中；半夏泻心汤亦用干姜散结除痞，唯独吴茱萸汤用生姜不用干姜。生姜温胃止呕，吴茱萸、人参温中补虚"},{"q":"温燥伤肺轻证，治疗应首选的方剂是","o":["养阴清肺汤","清燥救肺汤","增液汤","桑杏汤","杏苏散"],"a":3,"e":"桑杏汤清宣温燥、润肺止咳，主治温燥伤肺轻证，见身热不甚、干咳无痰。养阴清肺汤治白喉；清燥救肺汤治温燥重证；增液汤润燥通便；杏苏散轻宣凉燥，本方为温燥轻证首选。本方桑叶、杏仁轻宣温燥，证轻故不用重剂"},{"q":"养心汤中君药是","o":["黄芪、人参","人参、当归","酸枣仁、黄连","人参、五味子","黄芪、远志"],"a":0,"e":"养心汤养心安神，君药黄芪、人参大补心气，气足则神安。酸枣仁、黄连非君药；五味子、远志、当归、柏子仁或为臣佐，重在益气养血安神；肉桂温阳，亦非君药，本方以补气为安神之本。黄芪、人参益气以生血，气旺则神明得养"},{"q":"以下关于阿胶鸡子黄汤的组成，表述错误的是","o":["钩藤、石决明","络石藤、茯神木","牡蛎、阿胶","鸡子黄、炙甘草","熟地、白芍"],"a":4,"e":"阿胶鸡子黄汤含阿胶、鸡子黄、生地、白芍、石决明、钩藤、牡蛎、络石藤、茯神木、炙甘草，无熟地。本方以生地滋阴养血、柔肝息风，熟地滋腻非本方所用，钩藤、石决明平肝，余组药物均确。生地、白芍滋阴柔肝，阿胶、鸡子黄养血息风"},{"q":"二陈汤主治","o":["风寒咳嗽","热痰咳嗽","燥痰咳嗽","湿痰咳嗽","寒饮咳嗽"],"a":3,"e":"二陈汤燥湿化痰、理气和中，主治湿痰咳嗽，痰多色白易咯。风寒咳嗽麻黄汤；热痰咳嗽清气化痰丸；燥痰咳嗽贝母瓜蒌散；寒饮咳嗽小青龙汤，本方为治湿痰之基础方。半夏燥湿化痰，橘红理气行痰，茯苓健脾渗湿"},{"q":"体现“以泻代清”治法的方剂是","o":["凉膈散","泻白散","清胃散","导赤散","泻黄散"],"a":0,"e":"凉膈散以大黄、芒硝泻下，配栀子、黄芩、连翘、竹叶清上，体现以泻代清、上病下取。泻白散清泻肺热；清胃散清胃凉血；导赤散清心利水；泻黄散泻脾胃伏火，皆无以泻代清之配伍。连翘、大黄相配，使上焦之热从下而去"},{"q":"健脾丸的君药是","o":["人参、山药、白术","人参、白术、茯苓","白术、茯苓、山药","人参、白术、茯苓、甘草","茯苓、人参、甘草、山药"],"a":1,"e":"健脾丸健脾和胃、消食止泻，君药人参、白术、茯苓益气健脾以治本，佐以消食化积。山药、甘草为佐助；本方以四君为基础重在健脾，与单纯消食之保和丸不同，故君为参、术、苓。消食药如山楂、神曲、麦芽，健脾与消食并行"},{"q":"具有滋阴润肺，益气补脾作用的方剂是","o":["生脉散","增液汤","琼玉膏","玉液汤","麦门冬汤"],"a":2,"e":"琼玉膏滋阴润肺、益气补脾，主治虚劳干咳、咯血，见咳逆上气。生脉散益气养阴；增液汤增液润燥；玉液汤益气滋阴治消渴；麦门冬汤滋养肺胃、降逆下气，功用各有侧重。本方生地、人参、茯苓、白蜜，润肺补脾兼顾"},{"q":"清营汤中具有透热转气作用的药物是","o":["金银花、连翘","水牛角、黄连","牡丹皮、丹参","麦门冬、玄参","生地黄、竹叶"],"a":0,"e":"清营汤中金银花、连翘透热转气，使营分热邪转出气分而解，为透热外出之要药。水牛角、黄连清营解毒；丹皮、丹参凉血散瘀；麦冬、玄参、生地养阴清热，均无透热转气之专功。热入营分，透热转气可使邪从气分而解"},{"q":"枳实导滞丸主治","o":["湿热食积","脾虚食积","食积证","酒积伤脾","痢疾，食积"],"a":0,"e":"枳实导滞丸消积导滞、清利湿热，主治湿热食积，见脘腹胀痛、下痢泄泻。脾虚食积健脾丸；单纯食积保和丸；酒积伤脾葛花解酲汤；痢疾食积木香槟榔丸，本方消积兼清利湿热。大黄、枳实行气泻热，黄连、黄芩清热燥湿"},{"q":"左归丸中配伍鹿角胶的作用是","o":["滋阴","补阳","阳中求阴","阴中求阳","阴阳并补"],"a":2,"e":"左归丸纯甘壮水、滋阴补肾，配鹿角胶、菟丝子补阳，于阴中求阳，寓阳中求阴之意。阴中求阳为右归丸配伍；滋阴是本方主功而非鹿角胶之特指；阴阳并补非纯滋阴剂所取，本方重在填补肾阴。鹿角胶温阳益精，龟板胶滋阴，二胶并补精髓"},{"q":"温经汤主治证的病机是","o":["脾气亏虚，冲脉不固","肝肾两虚，冲脉不固","冲任虚寒，瘀血阻滞","冲任虚损，瘀血阻滞","寒凝血瘀，湿阻胞宫"],"a":2,"e":"温经汤温经散寒、养血祛瘀，病机为冲任虚寒、瘀血阻滞，见月经不调、小腹冷痛。脾气虚冲脉不固属固冲汤；肝肾两虚冲任不固近寿胎丸；冲任虚损、寒凝血瘀湿阻均非本方确切病机。本方吴茱萸、桂枝温经散寒，当归、芍药养血"},{"q":"小建中汤组成中用量为六两的药物是","o":["桂枝","生姜","大枣","芍药","饴糖"],"a":3,"e":"小建中汤重用芍药六两，与桂枝等量，酸甘化阴、缓急止痛，温中补虚。桂枝、生姜各三两，大枣十二枚，饴糖一升，皆非六两之数；本方倍芍药之意在于缓急和里，非发汗解表。桂枝三两、芍药六两，倍芍药以缓急止痛"},{"q":"大秦艽汤与消风散配伍中体现“治风先治血，血行风自灭”之理的药物是","o":["生地","当归","白芍","熟地","川芎"],"a":1,"e":"大秦艽汤与消风散均配当归养血活血，体现治风先治血、血行风自灭之理。生地、白芍滋阴养血；熟地滋补肾阴；川芎行气活血，虽亦入血分，但非两方共取治风先治血之义者，当推当归。两方均以当归养血，配生地、川芎助血行"},{"q":"桑螵蛸散的功用是","o":["温补肾阳，涩精止遗","温肾祛寒，缩尿止遗","固冲摄血，益气健脾","涩肠固脱，温补脾肾","调补心肾，涩精止遗"],"a":4,"e":"桑螵蛸散调补心肾、涩精止遗，主治心肾两虚尿频遗尿，兼心神恍惚、健忘。温肾祛寒、缩尿止遗为缩泉丸；固冲摄血、益气健脾属固冲汤；涩肠固脱真人养脏汤，皆非心肾同调之剂。龙骨、龟板固涩，远志、菖蒲交通心肾"},{"q":"理气化痰，清胆和胃为哪首方剂的功用","o":["清气化痰丸","贝母瓜蒌散","温胆汤","二陈汤","茯苓丸"],"a":2,"e":"温胆汤理气化痰、清胆和胃，主治胆郁痰扰，见胆怯易惊、失眠多梦。清气化痰丸清热化痰；贝母瓜蒌散润燥化痰；二陈汤燥湿化痰；茯苓丸燥湿行气软坚，无清胆和胃之功。半夏、竹茹、枳实、陈皮，理气化痰清胆和胃"},{"q":"朱砂安神丸服用方法为","o":["作汤剂，朱砂也入药一起煎煮","作丸剂，久服","作丸剂，多服","临睡前温开水送服","没有禁忌"],"a":3,"e":"朱砂安神丸镇心安神、清热养血，原方临睡前温开水送服，使药力专于安神。朱砂不可入煎；本方作丸剂不宜久服多服，因朱砂含汞；无禁忌之说更误，服法与禁忌皆当注意。磁石、朱砂镇心安神，生地、当归养血清热"},{"q":"六味地黄丸中的君药是","o":["山萸肉","山药","熟地黄","茯苓","牡丹皮"],"a":2,"e":"六味地黄丸熟地黄滋阴补肾、填精益髓为君，重在补肾阴。山萸肉补养肝肾、山药补益脾阴为臣；茯苓渗脾湿、泽泻泄肾浊、牡丹皮凉肝火为三泻之佐，均非君药。熟地八两为君，山萸肉、山药各四两为臣"},{"q":"逍遥散中配伍生姜的意义是","o":["温中散寒，健脾和中","辛温解表，散寒除湿","降逆和中，辛散达郁","温肺化饮，散寒止咳","补脾和胃，化气生津"],"a":2,"e":"逍遥散中生姜降逆和中、辛散达郁，助柴胡疏肝，兼和胃止呕。温中散寒、健脾和中非生姜在此主功；解表散寒除湿、温肺化饮皆非本方配伍意义；补脾和胃、化气生津属它药，本方重在疏肝。柴胡疏肝解郁，当归、白芍养血柔肝，白术健脾"},{"q":"清胃散的功用是","o":["清胃泻火","清胃滋阴","清胃养血","清胃凉血","清泻胃热"],"a":3,"e":"清胃散清胃凉血，主治胃火牙痛，见牙痛牵引头痛、面颊发热。清胃泻火表述不确；清胃滋阴、养血非本方；清泻胃热虽近，但本方兼顾凉血，以升麻、黄连、丹皮、生地合用，故功用为清胃凉血。生地凉血，丹皮清肝火，当归养血，黄连清胃"},{"q":"不属于青蒿鳖甲汤主治证候的是","o":["脉细数","舌红少苔","热退无汗","夜热早凉","身热夜甚"],"a":4,"e":"青蒿鳖甲汤养阴透热，主温病后期夜热早凉、热退无汗、舌红少苔、脉细数。身热夜甚为清营汤热入营分之象，且伴神昏谵语，非本方主治；本方以鳖甲滋阴、青蒿透热，重在透邪外出。青蒿透热外出，鳖甲滋阴入里，一透一滋"},{"q":"肉桂在真人养脏汤中的作用是","o":["温经散寒","温肾纳气","温通经脉","温阳化气","温肾暖脾"],"a":4,"e":"真人养脏汤中肉桂温肾暖脾，助罂粟壳、诃子等涩肠止泻，治脾肾虚寒之久泻久痢。温经散寒、温通经脉非其在方中主功；温肾纳气、温阳化气亦非本方配伍目的，本方重在温补固涩。肉桂温肾暖脾以助运化，诃子、罂粟壳涩肠"},{"q":"原书服法要求“香气大出，即取服，勿过煮”的方剂是","o":["桑菊饮","香薷散","银翘散","香苏散","葱豉桔梗汤"],"a":2,"e":"银翘散原方煎法强调香气大出即取服、勿过煮，以免辛散清热之力受损。桑菊饮、香薷散、香苏散、葱豉桔梗汤均无此特殊服法，本方为辛凉平剂，煎煮时间宜短以存其轻宣之性。本方连翘、金银花芳香辛散，久煮则效减"},{"q":"黄龙汤与温脾汤共有的药物是","o":["大黄、芒硝","枳实、芍药","干姜、人参","当归、升麻","厚朴、甘草"],"a":0,"e":"黄龙汤与温脾汤均含大黄、芒硝以泻下通便，主治腑实便秘。枳实、芍药仅黄龙汤有；干姜、人参温脾汤有而黄龙汤无；当归、升麻、厚朴非两方共有，一为攻下兼补气血，一为温下。黄龙汤益气养血，温脾汤温阳攻下，同用硝黄"},{"q":"小蓟饮子与导赤散共有的药物是","o":["生地、木通","当归、山栀子","滑石、甘草","小蓟、藕节","竹叶、车前子"],"a":0,"e":"小蓟饮子与导赤散均含生地、木通，共奏凉血利水通淋之效。小蓟、藕节、山栀子为小蓟饮子独有，重在凉血止血；竹叶、甘草虽两方均有，但生地、木通为两方共有之主药，故为首选。导赤散清心利水，小蓟饮子凉血止血"},{"q":"不属于竹叶石膏汤组成药物的是","o":["半夏","人参","炙甘草","天门冬","麦门冬"],"a":3,"e":"竹叶石膏汤含竹叶、石膏、半夏、人参、麦冬、甘草、粳米，清热生津、益气和胃，无天门冬。天门冬滋阴润燥之力强，非本方所有；余药均为原方组成，半夏降逆和胃，人参益气。半夏、人参、炙甘草、粳米，益气和胃生津"},{"q":"参苓白术散证的病机是","o":["阳虚水泛","脾胃气虚","寒湿困脾","肺肾气虚","脾胃气虚，湿自内生"],"a":4,"e":"参苓白术散病机为脾胃气虚、湿自内生，故益气健脾兼渗湿止泻。单纯脾胃气虚为四君子汤证；阳虚水泛真武汤；寒湿困脾平胃散类；肺肾气虚非本方，本方体现培土生金之法。参苓白术散兼能渗湿止泻，体现培土生金"},{"q":"用于气虚发热，体现甘温除热法的方剂是","o":["补中益气汤","参苓白术散","人参蛤蚧散","生脉散","四君子汤"],"a":0,"e":"补中益气汤补中益气、升阳举陷，体现甘温除热，治脾胃气虚、阳气下陷之发热。参苓白术散健脾渗湿；生脉散益气养阴；四君子汤平补脾胃；人参蛤蚧散补肺益肾，均非甘温除热之剂。黄芪、人参、甘草甘温益气，升麻、柴胡升阳"},{"q":"消食剂中用药体现“通因通用”的代表方剂是","o":["保和丸","木香槟榔丸","葛花解酲汤","健脾丸","木香导滞丸"],"a":1,"e":"木香槟榔丸行气攻积，治湿热积滞之痢疾、食积，以通治通，属通因通用。保和丸消食和胃；健脾丸健脾消食；葛花解酲汤解酒化湿；木香导滞丸行气导滞，本方行气攻下之力最著。木香、槟榔行气导滞，牵牛、大黄攻积泄热"},{"q":"滚痰丸属于的何类方剂","o":["燥湿化痰剂","清热化痰剂","温化寒痰剂","润燥化痰剂","治风化痰剂"],"a":1,"e":"滚痰丸泻火逐痰，主治实热老痰、癫狂惊悸，属清热化痰剂。燥湿化痰二陈汤；温化寒痰苓甘五味姜辛汤；润燥化痰贝母瓜蒌散；治风化痰半夏白术天麻汤，分类各别。滚痰丸以礞石、大黄、黄芩泻火逐痰"},{"q":"桑菊饮的功用是","o":["辛凉透表，清热解毒","疏风清热，宣肺止咳","辛凉疏表，清肺平喘","辛凉宣肺，清热解毒","宣利肺气，疏风止咳"],"a":1,"e":"桑菊饮疏风清热、宣肺止咳，为辛凉轻剂，主治风温初起、但咳。辛凉透表、清热解毒为银翘散；辛凉疏表、清肺平喘属麻杏甘石汤；宣利肺气、疏风止咳表述不确，本方重在宣肺止咳。桑菊饮以桑叶、菊花为君，重在宣肺止咳"},{"q":"主治肝郁血虚脾弱证的方剂是","o":["小柴胡汤","龙胆泻肝汤","逍遥散","归脾汤","补中益气汤"],"a":2,"e":"逍遥散疏肝解郁、养血健脾，主治肝郁血虚脾弱，见胁痛、神疲食少。小柴胡汤和解少阳；龙胆泻肝汤清肝胆实火；归脾汤治心脾两虚；补中益气汤治气虚下陷，均非肝郁血虚脾弱。柴胡、当归、白芍疏肝养血，白术、茯苓健脾"},{"q":"属于六味地黄丸中“三泻”的药物是","o":["茯苓、泽泻、山茱萸","泽泻、牡丹皮、熟地黄","山药、茯苓、泽泻","茯苓、泽泻、牡丹皮","山茱萸、山药、泽泻"],"a":3,"e":"六味地黄丸三泻为茯苓、泽泻、牡丹皮，分别淡渗脾湿、清泄肾浊、清泄肝火。熟地、山茱萸、山药为三补，故含山茱萸、熟地、山药之项均非三泻，三补三泻相反相成。三泻渗湿泄浊凉血，与三补相制，补而不滞"},{"q":"下列各项中，属于肾著汤药物组成的是","o":["杜仲","干姜","生姜","补骨脂","核桃仁"],"a":1,"e":"肾著汤即甘草干姜茯苓白术汤，含干姜温中散寒，主治寒湿腰痛。杜仲、补骨脂、核桃仁补肾强腰；生姜解表散寒，皆非肾著汤药物，本方重在温脾散寒除湿以止腰痛。干姜、白术温脾燥湿，茯苓渗湿，甘草和中"},{"q":"凉开剂中长于镇痉息风的是","o":["安宫牛黄丸","紫雪","苏合香丸","抱龙丸","紫金锭"],"a":1,"e":"紫雪清热开窍、息风止痉，凉开剂中长于镇痉息风，主治热盛动风。安宫牛黄丸长于清热解毒；苏合香丸属温开；抱龙丸、紫金锭化痰开窍，均无息风止痉之长。紫雪含石膏、寒水石、羚羊角，清热息风"},{"q":"琼玉膏的功用是","o":["滋阴润肺，益气补脾","养阴清肺，解毒利咽","润肺益胃，降逆下气","滋阴填精，益气壮阳","滋阴益气，固肾止渴"],"a":0,"e":"琼玉膏滋阴润肺、益气补脾，主治虚劳干咳、咯血，见咳嗽气短。养阴清肺、解毒利咽为养阴清肺汤；润肺益胃、降逆下气是麦门冬汤；滋阴填精、益气壮阳属龟鹿二仙胶，皆非本方。人参、白蜜益气润燥，生地滋阴，茯苓健脾"},{"q":"《医方集解》中记载的苏子降气汤与《局方》中记载的苏子降气汤的变化为","o":["去当归加枳实","去肉桂加沉香","去半夏加百部","去厚朴加麻黄","去前胡加柴胡"],"a":1,"e":"《医方集解》所载苏子降气汤去肉桂、加沉香，以增强降逆纳气之功，治上实下虚喘咳。去当归加枳实、去半夏加百部、去厚朴加麻黄、去前胡加柴胡皆非两书之变化，本方变化重在降气。沉香降气纳肾，较肉桂之温补更宜于气逆"},{"q":"定喘汤的功用为","o":["降逆化痰，益气和胃","宣肺降气，清热化痰","宣肺止咳，降气定喘","降气平喘，祛痰止咳","定喘止咳，宣肺降气"],"a":1,"e":"定喘汤宣肺降气、清热化痰，主治风寒外束、痰热内蕴之哮喘，见咳喘痰多。降逆化痰、益气和胃是旋覆代赭汤；降气平喘、祛痰止咳为苏子降气汤；余项非本方规范功用，本方兼清化痰热。白果、麻黄宣降肺气，黄芩、桑皮清化热痰"},{"q":"杏苏散的功用是","o":["清宣温燥，润肺止咳","清燥润肺，养阴益气","清热燥湿，调和气血","轻宣凉燥，理肺化痰","清养肺胃，降逆下气"],"a":3,"e":"杏苏散轻宣凉燥、理肺化痰，主治外感凉燥，见头微痛、恶寒、咳嗽痰稀。清宣温燥、润肺止咳是桑杏汤；清燥润肺、养阴益气属清燥救肺汤；清养肺胃、降逆下气为麦门冬汤。杏苏散以杏仁、苏叶轻宣凉燥，前胡、桔梗化痰"},{"q":"主治喑痱的方剂是","o":["大补阴丸","加减复脉汤","右归丸","地黄饮子","龟鹿二仙胶"],"a":3,"e":"地黄饮子滋肾阴、补肾阳、开窍化痰，主治喑痱，见舌强不能言、足废不能用。大补阴丸滋阴降火；加减复脉汤滋阴养血；右归丸温补肾阳；龟鹿二仙胶填精补髓，均不治喑痱。地黄饮子用薄荷、石菖蒲、远志化痰开窍"},{"q":"患者体倦气短，口渴多汗，咽干舌红，脉虚，宜选用","o":["补中益气汤","玉屏风散","人参蛤蚧散","四君子汤","生脉散"],"a":4,"e":"生脉散益气养阴、敛汗生脉，主治气阴两伤之体倦气短、口渴多汗、咽干舌红、脉虚。补中益气汤治气虚发热；玉屏风散益气固表止汗；四君子汤健脾益气；人参蛤蚧散补肺益肾。五味子敛肺生津，麦冬、人参益气养阴"},{"q":"补中益气汤中的君药是","o":["白术","黄芪","甘草","当归","人参"],"a":1,"e":"补中益气汤黄芪大补脾肺元气、升阳举陷为君，为益气升阳之要药。白术健脾燥湿、甘草益气和中、人参补气、当归养血，皆为臣佐，助君药补中益气，非升阳举陷之主。黄芪用量独重，益气升阳，故为君药"},{"q":"大定风珠的功用是","o":["凉肝息风","镇肝息风","滋阴息风","滋阴养血","潜阳息风"],"a":2,"e":"大定风珠滋阴息风，主治温病后期、阴虚风动，见手足瘛疭、脉气虚弱。凉肝息风属羚角钩藤汤；镇肝息风属镇肝熄风汤；滋阴养血、潜阳息风非本方规范功用，本方纯以滋阴息风。龟板、鳖甲、阿胶、鸡子黄滋阴养血息风"},{"q":"慢性痢疾属湿热积滞者，宜选用","o":["保和丸","木香槟榔丸","木香导滞丸","枳实导滞丸","健脾丸"],"a":3,"e":"枳实导滞丸消积导滞、清利湿热，主治湿热积滞之痢疾，见下痢腹痛、里急后重。保和丸消食和胃；木香槟榔丸行气攻积；木香导滞丸行气导滞；健脾丸健脾消食，本方消积兼清热。黄连、黄芩清热燥湿，枳实、大黄消积导滞"},{"q":"玉屏风散治汗出的机制是","o":["祛风散邪","敛汗固表","益气解表","益气固表","调和营卫"],"a":3,"e":"玉屏风散益气固表止汗，治表虚自汗、恶风，易感风邪。祛风散邪非本方；敛汗固表为牡蛎散，主盗汗；益气解表属败毒散类；调和营卫属桂枝汤，本方重在补气固表。黄芪、白术、防风益气固表，卫外得固则汗止"},{"q":"下列不含人参、五味子的方剂是","o":["生脉散","天王补心丹","琼玉膏","回阳救急汤","石斛夜光丸"],"a":2,"e":"琼玉膏含人参、生地、茯苓、蜂蜜，滋阴润肺、益气补脾，不含五味子。生脉散、天王补心丹、回阳救急汤、石斛夜光丸均含人参、五味子，五味子敛肺滋肾，非本方所用。五味子敛肺滋肾、生津收汗，为生脉散之要药"},{"q":"治疗痰涎壅盛于上，肾阳不足于下的喘咳应选用","o":["苏子降气汤","定喘汤","麻黄汤","小青龙汤","都气丸"],"a":0,"e":"苏子降气汤降气平喘、祛痰止咳，主治上实下虚之喘咳，痰涎壅盛于上、肾阳不足于下。定喘汤宣肺清热；小青龙汤解表化饮；麻黄汤风寒表实；都气丸补肾纳气，均非上实下虚之治。本方苏子、半夏降上实，肉桂、当归温下虚"},{"q":"麻黄杏仁甘草石膏汤中的君药是","o":["麻黄","杏仁","石膏","麻黄、石膏","麻黄、杏仁"],"a":3,"e":"麻杏甘石汤麻黄宣肺平喘、石膏清泄肺热，二者相制相成，共为君药。杏仁降肺气为臣；炙甘草调和诸药。单以麻黄或石膏为君均不全面，本方重在清宣肺热而平喘。麻黄宣肺，石膏清热，相须为用，故共为君"},{"q":"十枣汤中善泻脏腑水邪的药是","o":["甘遂","大戟","商陆","芫花","牵牛"],"a":1,"e":"十枣汤中大戟善泻脏腑水邪，甘遂善行经隧之水，芫花善消胸胁伏饮，三药各有所长。商陆、牵牛虽亦逐水，但非十枣汤药物，故泻脏腑水邪当推大戟。十枣汤以大枣十枚煎汤送服，缓峻药之毒；芫花、甘遂、大戟各有所主"},{"q":"下列哪项不是“十剂”中的内容","o":["轻重","滑涩","温清","补泄","宣通"],"a":2,"e":"十剂为宣、通、补、泄、轻、重、滑、涩、燥、湿，无温清。轻重、滑涩、补泄、宣通皆在其列，温清属后世药性理论，不在十剂内容，十剂重在概括方剂功用。宣通、补泄、轻重、滑涩、燥湿，合为十剂"},{"q":"下列关于旋覆代赭汤的说法，错误的是","o":["旋覆花降逆止嗳","代赭石善镇冲逆","生姜温中补虚","半夏祛痰散结","参枣草补脾胃之气"],"a":2,"e":"旋覆代赭汤生姜和胃止呕、温胃散饮，助降逆止嗳，非温中补虚。旋覆花降逆止嗳、代赭石镇冲逆、半夏祛痰散结、参枣草补脾胃，表述均确，唯生姜补虚之说不当。代赭石质重镇逆，旋覆花降气化痰，半夏散结"},{"q":"桂枝汤中桂枝与芍药的用量比例是","o":["2∶1","1∶2","3∶2","2∶3","1∶1"],"a":4,"e":"桂枝汤桂枝、芍药各三两，用量为一比一，一散一收，调和营卫，主治外感风寒、营卫不和之汗出恶风。二比一、一比二、三比二、二比三均非原方用量比例，桂芍等量是本方调和营卫之关键。原方桂枝、芍药各三两，等量相配以和营卫"},{"q":"玉屏风散证汗出的病机是","o":["卫气虚弱，不能固表","营卫不和","外感风寒","暑热耗气伤阴","脾胃气虚，阳浮于外"],"a":0,"e":"玉屏风散卫气虚弱、不能固表，故自汗恶风、易感风邪。营卫不和属桂枝汤；外感风寒为麻黄汤；暑热耗气伤阴属生脉散；脾胃气虚、阳浮于外非本方病机，本方重在益气固表。防风、黄芪、白术同用，固表而不留邪"},{"q":"凉膈散原方用量最大的药物是","o":["大黄","竹叶","连翘","栀子","黄芩"],"a":2,"e":"凉膈散连翘用量最大，轻宣透上、清热解毒，为治上焦热盛之要药。大黄、芒硝泻下，栀子、黄芩清热，竹叶清心，用量皆不及连翘，本方以泻下清上体现以泻代清。连翘用量独重，且先煎久煮，轻宣上焦"},{"q":"茵陈蒿汤中，泻热逐瘀且通便的药物是","o":["栀子","芒硝","茵陈","大黄","桃仁"],"a":3,"e":"茵陈蒿汤大黄泻热逐瘀、通利大便，使湿热瘀滞从大便而去，为治阳黄之要药。栀子通泄三焦；茵陈清热利湿退黄；芒硝、桃仁非本方药物，故泻热逐瘀通便当推大黄。茵陈蒿汤三药合用，湿热从小便、大便分消"},{"q":"具有敛阴止汗，益气固表功用的方剂是","o":["玉屏风散","牡蛎散","当归六黄汤","知柏地黄汤","补中益气汤"],"a":1,"e":"牡蛎散敛阴止汗、益气固表，主治体虚自汗盗汗，见汗出、心悸、气短。玉屏风散益气固表但无敛阴；当归六黄汤滋阴泻火；知柏地黄汤滋阴降火；补中益气汤补中升阳，功各有偏。牡蛎、黄芪益气固表，麻黄根、浮小麦敛汗"},{"q":"六味地黄丸的主治证是","o":["肝阴虚证","心阴虚证","脾阴虚证","肺阴虚证","肾阴虚证"],"a":4,"e":"六味地黄丸滋补肾阴，主治肾阴虚证，见腰膝酸软、头晕耳鸣、盗汗遗精。肝阴虚、心阴虚、脾阴虚、肺阴虚各有专方，非本方所主，本方为滋补肾阴之基础方。六味丸三补三泻，以补肾阴为主，兼补肝脾"},{"q":"治疗外感温燥证宜首选的方剂是","o":["麻黄汤","桂枝汤","桑杏汤","杏苏散","桑菊饮"],"a":2,"e":"桑杏汤清宣温燥、润肺止咳，为外感温燥轻证首选，见身热不甚、干咳无痰。麻黄汤、桂枝汤治风寒；杏苏散治凉燥；桑菊饮治风温初起，皆非温燥轻证之剂。桑杏汤证燥邪轻浅，故以轻宣润肺为法。本方为轻宣温燥之代表方"},{"q":"左金丸中黄连与吴茱萸的配伍比例是","o":["1∶1","2∶1","5∶1","6∶1","7∶1"],"a":3,"e":"左金丸黄连、吴茱萸用量六比一，清肝泻火、降逆止呕，主治肝火犯胃。一比一、二比一、五比一、七比一均非原方配伍比例，重用黄连意在清肝火，少佐吴茱萸降逆和胃。黄连六两、吴茱萸一两，辛开苦降，肝胃并治"},{"q":"温胆汤之功用不包括","o":["理气","化痰","温胆","和胃","清胆"],"a":2,"e":"温胆汤理气化痰、清胆和胃，功用包括理气、化痰、清胆、和胃，不包括温胆。本方虽名温胆，实无温胆之药，方名寓温养胆气之意，主治胆郁痰扰之失眠惊悸。半夏、陈皮、茯苓、甘草即二陈汤，理气化痰"},{"q":"补天大造丸的功用主治是","o":["养肝敛阴","补五脏虚损","涩精止遗","脾胃气虚","气阴两虚"],"a":1,"e":"补天大造丸补五脏虚损，主治虚劳，见气血亏虚、形体消瘦。养肝敛阴、涩精止遗、气阴两虚、脾胃气虚均非其功用主治的概括，本方重在补益五脏。本方集人参、黄芪、熟地、当归等补五脏气血，主治虚劳诸损"},{"q":"小青龙汤中的君药是","o":["桂枝、白芍","干姜、细辛","干姜、半夏","麻黄、桂枝","桂枝、干姜"],"a":3,"e":"小青龙汤麻黄、桂枝解表散寒、宣肺平喘为君，主治外寒内饮之咳喘。干姜、细辛温化寒饮为臣；半夏降逆；白芍、五味子敛肺，均非君药，本方重在散寒化饮。麻黄、桂枝发汗散寒，杏仁、甘草宣肺平喘"},{"q":"黄土汤与理中丸共有的药物是","o":["人参","白术","干姜","黄芩","附子"],"a":1,"e":"黄土汤与理中丸均含白术、甘草，共奏健脾之举。人参、干姜仅理中丸有；附子、黄芩仅黄土汤有；灶心土、阿胶、生地亦黄土汤独有，非两方共有，故白术为共有药物。黄土汤温阳健脾、养血止血，理中丸温中祛寒"},{"q":"十灰散与槐花散共有的药物是","o":["槐花","侧柏叶","小蓟","大蓟","山栀子"],"a":1,"e":"十灰散与槐花散均含侧柏叶，凉血止血。槐花仅槐花散有；小蓟、大蓟、山栀子为十灰散所有，槐花散无；荆芥穗、枳壳仅槐花散有，两方虽均止血而配伍不同。十灰散凉血止血，槐花散清肠疏风止血。两方均入血分以止血"},{"q":"以下关于大定风珠的组成，表述错误的是","o":["鸡子黄、五味子","阿胶、熟地","白芍、麦冬","龟板、鳖甲","牡蛎、麻仁"],"a":1,"e":"大定风珠含阿胶、鸡子黄、龟板、鳖甲、白芍、麦冬、干地黄、麻仁、五味子、牡蛎、炙甘草，滋阴息风，无熟地黄。本方用地黄为干地黄以滋阴，熟地黄非本方药物，余组药物均确。鸡子黄、阿胶血肉有情，滋阴息风，龟鳖甲潜阳"},{"q":"玉真散的功用是","o":["祛风除湿，定搐止痉","祛风除湿，通络止痉","祛风化痰，定搐止痉","祛风化痰，通络止痉","祛风散邪，化痰止痉"],"a":2,"e":"玉真散祛风化痰、定搐止痉，主治破伤风，见牙关紧闭、角弓反张。祛风除湿、通络止痉非本方之制，本方重在化痰定搐，无通络之功，与治风湿痹痛之剂不同。白附子、天南星祛风化痰，白芷、羌活祛风"},{"q":"二陈汤中的君药是","o":["橘红","半夏","茯苓","乌梅","炙甘草"],"a":1,"e":"二陈汤半夏燥湿化痰、理气和中为君，为治痰之要药。橘红理气化痰为臣；茯苓健脾渗湿；乌梅收敛肺气；甘草调和，皆非君药，本方燥湿化痰以治湿痰咳嗽。半夏辛温性燥，善燥湿化痰，故为君药。橘红、茯苓、乌梅皆辅半夏化痰"},{"q":"大黄牡丹汤和桃核承气汤两方组成中均含有的药物是","o":["大黄、桃仁、甘草","大黄、芒硝、甘草","大黄、赤芍、甘草","大黄、芒硝、桃仁","大黄、芒硝、赤芍"],"a":3,"e":"大黄牡丹汤与桃核承气汤均含大黄、芒硝、桃仁，共奏泻热逐瘀之功。甘草仅桃核承气汤有；赤芍两方均无；桂枝、当归亦非两方共有，故大黄、芒硝、桃仁为共有药物。大黄牡丹汤治肠痈，桃核承气汤治下焦蓄血"},{"q":"金锁固精丸的主要功用是","o":["涩精止遗","固脬缩尿","固经止血","收涩止带","固表止汗"],"a":0,"e":"金锁固精丸涩精止遗，主治肾虚不固之遗精滑泄，见腰膝酸软、耳鸣。固脬缩尿属缩泉丸；固经止血属固经丸；收涩止带完带汤；固表止汗玉屏风散、牡蛎散，功用各别。金锁固精丸煅龙骨、牡蛎涩精，沙苑子补肾"},{"q":"竹叶石膏汤的主治证是","o":["暑湿证","气分热盛证","暑热气津两伤证","暑病余热未清，气阴两伤证","气分热盛，气津两伤证"],"a":3,"e":"竹叶石膏汤清热生津、益气和胃，主治暑病余热未清、气阴两伤，见身热多汗、气短神疲。暑湿证、气分热盛、暑热气津两伤等表述均非本方确切主治，本方清补兼施。竹叶、石膏清热生津，半夏、人参和胃益气"},{"q":"平胃散的主治病证是","o":["脾胃气虚证","脾胃气滞证","痰阻脾胃证","湿浊内停证","湿滞脾胃证"],"a":4,"e":"平胃散燥湿运脾、行气和胃，主治湿滞脾胃证，见脘腹胀满、苔白厚腻。脾胃气虚四君子汤；脾胃气滞多理气剂；痰阻脾胃、湿浊内停非其规范表述，本方为燥湿运脾之基础方。苍术燥湿健脾，厚朴行气除满，陈皮理气"},{"q":"麻黄汤主治证候的病机是","o":["外感风寒，营卫不和","外感风寒湿邪，内有蕴热","风邪犯肺，肺失清肃","外感风寒，肺气失宣","外感风寒，水饮内停"],"a":3,"e":"麻黄汤发汗解表、宣肺平喘，病机为外感风寒、肺气失宣，见恶寒发热、无汗而喘。营卫不和属桂枝汤；风寒湿邪内有蕴热为九味羌活汤；风邪犯肺肺失清肃多桑菊饮；水饮内停小青龙汤。麻黄、桂枝发汗，杏仁、甘草宣肺平喘"},{"q":"痛泻要方主治之腹泻特点是","o":["泻必腹痛，泻后痛减","每于五更，定时而发","腹痛腹泻，久治不愈","大便带血，血色黯淡","泻下无度，里急后重"],"a":0,"e":"痛泻要方补脾柔肝，主治脾虚肝郁之痛泻，特点为泻必腹痛、泻后痛减。五更泄泻四神丸；腹痛腹泻久治不愈、便血黯淡、里急后重均非本方特征，本方重在柔肝缓急止痛。白术、白芍补脾柔肝，陈皮、防风疏肝理脾"},{"q":"健脾丸的功用是","o":["行气导滞，消食和胃","健脾和胃，消食止泻","补脾益气，消食止泻","健脾消积，行气和胃","消食和胃，健脾渗湿"],"a":1,"e":"健脾丸健脾和胃、消食止泻，主治脾虚食积，见食少难消、脘腹痞胀、大便溏薄。行气导滞、消食和胃偏保和丸；补脾益气、消食止泻未及和胃；消食和胃、健脾渗湿非规范表述。人参、白术、茯苓健脾，山楂、神曲消食"},{"q":"治疗肾虚便秘，首选方剂是","o":["济川煎","五仁丸","肾气丸","十枣汤","黄龙汤"],"a":0,"e":"济川煎温肾益精、润肠通便，主治肾虚便秘，见大便秘结、腰膝酸软、头目眩晕。五仁丸润肠；肾气丸温补肾阳；十枣汤逐水；黄龙汤泻下兼补气血，均非肾虚便秘之首选。肉苁蓉、当归温肾润肠，牛膝、泽泻引药下行"},{"q":"麦门冬汤的功用是","o":["养阴益胃，止咳化痰","养阴清肺，止咳化痰","滋养肺胃，降逆下气","滋养肺肾，降逆下气","养阴润肺，益胃生津"],"a":2,"e":"麦门冬汤滋养肺胃、降逆下气，主治肺痿及胃虚气逆，见咳唾涎沫、气逆呕吐。养阴益胃、止咳化痰不确；养阴清肺属养阴清肺汤；滋养肺肾非本方；养阴润肺、益胃生津未及降逆。半夏降逆下气，麦冬、沙参滋养肺胃"},{"q":"具有敛肺止咳，益气养阴功用的方剂是","o":["生脉散","泻白散","九仙散","小青龙汤","定喘汤"],"a":2,"e":"九仙散敛肺止咳、益气养阴，主治久咳肺虚，见咳嗽日久、气短懒言。生脉散益气养阴；泻白散泻肺清热；小青龙汤解表化饮；定喘汤宣肺清热，本方重在敛肺止咳。罂粟壳、五味子、乌梅敛肺止咳，人参、黄芪益气"},{"q":"白虎汤的功用是","o":["清热生津","清热，益气，生津","清热通络，和营卫","清热生津，益气和胃","清热益气，养阴生津"],"a":0,"e":"白虎汤清热生津，主治气分热盛，见壮热、大汗、烦渴、脉洪大。清热、益气、生津为竹叶石膏汤；清热通络和营卫属桂枝白虎汤；清热生津、益气和胃亦竹叶石膏汤之属。石膏、知母清热生津，粳米、甘草益胃"},{"q":"参苓白术散除益气健脾外兼有何功用","o":["补气升阳举陷","益气固表止汗","和胃渗湿保肺","消食理气导滞","补肺益肾止咳"],"a":2,"e":"参苓白术散益气健脾、渗湿止泻，兼和胃渗湿保肺，体现培土生金，主治脾虚湿盛。补气升阳举陷属补中益气汤；益气固表止汗玉屏风散；消食理气导滞健脾丸；补肺益肾止咳非本方。桔梗宣肺利气，载药上行以保肺，体现培土生金"},{"q":"组成药物中无茯苓的方剂是","o":["半夏厚朴汤","枳实消痞丸","厚朴温中汤","苏子降气汤","逍遥散"],"a":3,"e":"苏子降气汤不含茯苓，重在降气平喘、祛痰止咳。半夏厚朴汤、枳实消痞丸、厚朴温中汤、逍遥散均用茯苓健脾渗湿，茯苓健脾渗湿为四方共用之辅药，唯苏子降气汤不用。苏子降气汤以苏子、半夏降气化痰，肉桂温肾"},{"q":"葱豉桔梗汤的功用是","o":["解肌发汗","解肌清热","解肌透疹","疏风止痛","疏风清热"],"a":4,"e":"葱豉桔梗汤疏风清热，主治风温初起，见头痛、发热、咳嗽。解肌发汗、解肌清热、解肌透疹非本方；疏风止痛属川芎茶调散之类，本方以葱豉、桔梗、薄荷疏风清热。葱白、淡豆豉疏风，桔梗、薄荷、连翘清热"},{"q":"生化汤的功用是","o":["活血化瘀，行气止痛","温经散寒，祛瘀养血","养血活血，温经止痛","活血行气，温经止痛","活血祛瘀，通络止痛"],"a":2,"e":"生化汤养血活血、温经止痛，主治产后血虚寒凝、瘀血内阻，见恶露不行、小腹冷痛。活血化瘀、行气止痛近失笑散；温经散寒、祛瘀养血近温经汤；活血行气、温经止痛非本方规范表述。当归、川芎养血活血，炮姜、甘草温中止痛"},{"q":"清气化痰丸与温胆汤同用的药物是","o":["枳实","胆南星","甘草","黄芩","浙贝母"],"a":0,"e":"清气化痰丸与温胆汤均含枳实、半夏、陈皮、茯苓，行气化痰。胆南星、黄芩仅清气化痰丸有；浙贝母非两方共有；甘草仅温胆汤有，枳实为两方行气消痞之要药。清气化痰丸清热化痰，温胆汤清胆和胃"},{"q":"十灰散中用以凉血祛瘀，防血止留瘀的药物是","o":["牡丹皮","丹参","三七","当归","川芎"],"a":0,"e":"十灰散牡丹皮凉血祛瘀，使血止而不留瘀，体现止血不留瘀之制。三七、当归、丹参、川芎或活血或止血，非十灰散中防留瘀之专药，本方炒炭存性以增涩止血之力。牡丹皮、大蓟、小蓟凉血散瘀，棕榈炭涩止血"},{"q":"大定风珠配伍的君药是","o":["鸡子黄、熟地","阿胶、干地黄","鸡子黄、干地黄","阿胶、鸡子黄","阿胶、熟地"],"a":3,"e":"大定风珠君药阿胶、鸡子黄，滋阴养血、息风，主治阴虚风动。熟地非本方药物；干地黄、龟板、鳖甲为臣佐滋阴潜阳；白芍、麦冬养阴，均非君药，本方以血肉有情之品息风。阿胶、鸡子黄滋阴养血，为血肉有情之品"},{"q":"症见恶寒发热，呕吐泄泻，舌苔白腻者，治宜","o":["连朴饮","藿香正气散","甘露消毒丹","三仁汤","八正散"],"a":1,"e":"藿香正气散解表化湿、理气和中，主治外感风寒、内伤湿滞，见恶寒发热、呕吐泄泻、苔白腻。连朴饮清热化湿；甘露消毒丹利湿清热；三仁汤宣畅三焦；八正散清热利水通淋。藿香、紫苏、白芷解表，半夏、陈皮和胃止呕"},{"q":"吴茱萸汤的组成不包括","o":["吴茱萸","半夏","大枣","生姜","人参"],"a":1,"e":"吴茱萸汤由吴茱萸、人参、生姜、大枣组成，温中补虚、降逆止呕，不含半夏。半夏为降逆化痰要药，多用于小半夏汤、旋覆代赭汤、半夏泻心汤，非本方组成。吴茱萸温中，人参、大枣补虚，生姜温胃止呕"},{"q":"枳实消痞丸的功用为","o":["行气祛痰，健脾和胃","行气温中，燥湿除满","行气散结，降逆化痰","行气消痞，健脾和胃","行气降逆，化痰散结"],"a":3,"e":"枳实消痞丸行气消痞、健脾和胃，主治脾虚气滞、寒热互结之痞满。行气祛痰、健脾和胃非规范表述；行气温中、燥湿除满属厚朴温中汤；行气散结、降逆化痰属半夏厚朴汤。黄连、黄芩清热，干姜、人参温中，消痞和胃"},{"q":"既是治疗少阳病证之基础方，又是和解少阳法之代表方是","o":["逍遥散","半夏泻心汤","痛泻要方","小柴胡汤","大柴胡汤"],"a":3,"e":"小柴胡汤为治疗少阳病之基础方、和解少阳法之代表方，见往来寒热、口苦、胁满。逍遥散疏肝健脾；半夏泻心汤和胃消痞；痛泻要方补脾柔肝；大柴胡汤治少阳阳明合病。柴胡、黄芩和解少阳，人参、甘草扶正"},{"q":"朱砂安神丸与交泰丸具有的共同药物组成为","o":["当归","黄连","肉桂","茯神","朱砂"],"a":1,"e":"朱砂安神丸含黄连、朱砂、当归、生地、甘草，镇心安神、清热养血；交泰丸含黄连、肉桂，交通心肾，共同药物为黄连。朱砂仅前者有；肉桂仅交泰丸有；当归、茯神非两方共有。黄连苦寒清热，朱砂镇心，当归、生地养血"},{"q":"瓜蒌薤白白酒汤的功用为","o":["通阳散结，祛痰宽胸","通阳散结，下气祛痰","通阳散结，行气祛痰","温通心阳，下气祛痰","温通心阳，行气宽胸"],"a":2,"e":"瓜蒌薤白白酒汤通阳散结、行气祛痰，主治胸阳不振、痰气互结之胸痹，见胸闷胸痛。通阳散结、祛痰宽胸为瓜蒌薤白半夏汤；温通心阳非本方功用表述，本方重在通阳行气。瓜蒌、薤白通阳散结，白酒行气活血"},{"q":"败毒散组成中的人参属于","o":["君药","臣药","佐助药","佐制药","反佐药"],"a":2,"e":"败毒散人参益气扶正以助祛邪，为佐助药，防疏散伤正。君药羌活、独活；臣药防风、川芎、柴胡；桔梗、枳壳、前胡、茯苓、甘草或佐或使，人参非君、非反佐，体现扶正解表之法。人参扶正助祛邪，配羌活、独活散寒除湿"},{"q":"当归补血汤有，而四物汤没有的药是","o":["干地黄","黄芪","川芎","芍药","当归"],"a":1,"e":"当归补血汤含黄芪、当归，重在益气生血；四物汤含熟地、当归、白芍、川芎，重在养血和血。前者有而后者无者为黄芪，干地黄、川芎、芍药、当归皆四物汤所有。当归补血汤重用黄芪五倍于当归，益气生血"},{"q":"“每剂不过三钱，用生绢小袋盛之，煮作汤饮，随甘旨代茶水啜用，不宜煎熬太过”的用法出自于","o":["苓甘五味姜辛汤","三子养亲汤","半夏白术天麻汤","养阴清肺汤","半夏厚朴汤"],"a":1,"e":"三子养亲汤用法为每剂不过三钱，生绢小袋盛之煮作汤饮，代茶啜用，不宜煎熬太过，以免辛散走窜之性受损。苓甘五味姜辛汤、半夏白术天麻汤、养阴清肺汤、半夏厚朴汤均无此用法。三子养亲汤苏子、白芥子、莱菔子降气化痰"},{"q":"逍遥散与银翘散共用的药物是","o":["炙甘草","薄荷","白芍","柴胡","连翘"],"a":1,"e":"逍遥散与银翘散均用薄荷，辛散达郁、疏风清热。连翘、桔梗、金银花为银翘散独有；柴胡、白芍、白术、茯苓为逍遥散独有；两方甘草一炙一生，规格不同，故薄荷为明确同用之药。逍遥散疏肝养血，银翘散辛凉透表，共用薄荷"},{"q":"具有清热解毒，凉血散瘀功用的方剂是","o":["清营汤","黄连解毒汤","清瘟败毒饮","犀角地黄汤","白虎加桂枝汤"],"a":3,"e":"犀角地黄汤以犀角（水牛角代）清热凉血解毒，生地凉血养阴，赤芍、牡丹皮凉血散瘀，共奏清热解毒、凉血散瘀之功，主治热入血分证。清营汤功在清营解毒、透热养阴，主治热入营分；黄连解毒汤只泻火解毒，无凉血散瘀之力；清瘟败毒饮虽气血两清，重在清热解毒、凉血泻火而非散瘀"},{"q":"以下关于玉真散的药物组成描述正确的是","o":["防风、白芷、天麻、羌活、黑附子、天南星","防风、白芷、天麻、独活、黑附子、胆南星","防风、白芷、天麻、羌活、白附子、天南星","防风、白芷、天麻、羌活、白附子、胆南星","防风、白芷、天麻、独活、白附子、天南星"],"a":2,"e":"玉真散由防风、白芷、天麻、羌活、白附子、天南星组成，功能祛风化痰、定惊止痛，主治破伤风。白附子、天南星（生品）祛风化痰解痉，不可误作黑附子或胆南星；羌活与防风、白芷同搜风，独活善治下半身风湿，非本方所用。故凡含独活、黑附子、胆南星者均非其组成"},{"q":"济川煎主治证的病机关键在于","o":["阳虚冷结","肾虚精亏","肠燥津枯","血虚津少","津亏热结"],"a":1,"e":"济川煎主治肾虚便秘，病机关键为肾虚精亏、肠失濡润，兼阳气不足推动无力。方以肉苁蓉温肾益精、润肠通便，当归养血润肠，牛膝引药下行，泽泻、枳壳、升麻调气。肠燥津枯、血虚津少另有所主：麻子仁丸治胃肠燥热之脾约，四物类养血润燥；阳虚冷结当温阳散寒，津亏热结则宜清热生津"},{"q":"逍遥散中体现“补肝体”作用的药物是","o":["当归、芍药","柴胡、薄荷","柴胡、白芍","白术、茯苓","生姜、甘草"],"a":0,"e":"逍遥散中当归、白芍养血柔肝，滋补肝体以涵肝用，为“补肝体”之品；柴胡疏肝解郁、调畅气机，体现“疏肝用”。柴胡、薄荷偏于疏散，白术、茯苓健脾益气以实土御木，生姜、甘草调和脾胃。补肝体与疏肝用相配，使肝体得养、肝气得疏，是逍遥散调和肝脾的配伍核心"},{"q":"槐花散中用以疏风止血的药物是","o":["防风","升麻","羌活","柴胡","荆芥穗"],"a":4,"e":"槐花散中荆芥穗辛散疏风，且能止血，与槐花、侧柏叶相配，共奏清肠止血、疏风行气之功，主治肠风脏毒下血。防风虽亦疏风，但无止血之能，非本方所用；升麻、柴胡升提阳气，羌活祛风湿，均与本方疏风止血之旨不符。枳壳行气宽肠，使气行则血行，体现行气止血之法"},{"q":"阿胶鸡子黄汤配伍的臣药是","o":["阿胶、生地","阿胶、白芍","白芍、鸡子黄","生地、鸡子黄","白芍、生地"],"a":4,"e":"阿胶鸡子黄汤治阴虚风动，以阿胶、鸡子黄滋阴养血息风为君，生地、白芍助其凉血养阴、柔肝缓急，为臣药。白芍、鸡子黄中鸡子黄属君而非臣；阿胶、生地中阿胶为君；生地、鸡子黄分属臣与君，配伍不成对。唯白芍、生地同为臣药，助君滋阴息风，共治热盛伤阴、筋脉拘急"},{"q":"地黄饮子组成中有","o":["人参","白术","天麻","当归","石菖蒲"],"a":4,"e":"地黄饮子由熟地、山茱萸、肉苁蓉、巴戟天、附子、肉桂、麦冬、五味子、石菖蒲、远志、薄荷、茯苓、生姜、大枣组成，功能滋肾阴、补肾阳、开窍化痰，主治下元虚衰之瘖痱。石菖蒲开窍化痰、交通心肾，为方中要药；人参、白术、天麻、当归均非本方所有，其中天麻息风、当归养血，各有所主，不可混淆"},{"q":"黄芩、半夏、滑石同用的方剂是","o":["小柴胡汤","半夏泻心汤","蒿芩清胆汤","温脾汤","归脾汤"],"a":2,"e":"蒿芩清胆汤含青蒿、黄芩、半夏、竹茹、枳壳、陈皮、茯苓、滑石、甘草、青黛，功能清胆利湿、和胃化痰，主治少阳湿热证。方中黄芩清热燥湿，半夏、陈皮和胃化痰，滑石、茯苓利湿清热，故三味同用。小柴胡汤、半夏泻心汤虽用黄芩、半夏，但均无滑石；温脾汤、归脾汤则与清热利湿无涉"},{"q":"以下关于消风散的君药描述错误的是","o":["牛蒡子","苍术","荆芥","防风","蝉蜕"],"a":1,"e":"消风散以荆芥、防风、牛蒡子、蝉蜕为君，辛散透邪、疏风止痒，主治风湿浸淫之瘾疹、湿疹。苍术辛苦温燥，燥湿健脾，在方中为臣药以助祛湿，并非君药，故指苍术为君属错误。牛蒡子、蝉蜕疏散风热、透疹止痒，防风、荆芥祛风解表，四味共为君药，与苍术燥湿之力分工明确"},{"q":"属于六味地黄丸中“三补”的药物是","o":["熟地黄、山茱萸、牡丹皮","熟地黄、山药、泽泻","熟地黄、山茱萸、山药","山茱萸、山药、牡丹皮","茯苓、泽泻、牡丹皮"],"a":2,"e":"六味地黄丸以熟地黄滋阴补肾、填精益髓为君，山茱萸补养肝肾、涩精，山药补益脾肾、固精，三味合为“三补”。泽泻利湿泄浊、牡丹皮清泄相火、茯苓淡渗脾湿，是为“三泻”，泻中寓补。以补为主、补泻兼施，滋补而不留邪，是本方配伍特点。凡含泽泻、茯苓、牡丹皮者皆属三泻而非三补"},{"q":"不属于黄芪桂枝五物汤组成的是","o":["黄芪","芍药","桂枝","生姜","甘草"],"a":4,"e":"黄芪桂枝五物汤由黄芪、桂枝、芍药、生姜、大枣组成，功能益气温经、和血通痹，主治血痹肌肤麻木。方中无甘草，此点与桂枝汤、小建中汤不同。黄芪益气固表为君，桂枝、芍药调和营卫，生姜、大枣调和脾胃；若加甘草即成桂枝汤意，反失本方走表通痹之专，故甘草不在其列"},{"q":"治疗痰热咳嗽之代表方","o":["清气化痰丸","贝母瓜蒌散","苓甘五味姜辛汤","二陈汤","温胆汤"],"a":0,"e":"清气化痰丸以胆南星、黄芩清热化痰为君，瓜蒌仁、杏仁降气化痰，陈皮、半夏、茯苓理脾燥湿，枳实下气消痞，功能清热化痰、理气止咳，为治痰热咳嗽之代表方。贝母瓜蒌散润肺化痰，主治燥痰咳嗽；苓甘五味姜辛汤温肺化饮，二陈汤燥湿化痰，均治寒痰湿痰；温胆汤理气化痰、和胃利胆，非专治痰热咳喘"},{"q":"复元活血汤对大黄炮制的要求是","o":["先煎","后入","酒浸","炒炭","生用"],"a":2,"e":"复元活血汤中大黄用酒浸，意在借酒行药势，增强活血祛瘀、荡涤败血之功，以助柴胡、桃仁、红花逐瘀通络，主治跌打损伤、瘀血留于胁下。大黄生用泻下力峻，酒制则活血为主、泻下缓；先煎、后入、炒炭皆非本方炮制要求，炒炭偏于止血，与逐瘀止痛之旨相悖"},{"q":"玉屏风散中配伍黄芪的意义是","o":["补益正气，托脓外出","益气固表，行水消肿","内补脾肺，固表止汗","大补元气，气旺血行","补气健脾，化生气血"],"a":2,"e":"玉屏风散中黄芪内补脾肺之气、外固卫表而止汗，为君药；白术健脾益气、助黄芪固表，防风走表祛风，三药合用益气固表止汗，主治表虚自汗。托脓外出为黄芪配伍透脓散之意，行水消肿属防己黄芪汤所用，大补元气、气旺血行是当归补血汤之配伍，补气健脾、化生气血则偏于归脾、八珍之类"},{"q":"小承气汤组成药物正确的是","o":["大黄、枳实、厚朴","大黄、芒硝、甘草","大黄、枳实、甘草","大黄、枳实、芒硝","大黄、厚朴、甘草"],"a":0,"e":"小承气汤由大黄、枳实、厚朴三味组成，功能轻下热结，主治阳明腑实轻证。方中大黄泻热通便，枳实、厚朴行气导滞，不含芒硝、甘草。调胃承气汤为大黄、芒硝、甘草，大承气汤则四味俱全且枳朴量重；凡见芒硝、甘草皆非小承气汤之制，此方重在行气导滞，泻下之力较缓"},{"q":"干姜为苓甘五味姜辛汤中的","o":["臣药","佐药","君药","佐助药","佐制药"],"a":2,"e":"苓甘五味姜辛汤以干姜为君，辛热温肺化饮、温脾化湿，针对寒饮内停之咳嗽痰多清稀。茯苓健脾渗湿为臣，细辛、五味子一散一收、温肺化饮并敛肺气，甘草调和诸药。干姜温中散寒兼化饮，故既温肺又温脾；细辛辛散温肺但无温脾化湿之功，五味子酸收敛肺，茯苓、甘草健脾益气而非温化寒饮之主"},{"q":"治疗热毒痢疾，应首选的方剂是","o":["芍药汤","香连丸","黄芩汤","白头翁汤","白头翁加甘草阿胶汤"],"a":3,"e":"白头翁汤以白头翁清热解毒、凉血止痢为君，黄连、黄柏清热燥湿、泻火解毒，秦皮清热燥湿、收涩止痢，共奏清热解毒、凉血止痢之功，主治热毒痢疾、下痢脓血。芍药汤清热燥湿、调气和血，主治湿热痢；香连丸清热燥湿、行气止痛，主治湿热痢疾之轻者；黄芩汤清热止利，白头翁加甘草阿胶汤则养血和血，均非热毒痢首选"},{"q":"黄土汤和龙胆泻肝汤共有的药物是","o":["白术、山栀子","山栀子、生地黄","山栀子、黄芩","黄芩、生地黄","白术、木通"],"a":3,"e":"黄土汤含灶心土、白术、附子、阿胶、生地、黄芩、甘草，龙胆泻肝汤含龙胆草、黄芩、栀子、泽泻、木通、车前子、当归、生地、柴胡、甘草，二方共有黄芩、生地与甘草，选项中为黄芩、生地黄。山栀子、木通只见于龙胆泻肝汤，白术只见于黄土汤，故含山栀子、木通、白术各项皆非共有之药"},{"q":"苓甘五味姜辛汤中既温肺化饮，又温脾化湿的药物是","o":["茯苓","甘草","五味子","细辛","干姜"],"a":4,"e":"苓甘五味姜辛汤中干姜辛热，入肺、脾经，既能温肺散寒化饮以治咳痰清稀，又能温脾阳、助运化而化湿，一举两得，故为所问。细辛辛温，专于温肺散寒化饮，无温脾化湿之能；五味子酸温，敛肺止咳、滋肾纳气；茯苓淡渗利湿健脾，甘草益气和中，均不具备既温肺又温脾的双重作用"},{"q":"牡蛎散中功专止汗的药物是","o":["煅牡蛎","麻黄根","生黄芪","浮小麦","山茱萸"],"a":1,"e":"牡蛎散以麻黄根为功专止汗之品，其性收敛，专入肌表固腠理而止汗，配煅牡蛎敛阴固涩、黄芪益气固表、浮小麦退热止汗，共奏益气固表、敛阴止汗之功。煅牡蛎偏于敛阴潜阳、固涩止汗，生黄芪益气固表而非专止汗，浮小麦止汗兼清虚热，山茱萸补益肝肾、涩精止汗，皆非功专止汗之药"},{"q":"下列各项，不属于杏苏散的组成药物","o":["半夏、茯苓","橘皮、前胡","荆芥、防风","枳壳、生姜","桔梗、大枣"],"a":2,"e":"杏苏散由苏叶、杏仁、前胡、桔梗、枳壳、陈皮、半夏、茯苓、甘草、生姜、大枣组成，功能轻宣凉燥、理肺化痰，主治外感凉燥。方中半夏、茯苓健脾燥湿，橘皮、前胡理气宣肺，枳壳、生姜宽胸和中，桔梗、大枣宣肺调和，均为本方所有；荆芥、防风辛散祛风，主治外感风寒表证，非凉燥所宜，故不在杏苏散之列"},{"q":"当归四逆汤主治病证的主要临床表现是","o":["恶寒蜷卧","手足厥寒","腹痛下利","倦怠乏力","脉微欲绝"],"a":1,"e":"当归四逆汤主治血虚寒厥证，因营血虚弱、寒邪凝滞、血脉不通，故以手足厥寒、脉细欲绝为主要表现。方中当归养血和血，桂枝、芍药调和营卫，细辛温经散寒，木通通利关节，甘草、大枣益气健脾。恶寒蜷卧、脉微欲绝为四逆汤之少阴寒化证；腹痛下利属理中、四逆之候，倦怠乏力为气虚之象，均非本方主证"},{"q":"阳和汤中少佐麻黄的主要用意是","o":["发汗散寒、通达表里","宣通肺气、开发腠理","鼓舞阳气、散寒通滞","制熟地黄、鹿角胶之滋腻","宣肺解表，调和营卫"],"a":2,"e":"阳和汤中少佐麻黄，意在鼓舞阳气、开腠达表、散寒通滞，使阴疽之寒凝得以温散，与熟地、鹿角胶、姜炭、肉桂等温阳补血之品相配，共奏温阳补血、散寒通滞之功，主治阴疽。若用发汗散寒、宣通肺气或宣肺解表，皆失其散寒通滞之专；麻黄在方中并非为制熟地、鹿角胶之滋腻而设，该作用主要靠姜炭、肉桂等温药"},{"q":"炙甘草汤中用量最大的药物是","o":["炙甘草","生地黄","麦门冬","人参","生姜"],"a":1,"e":"炙甘草汤中用量最大者为生地黄，重用至一斤，意在滋阴养血、充填血脉，配阿胶、麦冬、麻仁滋阴润燥，人参、桂枝、生姜、大枣、甘草益气通阳，共奏益气滋阴、通阳复脉之功，主治气血阴阳俱虚之脉结代、心动悸。炙甘草虽为君药，用量不及生地；麦冬、人参、生姜用量亦较轻，故唯生地黄用量最重"},{"q":"天台乌药散的功用为","o":["行气疏肝，散寒止痛","行气疏肝，祛寒止痛","温补肝肾，行气止痛","行气活血，调经止痛","行气活血，软坚散结"],"a":0,"e":"天台乌药散以乌药行气疏肝、散寒止痛为君，木香、小茴香、青皮、高良姜行气散寒，槟榔下气导滞，川楝子、巴豆同炒去巴豆而取其行气散结之性，共奏行气疏肝、散寒止痛之功，主治寒凝气滞之小肠疝气。温补肝肾属暖肝煎，行气活血、调经止痛多见于妇科方，行气活血、软坚散结属橘核丸，皆非本方功用"},{"q":"右归丸的功用是","o":["温补肾阳，填精益髓","滋阴补肾，填精益髓","温肾化气，利水消肿","温肾壮阳，涩精止遗","温补肾阳，涩精缩尿"],"a":0,"e":"右归丸以附子、肉桂、鹿角胶温补肾阳、填精补髓为君，熟地、山茱萸、山药、枸杞子、杜仲、菟丝子滋补肝肾、强腰膝，当归养血，共奏温补肾阳、填精益髓之功，主治肾阳不足、命门火衰。滋阴补肾属左归丸，温肾化气、利水消肿属肾气丸，温肾壮阳、涩精止遗偏于固精之剂，温补肾阳、涩精缩尿则近于缩泉、桑螵蛸之类，均非右归丸功用"},{"q":"黄土汤的组成药物中无","o":["白术","附子","干姜","阿胶","干地黄"],"a":2,"e":"黄土汤由灶心土、白术、附子、阿胶、干地黄、黄芩、甘草组成，功能温阳健脾、养血止血，主治脾阳不足、统摄无权之便血、崩漏。方中白术健脾，附子温阳，阿胶、干地黄养血，黄芩苦寒坚阴、制约温燥，唯独不含干姜。干姜虽温中，但本方温阳靠附子、灶心土，若加入干姜则温燥太过，反伤阴血，故不在其列"},{"q":"具有温肾益精，润肠通便功用的方剂是","o":["肾气丸","五仁丸","麻子仁丸","济川煎","润肠丸"],"a":3,"e":"济川煎以肉苁蓉温肾益精、润肠通便为君，当归养血润肠，牛膝补肾强腰、引药下行，泽泻利湿，枳壳宽肠下气，升麻升清阳，共奏温肾益精、润肠通便之功，主治肾虚便秘。肾气丸温补肾阳而不润肠，五仁丸、润肠丸纯润肠燥而无温肾之功，麻子仁丸泻热润肠、治胃肠燥热之脾约，均非温肾益精之剂"},{"q":"川芎茶调散的功用是","o":["疏风解表","疏风清热","疏风止痛","祛风化痰","祛风除湿"],"a":2,"e":"川芎茶调散以川芎、羌活、白芷、防风等疏风止痛药为主，清茶调服，共奏疏风止痛之功，主治外感风邪头痛。本方重在疏风邪以止头痛，非解表退热之剂，故不专主疏风解表；疏风清热属桑菊、川芎茶调加减，祛风化痰、祛风除湿则分别针对风痰、风湿，皆非本方功用。川芎善治少阳、厥阴头痛，为方中要药"},{"q":"厚朴温中汤的臣药为","o":["草豆蔻","陈皮","茯苓","木香","干姜"],"a":0,"e":"厚朴温中汤以厚朴行气燥湿、消胀除满为君，草豆蔻辛温香燥，温中燥湿、行气除满，助君药温中行气，是为臣药；陈皮、木香理气，茯苓渗湿，干姜温中，甘草调和，共奏温中行气、燥湿除满之功。陈皮、木香、茯苓、干姜皆为佐药之列，功在辅助，唯草豆蔻与厚朴相须为臣，共主温中燥湿"},{"q":"牡蛎散、玉屏风散、补中益气汤三方中共同的药物是","o":["当归","黄芪","防风","橘红","炙甘草"],"a":1,"e":"牡蛎散、玉屏风散、补中益气汤三方均含黄芪：牡蛎散用黄芪益气固表止汗，玉屏风散用黄芪益气固表御风，补中益气汤用黄芪补中益气、升阳举陷，故共有者为黄芪。当归只见于补中益气汤，防风为玉屏风散所有，炙甘草见于补中、牡蛎散，橘红则三方的常规组成中皆无，均非三方共有之药"},{"q":"下列各项中，属于苓桂术甘汤主治症状的是","o":["胸胁胀痛","目眩心悸","气逆而喘","苔白腻","水入即吐"],"a":1,"e":"苓桂术甘汤主治中阳不足之痰饮，茯苓健脾渗湿、桂枝温阳化气、白术健脾燥湿、甘草益气和中，共奏温阳化饮、健脾利湿之功。饮邪上犯清阳则目眩，水气凌心则心悸，为其特征症状。胸胁胀痛多属悬饮、气滞，气逆而喘为肺气上逆，苔白腻为湿浊之象，水入即吐属五苓散之蓄水证，皆非本方主治之的症"},{"q":"平胃散主治证的病机是","o":["湿阻气滞，肝脾不和","湿阻气滞，肝胃不和","湿阻气滞，胆胃不和","湿阻气滞，脾胃失和","湿阻气滞，肠胃失和"],"a":3,"e":"平胃散以苍术燥湿健脾为君，厚朴行气除满，陈皮理气和胃，甘草调和，生姜、大枣调和脾胃，共奏燥湿运脾、行气和胃之功，主治湿滞脾胃证，病机为湿阻气滞、脾胃失和。肝脾不和属逍遥散，肝胃不和属柴胡疏肝、左金之类，胆胃不和属蒿芩清胆，肠胃失和亦非本方所主，本方专为湿困脾胃、运化失常而设"},{"q":"小陷胸汤治疗的痰证是","o":["热痰","湿痰","燥痰","风痰","顽痰"],"a":0,"e":"小陷胸汤以黄连清热燥湿、半夏化痰散结、瓜蒌实清热化痰、宽胸散结，共奏清热化痰、宽胸散结之功，主治痰热互结之小结胸证，所治为热痰。湿痰稠黏属二陈汤所主，燥痰难咯属贝母瓜蒌散，风痰多见半夏白术天麻汤，顽痰、老痰则非礞石滚痰丸莫属，皆非小陷胸汤清热涤痰之的"},{"q":"温脾汤与济川煎共有的药物是","o":["附子","肉苁蓉","当归","人参","甘草"],"a":2,"e":"温脾汤含大黄、附子、干姜、人参、甘草、当归，济川煎含肉苁蓉、当归、牛膝、泽泻、升麻、枳壳，二方共有当归。附子、人参、甘草只见于温脾汤，肉苁蓉只见于济川煎，故诸项中唯当归为两方所同用。温脾汤重在温阳泻下、攻逐寒积，济川煎重在温肾益精、润肠通便，当归在两方中分别兼养血润肠、活血之用"},{"q":"下列方剂组成中含有人参、黄芪、白术、甘草的是","o":["参苓白术散","四君子汤","人参蛤蚧散","补中益气汤","玉屏风散"],"a":3,"e":"补中益气汤由黄芪、人参、白术、甘草、当归、陈皮、升麻、柴胡组成，含人参、黄芪、白术、甘草四味，功能补中益气、升阳举陷。参苓白术散有人参、白术、甘草而无黄芪；四君子汤仅人参、白术、茯苓、甘草；玉屏风散有黄芪、白术而无甘草、人参；人参蛤蚧散虽有人参、甘草，亦无黄芪、白术之全，故唯补中益气汤四味俱全"},{"q":"大青龙汤的功用是","o":["发汗解表，宣肺平喘","发汗解表，兼清里热","解肌发表，调和营卫","温经散寒，养血通脉","发汗解表，平冲降逆"],"a":1,"e":"大青龙汤以麻黄、桂枝、杏仁、甘草发汗解表、宣肺平喘，更配石膏清热除烦，共奏发汗解表、兼清里热之功，主治外感风寒、里有郁热之表实热证。单纯发汗解表、宣肺平喘为麻黄汤功用；解肌发表、调和营卫属桂枝汤；温经散寒、养血通脉属当归四逆汤；平冲降逆则非本方所重，故兼清里热为其辨识要点"},{"q":"左归丸的功用是","o":["滋阴补肾，涩精止遗","温补肾阳，填精补血","滋阴补肾，填精益髓","补益肝肾，强壮筋骨","填精补髓，滋阴降火"],"a":2,"e":"左归丸以熟地滋补肾阴、填精益髓为君，山药、山茱萸、枸杞子、鹿角胶、龟板胶、菟丝子、牛膝滋阴益肾、填精补髓，共奏滋阴补肾、填精益髓之功，主治真阴不足。滋阴降火属知柏地黄丸，温补肾阳属右归丸，补益肝肾、强壮筋骨偏于虎潜丸，填精补髓、滋阴降火则非纯补之剂，左归丸纯补无泻，与六味地黄丸补泻兼施不同"},{"q":"阳和汤的主治病证不包括","o":["贴骨疽","流注","鹤西风","大头瘟","痰核"],"a":3,"e":"阳和汤温阳补血、散寒通滞，主治阴疽，如贴骨疽、流注、鹤膝风、痰核、脱疽等证属阳虚寒凝者。大头瘟为风热疫毒上攻头面，治宜普济消毒饮清热解毒、疏风散邪，与阳和汤温阳散寒之旨相反，故非阳和汤所主。贴骨疽、流注、痰核皆为阴疽范畴，鹤膝风属阴寒凝滞关节，皆可用阳和汤温散"},{"q":"补阳还五汤的功用","o":["补气，活血，养血","补气，活血，通络","补气，活血，行气","行气，舒肝，通络","行气，止痛，活血"],"a":1,"e":"补阳还五汤重用黄芪大补元气为君，当归尾、赤芍、川芎、桃仁、红花、地龙活血化瘀、通经活络，共奏补气、活血、通络之功，主治气虚血瘀之中风后遗症，半身不遂。方中并无养血之熟地、白芍，故不主养血；亦无行气之陈皮、香附，非行气之剂；行气舒肝、行气止痛皆非本方所重，其要在补气以推动血行、化瘀通络"},{"q":"痛泻要方主治证的病机是","o":["肝郁克脾","土虚木乘","火不暖土","土不生金","心肾不交"],"a":1,"e":"痛泻要方以白术健脾燥湿为君，白芍柔肝缓急止痛，陈皮理气醒脾，防风散肝舒脾，共奏补脾柔肝、祛湿止泻之功，主治痛泻，病机为脾虚肝旺、土虚木乘，肝气乘脾则腹痛、脾失健运则泄泻。肝郁克脾偏重肝气郁结，土不生金为脾虚及肺，心肾不交属失眠、心悸之机，火不暖土多指命门火衰之五更泻，皆非痛泻要方之病机"},{"q":"半夏白术天麻汤的组成含有","o":["半夏、橘红、白术、乌梅、甘草","半夏、橘红、白茯苓、乌梅、甘草","半夏、陈皮、白茯苓、大枣、甘草","半夏、陈皮、茯苓、胆南星、甘草","半夏、橘红、白术、大枣、甘草"],"a":4,"e":"半夏白术天麻汤由半夏、天麻、茯苓、橘红、白术、甘草、生姜、大枣组成，功能化痰息风、健脾祛湿，主治风痰上扰之眩晕。橘红即陈皮，与白术、大枣、甘草、半夏相合，符合本方组成。含乌梅各方不是本方；胆南星为清热化痰之品，半夏白术天麻汤用半夏而非胆南星；不含白术或易以他药者，皆与本方健脾祛湿之旨不符"},{"q":"大黄牡丹汤中君药是","o":["大黄、桃仁","牡丹皮、大黄","桃仁、牡丹皮","瓜子、芒硝","大黄、芒硝"],"a":0,"e":"大黄牡丹汤以大黄泻热逐瘀、桃仁活血祛瘀共为君药，牡丹皮凉血散瘀，瓜子（冬瓜仁）清肠排脓，芒硝软坚散结、泻热通便，共奏泻热破瘀、散结消肿之功，主治肠痈初起湿热瘀滞证。牡丹皮偏于凉血，非君；瓜子、芒硝重在排脓软坚，亦非君药，故凡不以大黄、桃仁为君者，皆失本方逐瘀泻热之主"},{"q":"泻白散的功用是","o":["清泻肺热","泻肺行水，下气平喘","清泻肺热，止咳平喘","辛凉疏表，清肺平喘","疏风清热，宣肺止咳"],"a":2,"e":"泻白散以桑白皮清泻肺热、平喘利水为君，地骨皮退虚热、凉血，粳米、甘草养胃生津、调和诸药，共奏清泻肺热、止咳平喘之功，主治肺热喘咳，特点是清肺而不伤正。单纯清泻肺热未及止咳平喘，泻肺行水、下气平喘为葶苈大枣泻肺汤之意，辛凉疏表、清肺平喘属麻杏石甘汤，疏风清热、宣肺止咳属桑菊饮，皆非泻白散功用"},{"q":"镇肝熄风汤配伍的君药是","o":["白芍","代赭石","怀牛膝","牡蛎","龟板"],"a":2,"e":"镇肝熄风汤以怀牛膝为君，引血下行、折其亢阳，并补益肝肾；代赭石、龙骨、牡蛎、龟板、白芍镇肝潜阳、柔肝息风，川楝子、茵陈、麦芽疏肝泄热、条达肝气，甘草调和，共奏镇肝息风、滋阴潜阳之功，主治类中风肝阳上亢、气血逆乱。代赭石、牡蛎、龟板、白芍皆为臣佐，功在镇潜，唯牛膝引血下行以治本，故为君药"},{"q":"十灰散的病机是","o":["血热妄行，损伤血络","脾阳不足，统摄失常","血热妄行，瘀血内停","肝火犯肺，损伤血络","冲任虚寒，血不内守"],"a":0,"e":"十灰散以大蓟、小蓟、荷叶、侧柏叶、茅根、茜草、栀子、大黄、牡丹皮、棕榈皮十味烧灰存性，凉血止血，主治血热妄行之上部出血，病机为血热妄行、损伤血络。脾阳不足、统摄失常属黄土汤，肝火犯肺、损伤血络属咳血方，冲任虚寒、血不内守属温经汤，血热兼瘀虽可见，但本方病机重在血热妄行，不强调瘀血内停，故以血热妄行、血络损伤为的"},{"q":"下列选项与“朱砂安神丸”组成有关，并且功效也正确的是","o":["黄连苦寒，入心经，清心泻火以除烦热","酸枣仁养血补肝，宁心安神","柏子仁养血安神","茯神健脾安神","远志宁心安神"],"a":0,"e":"朱砂安神丸由朱砂、黄连、生地黄、当归、甘草组成，黄连苦寒入心经，清心泻火以除烦热，与朱砂重镇安神相配，主治心火亢盛、阴血不足之失眠多梦、心神烦乱。酸枣仁、柏子仁、茯神、远志虽均为安神常用药，但均不在朱砂安神丸组成之列，其中酸枣仁养心肝、柏子仁养心、茯神健脾宁心、远志祛痰开窍，与本方清心泻火、重镇安神之配伍不同"},{"q":"主治梅核气的方剂为","o":["柴胡疏肝散","越鞠丸","四磨汤","半夏厚朴汤","枳实消痞丸"],"a":3,"e":"半夏厚朴汤以半夏化痰散结、降逆和胃为君，厚朴下气除满，茯苓健脾渗湿，生姜和胃止呕，苏叶芳香行气、疏肝解郁，共奏行气散结、降逆化痰之功，主治痰气郁结之梅核气，咽中如有物阻。柴胡疏肝散疏肝理气，越鞠丸行气解郁治六郁，四磨汤行气降逆，枳实消痞丸消痞除满，皆非治梅核气之的方"},{"q":"龙胆泻肝汤的主治证是","o":["肝阳上亢","肝火上炎","肝火犯肺","肝气郁结","肝火犯胃"],"a":1,"e":"龙胆泻肝汤以龙胆草清肝胆实火、泻下焦湿热为君，黄芩、栀子助清热泻火，泽泻、木通、车前子清热利湿，当归、生地养血滋阴以防伤正，柴胡引经，甘草调和，主治肝胆实火上炎证及肝经湿热下注证。肝阳上亢属镇肝熄风、天麻钩藤饮，肝火犯肺属黛蛤散、咳血方，肝气郁结属柴胡疏肝散，肝火犯胃属左金丸，皆非本方主治"},{"q":"下列各项中，不属于芍药在真武汤中配伍意义的是","o":["利小便","柔肝缓急","敛阴舒筋","养血调经","制附子温燥之性"],"a":3,"e":"真武汤中芍药一药多用：利小便以助行水，柔肝缓急、敛阴舒筋以防温燥伤阴，并制附子、生姜之温燥，主治阳虚水泛。养血调经为当归、白芍在四物汤等方中的功用，与真武汤温阳利水、芍药防燥护阴的配伍意义无涉，故不属本方芍药的配伍意义。其余利小便、柔肝缓急、敛阴舒筋及制约温燥，皆为其配伍本意"},{"q":"四物汤与补中益气汤共有的药是","o":["地黄","黄芪","白术","当归","芍药"],"a":3,"e":"四物汤由熟地黄、当归、白芍、川芎组成，补中益气汤由黄芪、人参、白术、甘草、当归、陈皮、升麻、柴胡组成，二方共有当归。地黄、芍药只见于四物汤，黄芪、白术只见于补中益气汤，故唯当归为两方所同有。当归在四物汤中养血活血、调经，在补中益气汤中养血和血、助益气生血，体现气血相依之理"},{"q":"半夏厚朴汤的功用为","o":["行气散结，降逆化痰","行气祛痰，降逆散结","行气解郁，理气化痰","行气消痞，健脾化痰","行气解郁，疏肝理脾"],"a":0,"e":"半夏厚朴汤以半夏化痰散结、降逆和胃为君，厚朴下气消胀，茯苓健脾渗湿以助消痰，生姜和胃降逆，苏叶疏肝行气，共奏行气散结、降逆化痰之功，为治梅核气之主方。行气祛痰、降逆散结虽近似，但教材规范表述为行气散结、降逆化痰；行气解郁、疏肝理脾偏于柴胡疏肝、逍遥之类，行气消痞、健脾化痰属枳实消痞丸，皆非本方功用"},{"q":"由大黄、芒硝、甘遂组成的方剂是","o":["小承气汤","大承气汤","小柴胡汤","大柴胡汤","大陷胸汤"],"a":4,"e":"大陷胸汤由大黄、芒硝、甘遂组成，功能泻热逐水破结，主治水热互结之结胸证，心下硬满疼痛、大便不通。小承气汤为大黄、枳实、厚朴，大承气汤再加芒硝，均无甘遂；小柴胡汤、大柴胡汤属和解、通下少阳阳明之剂，组成各异；唯大陷胸汤以甘遂逐水、大黄芒硝泻热破结，三味相须，为逐水破结之峻剂"},{"q":"下列选项中，不属于十枣汤组成的是","o":["商陆","甘遂","大戟","芫花","大枣"],"a":0,"e":"十枣汤由甘遂、大戟、芫花三味逐水药与大枣组成，大枣益气护胃、缓和诸药毒性，功能攻逐水饮，主治悬饮、水肿实证。甘遂、大戟、芫花皆为方中逐水主药，大枣为使，唯商陆不在其列。商陆虽亦逐水消肿，但为另一逐水药，非十枣汤组成，本方以三味峻下逐水配大枣缓急，是其配伍特点"},{"q":"一贯煎的君药是","o":["沙参","枸杞子","当归","生地黄","麦门冬"],"a":3,"e":"一贯煎以生地黄为君，滋阴养血、补益肝肾，配枸杞子、沙参、麦冬、当归滋阴柔肝，少量川楝子疏肝泄热、行气止痛，共奏滋阴疏肝之功，主治肝肾阴虚、肝气不舒之胁肋疼痛。沙参、枸杞子、当归、麦冬均为臣药，助君滋阴柔肝；川楝子为佐药疏肝，唯生地黄滋阴之力最著，为全方之主，故为君药"},{"q":"半夏厚朴汤中的臣药为","o":["半夏","厚朴","苏叶","茯苓","生姜"],"a":1,"e":"半夏厚朴汤以半夏为君，化痰散结、降逆和胃；厚朴为臣，下气消胀、助半夏行气散结；茯苓、生姜、苏叶为佐使，健脾渗湿、和胃降逆、疏肝行气。其中苏叶辛香行气、解郁，生姜和胃止呕，茯苓健脾，皆居佐使之地，非臣药；唯厚朴与半夏相配，一化痰一降气，共主行气散结，故厚朴为臣"},{"q":"九味羌活汤主治证候的病机是","o":["外感风寒，营卫不和","外感风寒湿邪，内有蕴热","外感风寒，内有蕴热","外感风寒，肺气失宣","外感风寒，水饮内停"],"a":1,"e":"九味羌活汤以羌活为君，祛风散寒除湿、宣痹止痛，防风、苍术助祛风胜湿，细辛、白芷、川芎祛风散寒止痛，黄芩、生地清泄里热，甘草调和，共奏发汗祛湿、兼清里热之功，主治外感风寒湿邪、内有蕴热证，症见恶寒发热、无汗、肢体酸重痛、口苦微渴。单纯风寒无湿或仅内有蕴热，皆不全面，本方特点为祛湿与清热并用"},{"q":"血虚寒厥证手足厥寒宜用","o":["四逆散","四逆汤","当归四逆汤","独活寄生汤","回阳救急汤"],"a":2,"e":"当归四逆汤养血散寒、温经通脉，主治血虚寒厥证，因营血不足、寒凝经脉，阳气不能达于四末，故见手足厥寒、脉细欲绝或细而欲绝。四逆散疏肝解郁、透邪外出，治阳郁厥逆，肢冷但脉弦有力；四逆汤、回阳救急汤回阳救逆，治少阴寒化、阳气衰微之四肢厥冷、脉微欲绝；独活寄生汤益肝肾、补气血、祛风湿，治痹证，均非血虚寒厥所宜"},{"q":"大建中汤与小建中汤比较前者作用较峻的一项是","o":["补益气血","补虚散寒","温补肾阳","温里散寒","甘温益气"],"a":1,"e":"大建中汤以蜀椒、干姜温中散寒、降逆止痛，人参、饴糖补虚缓急，共奏温中补虚、降逆止痛之功，主治中阳衰弱、阴寒内盛之脘腹剧痛，温中补虚、散寒止痛之力较强。小建中汤以桂枝、白芍、饴糖温中补虚、和里缓急，作用较缓和；温补肾阳、甘温益气均非两方对比之要点，本方以散寒止痛见长，故较峻者在补虚散寒"},{"q":"桂枝在五苓散中的作用是","o":["温通血脉","解肌发表","温经散寒","调和营卫","温阳化气"],"a":4,"e":"五苓散中桂枝温阳化气以助膀胱气化，兼解外邪，与茯苓、猪苓、泽泻利水渗湿，白术健脾燥湿相配，共奏利水渗湿、温阳化气之功，主治蓄水证及水湿内停。温通血脉为桂枝在桂枝汤、当归四逆汤之意，解肌发表为桂枝汤功用，温经散寒属当归四逆，调和营卫属桂枝汤，皆非其在五苓散中的主要作用，本方取桂枝温阳化气以行水"},{"q":"四神丸主治证的主要病机是","o":["命门火衰","脾阳不足","湿热下注","寒湿内停","瘀血阻滞"],"a":0,"e":"四神丸以补骨脂温补肾阳、暖命门火为君，肉豆蔻温中涩肠，五味子敛肠止泻，吴茱萸温中散寒，生姜、大枣温中健胃，共奏温肾暖脾、固肠止泻之功，主治脾肾阳虚之五更泄泻，病机关键为命门火衰、火不暖土。脾阳不足偏于理中、实脾，湿热下注属葛根芩连、芍药汤，寒湿内停、瘀血阻滞皆非本方所主，故命门火衰为其核心病机"},{"q":"六一散中滑石与甘草配伍，功能","o":["祛暑解表","清暑益气","清暑利湿","清热解毒","疏风清热"],"a":2,"e":"六一散以滑石六两、甘草一两组成，滑石清暑利湿、解肌，甘草清热和中，共奏清暑利湿之功，主治暑湿证，症见身热烦渴、小便不利、泄泻。祛暑解表属香薷散，清暑益气属清暑益气汤、生脉散，清热解毒属凉膈、黄连解毒之类，疏风清热属桑菊饮，皆非六一散功用，本方药简力专，清暑而不忘利湿，使湿去热清"},{"q":"葛根黄芩黄连汤的功用是","o":["解表清里","解表温里","发散风热","清热解毒","清热燥湿"],"a":0,"e":"葛根黄芩黄连汤以葛根解肌发表、升阳止泻为君，黄芩、黄连清热燥湿、泻火解毒，甘草调和诸药，共奏解表清里之功，主治外感表证未解、热邪入里之协热下利，身热、下利臭秽、肛门灼热。解表温里属桂枝人参汤，发散风热属桑菊、银翘，清热解毒、清热燥湿虽各有其方，但本方特点为解表与清里并行，表里双解"},{"q":"补气生血的代表方剂是","o":["四物汤","当归补血汤","归脾汤","八珍汤","生脉散"],"a":1,"e":"当归补血汤重用黄芪五倍于当归，大补元气以资生血之源，当归养血和血，共奏补气生血之功，主治气血两虚、阳气虚弱之发热、面赤、脉洪大而虚，为有形之血不能速生、无形之气所当急固之代表方。四物汤纯养血和血，归脾汤益气补血、健脾养心，八珍汤气血双补，生脉散益气养阴，皆非以补气生血为主要配伍意义者"},{"q":"左归丸组成中含有而右归丸组成中不含有的药物是","o":["枸杞子","龟板胶","鹿角胶","山茱萸","菟丝子"],"a":1,"e":"左归丸含熟地、山药、山茱萸、枸杞子、鹿角胶、龟板胶、菟丝子、牛膝，功能滋阴补肾、填精益髓；右归丸含附子、肉桂、鹿角胶、熟地、山茱萸、山药、枸杞子、杜仲、菟丝子、当归，功能温补肾阳。龟板胶滋阴潜阳、益肾健骨，为左归丸所独有；鹿角胶、枸杞子、山茱萸、菟丝子则两方共有，故唯龟板胶为左归丸有而右归丸无"},{"q":"麦门冬汤组成中半夏与麦冬的用量比例为","o":["1∶2","1∶3","1∶5","1∶7","1∶9"],"a":3,"e":"麦门冬汤中麦冬用七升、半夏用一升，半夏与麦冬用量比例为一比七，即麦冬倍于半夏，意在以大量麦冬滋阴润肺、益胃生津，配少量半夏降逆下气、化痰和胃，燥湿相济，共奏滋养肺胃、降逆下气之功。其余一比二、一比三、一比五比例失之过大，一比九则非原方之制，均不符合麦门冬汤重用麦冬、轻用半夏的配伍特点"},{"q":"大承气汤中含有的药对是","o":["大黄、甘草","附子、生姜","厚朴、枳壳","人参、当归","大黄、芒硝"],"a":4,"e":"大承气汤由大黄、芒硝、枳实、厚朴组成，大黄泻热通便、芒硝软坚润燥，二者相须为用，共奏峻下热结之功，是其核心药对；枳实、厚朴行气导滞、消胀除满，助泻下之力。大黄、甘草为调胃承气汤之配，附子、生姜非本方所有，枳壳非本方所用（本方用枳实），人参、当归更非攻下之品，故唯大黄、芒硝为大承气汤所含药对"},{"q":"蒿芩清胆汤的功用是","o":["清泄三焦，舒畅气机","清胆利湿，和胃化痰","和解少阳，疏散郁热","疏肝理脾，健胃消食","温肝散寒，行气祛湿"],"a":1,"e":"蒿芩清胆汤以青蒿、黄芩清泄少阳湿热为君，竹茹、半夏、陈皮、枳壳和胃降逆、理气化痰，茯苓、滑石、青黛清热利湿，共奏清胆利湿、和胃化痰之功，主治少阳湿热、寒热如疟、痰热内扰。清泄三焦、舒畅气机偏于三焦辨证之剂，和解少阳、疏散郁热近于小柴胡加减，疏肝理脾、温肝散寒皆非本方清胆利湿之旨"},{"q":"凉膈散中所含的“承气”汤是","o":["大承气汤","小承气汤","调胃承气汤","桃核承气汤","增液承气汤"],"a":2,"e":"凉膈散由大黄、芒硝、甘草、栀子、黄芩、连翘、竹叶、薄荷组成，其中大黄、芒硝、甘草即调胃承气汤，用以泻热通便、荡涤中焦燥实，配清上泄下之品，共奏泻火通便、清上泄下之功，主治上中二焦邪郁生热。大承气、小承气皆含枳实、厚朴，桃核承气含桃仁、桂枝，增液承气含玄参、麦冬、生地，均非凉膈散所含，故为调胃承气汤"},{"q":"麻黄杏仁甘草石膏汤的功用是","o":["辛凉透表，清热解毒","疏风清热，宣肺止咳","辛凉疏表，清肺平喘","辛凉宣肺，清热解毒","宣利肺气，疏风止咳"],"a":2,"e":"麻黄杏仁甘草石膏汤以麻黄宣肺解表平喘、石膏清泄肺热，二者相制为用，杏仁降肺气、甘草调和，共奏辛凉疏表、清肺平喘之功，主治外感风邪、邪热壅肺之发热、咳喘、口渴。辛凉透表、清热解毒为银翘散功用，疏风清热、宣肺止咳属桑菊饮，辛凉宣肺虽近似但本方重在疏表与清肺平喘并见，故以辛凉疏表、清肺平喘为规范表述"},{"q":"橘皮竹茹汤的辨证要点是","o":["膈痞闷，脘腹胀痛，饮食不消","呃逆或呕吐，舌红嫩，脉虚数","胸中痞满，气从胁下冲逆，上攻心胸，舌苔白腻，脉沉弦或紧","少腹痛引睾丸，舌淡苔白，脉沉弦","胸膈满闷，痰多稀白，苔白滑或白腻"],"a":1,"e":"橘皮竹茹汤以橘皮、竹茹理气降逆、清热止呕，人参、甘草、生姜、大枣益气和中，共奏降逆止呕、益气清热之功，主治胃虚有热之呃逆、呕吐，辨证要点为呃逆或呕吐、舌红嫩、脉虚数。胸中痞满、气从胁下冲逆为旋覆代赭汤证，少腹痛引睾丸为天台乌药散证，胸膈满闷、痰多稀白为苏子降气汤证，膈痞闷、脘腹胀痛、饮食不消为枳实消痞丸证"},{"q":"定喘汤适用于","o":["外感温燥，邪在肺卫","风寒客表，水饮内停","外感风寒，内伤湿滞","风寒外束，痰热内蕴","胸阳不振，痰浊中阻"],"a":3,"e":"定喘汤以麻黄宣肺散寒平喘、白果敛肺定喘，一散一收，半夏、杏仁、苏子、桑白皮降气化痰、清泻肺热，黄芩清热，款冬花润肺止咳，甘草调和，共奏宣肺降气、清热化痰之功，主治风寒外束、痰热内蕴之哮喘，症见咳喘痰多黄稠、微恶风寒。风寒客表、水饮内停属小青龙汤，外感风寒、内伤湿滞属藿香正气散，胸阳不振、痰浊中阻属瓜蒌薤白类，均非本方所主"},{"q":"主治证病机为“素体阴虚，外感风热”的方剂是","o":["败毒散","参苏饮","麻黄附子细辛汤","再造散","加减葳蕤汤"],"a":4,"e":"加减葳蕤汤以葳蕤（玉竹）滋阴清热、生津润燥为君，配葱白、淡豆豉、薄荷、蝉蜕疏散风热，桔梗、甘草宣肺利咽，茯苓、大枣健脾，白薇清热凉血，共奏滋阴解表之功，主治素体阴虚、外感风热之头痛身热、微恶风寒、咽干口渴。败毒散益气解表，参苏饮益气解表、理气化痰，麻黄附子细辛汤助阳解表，再造散助阳益气解表，皆非滋阴解表之剂"},{"q":"槐花散的功效是","o":["凉血止血，利水通淋","温阳健脾，养血止血","清肠止血，疏风行气","清热解毒，凉血止痢","清热燥湿，调气和血"],"a":2,"e":"槐花散以槐花清肠凉血止血为君，侧柏叶凉血止血，荆芥穗疏风止血，枳壳行气宽肠，共奏清肠止血、疏风行气之功，主治肠风、脏毒下血，便血色鲜红。凉血止血、利水通淋属小蓟饮子，温阳健脾、养血止血属黄土汤，清热解毒、凉血止痢属白头翁汤，清热燥湿、调气和血属芍药汤，皆非槐花散功用，本方侧重清肠疏风以止血"},{"q":"玉屏风散的组成为","o":["黄芪、白术、甘草","白术、防风、黄芪","茯苓、白术、黄芪","黄芪、白术、人参","人参、白术、甘草"],"a":1,"e":"玉屏风散由黄芪、白术、防风三味组成，黄芪益气固表为君，白术健脾益气、助黄芪固表为臣，防风走表祛风为佐，共奏益气固表止汗之功，主治表虚自汗、易感风邪。方中无甘草、人参、茯苓，凡含甘草、人参或茯苓者皆非本方；白术、防风、黄芪三味相合，补中有散、散中寓补，如御风之屏障，故名玉屏风"},{"q":"真人养脏汤补涩不滞，是因为方中配伍了理气药","o":["陈皮","青皮","木香","砂仁","白豆蔻"],"a":2,"e":"真人养脏汤以罂粟壳涩肠止泻为君，肉豆蔻、诃子温中涩肠，人参、白术、甘草益气健脾，当归、白芍养血和血，肉桂温阳，木香理气醒脾，使补涩而不滞，共奏涩肠固脱、温补脾肾之功，主治久泻久痢、脾肾虚寒。陈皮、青皮、砂仁、白豆蔻虽均理气，但本方专用木香行气止痛、醒脾，以防诸药涩滞留邪，故为木香"},{"q":"苏子降气汤与定喘汤中共有的药物是","o":["当归、肉桂","苏子、半夏","厚朴、前胡","白果、麻黄","桑白皮、黄芩"],"a":1,"e":"苏子降气汤含苏子、半夏、前胡、厚朴、陈皮、当归、甘草、肉桂、生姜、大枣，定喘汤含麻黄、白果、苏子、半夏、杏仁、桑白皮、黄芩、款冬花、甘草，二方共有苏子、半夏、甘草，选项中为苏子、半夏。当归、肉桂只见于苏子降气汤，厚朴、前胡亦只见于苏子降气汤，白果、麻黄、桑白皮、黄芩只见于定喘汤，故唯苏子、半夏为两方共有"},{"q":"《金匮要略·呕吐哕下利病脉证治》：“哕逆者，（ ）主之。”","o":["吴茱萸汤","旋覆代赭汤","橘皮竹茹汤","炙甘草汤","小建中汤"],"a":2,"e":"《金匮要略》载“哕逆者，橘皮竹茹汤主之”，本方以橘皮、竹茹理气清热、降逆止呕，人参、甘草、生姜、大枣益气和中，主治胃虚有热之呃逆、呕吐。吴茱萸汤温中补虚、降逆止呕，主治胃寒呕吐；旋覆代赭汤降逆化痰、益气和胃，主治胃虚痰阻之噫气；炙甘草汤益气养阴、通阳复脉；小建中汤温中补虚、缓急止痛，皆非治哕逆之方"},{"q":"下列各项方证中，无小便不利症状的是","o":["实脾散","真武汤","防己黄芪汤","猪苓汤","五苓散"],"a":0,"e":"实脾散以附子、干姜温阳散寒，白术、茯苓健脾渗湿，厚朴、木香、大腹皮、草果、木瓜行气化湿，甘草调和，共奏温阳健脾、行气利水之功，主治阴水，以身半以下肿甚、手足不温、胸腹胀满、大便溏薄为主，无小便不利之的症。真武汤、防己黄芪汤、猪苓汤、五苓散均有利水渗湿之功，主治证中皆可出现小便不利，故唯实脾散无证及小便不利"},{"q":"川芎茶调散的君药是","o":["薄荷","川芎","荆芥","白芷","羌活"],"a":1,"e":"川芎茶调散以川芎为君，辛温香窜，祛风活血、行气止痛，善治少阳、厥阴经头痛；羌活、白芷、防风、荆芥、薄荷、细辛疏风止痛，清茶调服引药上行，共奏疏风止痛之功，主治外感风邪头痛。薄荷、荆芥辛凉、辛散疏风，为臣佐之品；白芷、羌活各治阳明、太阳头痛，亦为臣药，唯川芎总括诸经头痛而为君"},{"q":"仙方活命饮中君药是","o":["当归","白芷","赤芍","穿山甲","金银花"],"a":4,"e":"仙方活命饮以金银花为君，清热解毒、消痈散结，配白芷、防风解表散风，当归尾、赤芍、乳香、没药活血止痛，贝母、天花粉清热化痰散结，穿山甲、皂角刺消肿溃坚，陈皮理气，甘草调和，共奏清热解毒、消肿溃坚、活血止痛之功，主治阳证疮疡肿毒初起。当归、白芷、赤芍、穿山甲皆为臣佐，功在活血、疏风、溃坚，唯金银花清热解毒之力最著而为君"},{"q":"外感温燥，肺津受灼之轻证，宜选","o":["桑杏汤","清燥救肺汤","沙参麦冬汤","麦门冬汤","杏苏散"],"a":0,"e":"桑杏汤以桑叶轻宣温燥、杏仁润肺止咳为君，沙参、贝母滋阴化痰，栀子清泄燥热，梨皮养阴润肺，共奏清宣温燥、润肺止咳之功，主治外感温燥、肺津受灼之轻证，症见身热不甚、干咳无痰或痰少而黏。清燥救肺汤治温燥伤肺之重证，沙参麦冬汤养阴润肺、治燥伤肺胃，麦门冬汤滋养肺胃、降逆下气，杏苏散治外感凉燥，皆非温燥轻证所宜"},{"q":"麻黄汤的臣药是","o":["麻黄","桂枝","杏仁","白芍","甘草"],"a":1,"e":"麻黄汤以麻黄发汗解表、宣肺平喘为君，桂枝解肌发表、温通经脉，助麻黄发汗解表，为臣药；杏仁降肺气、助麻黄平喘为佐，甘草调和诸药为使，共奏发汗解表、宣肺平喘之功，主治外感风寒表实证。麻黄本身为君，杏仁为佐，白芍非本方所有，甘草为使，唯桂枝助麻黄开腠发汗，故为臣药，麻桂相须是发汗解表的核心"},{"q":"小蓟饮子方中配伍当归的意义是","o":["养血和血，宁心安神","养血和血，引血归经","养血和血，调经止痛","养血和血，祛瘀生新","养血和血，缓急止痛"],"a":1,"e":"小蓟饮子以小蓟、生地凉血止血为君，藕节、蒲黄凉血止血、消瘀，滑石、木通、淡竹叶清热利水通淋，栀子清热泻火，当归养血和血、引血归经，甘草调和，共奏凉血止血、利水通淋之功，主治血淋、尿血。当归在方中养血和血并引血归经，防诸药寒凉涩滞留瘀；宁心安神、调经止痛、祛瘀生新、缓急止痛皆非其在小蓟饮子中的配伍意义"},{"q":"下列属于四逆散组成的是","o":["枳壳","赤芍","柴胡","川芎","当归"],"a":2,"e":"四逆散由柴胡、枳实、芍药、甘草四味组成，功能透邪解郁、疏肝理气，主治阳郁厥逆及肝脾不和之胁肋胀痛、脘腹疼痛。柴胡疏肝解郁、透邪外出为君，芍药养血柔肝，枳实理气解郁，甘草调和，四味相合，升降协调。枳壳非本方所用（用枳实），赤芍、川芎、当归皆不在方中，故唯柴胡属于四逆散组成，其余诸药皆非"},{"q":"地黄饮子的功用中包括","o":["滋阴降火","乌发壮骨","理气","开窍化痰","安神益智"],"a":3,"e":"地黄饮子以熟地、山茱萸滋补肾阴，肉苁蓉、巴戟天温补肾阳，附子、肉桂助阳，麦冬、五味子滋阴敛液，石菖蒲、远志、薄荷开窍化痰、交通心肾，茯苓、生姜、大枣调和，共奏滋肾阴、补肾阳、开窍化痰之功，主治下元虚衰、虚阳上浮、痰浊上泛之瘖痱。滋阴降火、乌发壮骨、安神益智非本方功用，方中含薄荷、菖蒲、远志开窍化痰，故开窍化痰为其功用之一"},{"q":"心火亢盛，耗伤阴血，心神失养而致心神烦乱，失眠多梦者，治疗最宜选用","o":["桂枝甘草龙骨牡蛎汤","珍珠母丸","磁朱丸","朱砂安神丸","生铁落饮"],"a":3,"e":"朱砂安神丸以朱砂重镇安神、清心为君，黄连苦寒清心泻火除烦为臣，生地黄滋阴凉血、当归养血和血为佐，甘草调和为使，共奏清心泻火、养血安神之功，主治心火亢盛、阴血不足之心神烦乱、失眠多梦、惊悸怔忡。桂枝甘草龙骨牡蛎汤温阳安神，珍珠母丸滋阴养血、重镇安神，磁朱丸重镇安神、潜阳明目，生铁落饮镇心涤痰、泻肝火，皆非心火亢盛、阴血不足之首选"},{"q":"龟鹿二仙胶组成中不包括","o":["鹿角","龟板","人参","枸杞子","生地黄"],"a":4,"e":"龟鹿二仙胶由鹿角、龟板、人参、枸杞子组成，鹿角温补肾阳、益精血，龟板滋阴潜阳、益肾健骨，人参补气，枸杞子滋阴益精，共奏滋阴填精、益气壮阳之功，主治真元虚损、精血不足。鹿角、龟板、人参、枸杞子皆在方中，唯生地黄不在其列，虽为滋阴常用药，但本方以血肉有情之品填补精髓，不用生地，故生地黄为不包括之药"},{"q":"败毒散的组成中不含有","o":["枳壳","前胡","白前","柴胡","人参"],"a":2,"e":"败毒散由柴胡、前胡、川芎、枳壳、羌活、独活、茯苓、桔梗、人参、甘草、生姜、薄荷组成，功能散寒祛湿、益气解表，主治气虚外感风寒湿邪。方中有前胡而无白前，二者虽均能化痰止咳，但前胡兼能疏散风热、降气化痰，白前专于降气化痰，非本方所用；柴胡、枳壳、人参皆在方中，故唯白前不在败毒散组成之列"},{"q":"具有宣肺降气、清热化痰的功效的方剂是","o":["苏子降气汤","定喘汤","小青龙汤","麻黄汤","麻杏石甘汤"],"a":1,"e":"定喘汤以麻黄宣肺散寒平喘，白果敛肺定喘，杏仁、苏子、半夏降气化痰，桑白皮、黄芩清泻肺热，款冬花止咳，甘草调和，共奏宣肺降气、清热化痰之功，主治风寒外束、痰热内蕴之哮喘咳嗽。苏子降气汤降气平喘、祛痰止咳，主治上实下虚之喘咳；小青龙汤解表散寒、温肺化饮；麻黄汤发汗解表；麻杏石甘汤辛凉疏表、清肺平喘，皆非宣肺降气、清热化痰之剂"},{"q":"主治热毒炽盛之脱疽的方剂是","o":["五味消毒饮","阳和汤","四妙勇安汤","仙方活命饮","苇茎汤"],"a":2,"e":"四妙勇安汤以金银花清热解毒为君，玄参清热解毒、凉血滋阴，当归活血和血，甘草清热解毒、调和诸药，共奏清热解毒、活血止痛之功，主治热毒炽盛之脱疽，患肢红肿热痛、溃烂。五味消毒饮清热解毒、消散疔疮，阳和汤温阳散寒、治阴疽寒凝，仙方活命饮清热解毒、消肿溃坚治阳证疮疡初起，苇茎汤清肺化痰、逐瘀排脓治肺痈，皆非热毒脱疽之的方"},{"q":"萆薢分清饮主治","o":["蓄水证","水热互结阴伤证","下焦虚寒之膏淋、白浊","中阳不足之痰饮","阳虚水泛证"],"a":2,"e":"萆薢分清饮以萆薢利湿去浊、祛风除痹为君，益智仁温肾暖脾、缩尿，石菖蒲开窍化浊，乌药温肾行气，共奏温肾利湿、分清化浊之功，主治下焦虚寒之膏淋、白浊，小便浑浊如米泔。蓄水证属五苓散，水热互结阴伤属猪苓汤，中阳不足之痰饮属苓桂术甘汤，阳虚水泛属真武汤，皆非下焦虚寒、湿浊不化之膏淋白浊所主"},{"q":"以下哪一项不是方剂变化的形式","o":["药味增减变化","药量增减变化","药味、药量同时增减变化","治法更换变化","剂型更换变化"],"a":3,"e":"方剂的变化形式主要有药味增减、药量增减、药味与药量同时增减以及剂型更换四类。药味增减是加入或减去某药，药量增减是调整用量而改变效用，剂型更换如汤改丸、散以缓急，均为常用变化方式。治法更换变化则是另立治法、另选方药，已超出原方加减变化范畴，故不属于方剂变化的形式，其余四项皆为教材所列的变化方式"},{"q":"归脾汤中配伍茯神意在","o":["利水消肿","健脾渗湿","养心安神","渗湿止泻","涤痰除饮"],"a":2,"e":"归脾汤以茯神、远志、酸枣仁养心安神，人参、黄芪、白术、甘草益气健脾，当归、龙眼肉养血，木香理气醒脾，生姜、大枣调和，共奏益气补血、健脾养心之功，主治心脾两虚、气血不足之心悸怔忡、失眠健忘。茯神在方中宁心安神，针对心神失养；利水消肿、渗湿止泻为茯苓、白术健脾渗湿之用，涤痰除饮非茯神所长，健脾渗湿虽涉及茯苓，但本方用茯神意在养心安神"},{"q":"丁香柿蒂汤中不含有","o":["丁香","柿蒂","人参","生姜","大枣"],"a":4,"e":"丁香柿蒂汤由丁香、柿蒂、人参、生姜四味组成，丁香温中降逆、柿蒂降气止呃，人参益气，生姜温胃止呕，共奏温中益气、降逆止呃之功，主治胃气虚寒之呃逆。方中丁香、柿蒂、人参、生姜俱在，唯不含大枣，凡见大枣者皆非本方；大枣虽常用于调和脾胃，但本方药简力专，重在温胃降逆止呃，故不用大枣"},{"q":"下列各项，其中哪项不是旋覆代赭汤用药","o":["旋覆花、代赭石","人参、生姜","半夏","柴胡、黄芩","炙甘草、大枣"],"a":3,"e":"旋覆代赭汤由旋覆花、代赭石、半夏、人参、生姜、甘草、大枣组成，旋覆花消痰下气、降逆止噫，代赭石重镇降逆，半夏、生姜和胃降逆，人参、甘草、大枣益气和中，共奏降逆化痰、益气和胃之功，主治胃虚痰阻气逆之噫气不除。方中无柴胡、黄芩，二者为和解少阳之品，小柴胡汤、半夏泻心汤常用之；旋覆花、代赭石、人参、生姜、半夏、甘草、大枣皆在方中，故柴胡、黄芩非本方用药"},{"q":"被称为“仲景群方之冠”的方剂是","o":["正柴胡饮","麻黄汤","桂枝汤","小青龙汤","大青龙汤"],"a":2,"e":"桂枝汤由桂枝、芍药、生姜、大枣、甘草组成，功能解肌发表、调和营卫，主治外感风寒表虚证，为《伤寒论》首方，被后世誉为“仲景群方之冠”，其调和营卫、调和阴阳之法为众多方剂所本。正柴胡饮、麻黄汤、小青龙汤、大青龙汤虽皆为解表剂，但或重在发汗，或兼清里、化饮，皆无桂枝汤调和营卫之普适意义，故群方之冠专属桂枝汤"},{"q":"苏子降气汤的辨证要点是","o":["胸膈满闷，痰多稀白，苔白滑或白腻","哮喘咳嗽，痰多色黄，微恶风寒，苔黄腻，脉滑数","呕吐不渴，苔白滑","心下痞硬，嗳气频作，或呕吐，呃逆，苔白腻，脉缓或滑","呃逆或呕吐，舌红嫩，脉虚数"],"a":0,"e":"苏子降气汤以苏子降气化痰、止咳平喘为君，半夏、前胡、厚朴、陈皮降气化痰、宽胸，当归养血润燥、纳气归肾，肉桂温肾纳气，生姜、大枣、甘草调和，共奏降气平喘、祛痰止咳之功，主治上实下虚之喘咳，辨证要点为胸膈满闷、痰多稀白、苔白滑或白腻。痰多色黄、苔黄腻属定喘汤证，呕吐不渴属小半夏汤之类，心下痞硬、嗳气频作属旋覆代赭汤证，呃逆、舌红嫩脉虚数属橘皮竹茹汤证"},{"q":"真人养脏汤的君药是","o":["肉豆蔻","罂粟壳","诃子","肉桂","人参"],"a":1,"e":"真人养脏汤以罂粟壳涩肠止泻为君，专治久泻久痢、滑脱不禁；肉豆蔻、诃子助涩肠，人参、白术、甘草益气健脾，当归、白芍养血和血，木香理气，肉桂温阳，共奏涩肠固脱、温补脾肾之功。肉豆蔻、诃子为臣药助涩肠，肉桂温阳、人参益气皆为佐助，唯罂粟壳涩肠固脱之力最强，直折滑脱之势，故为君药"},{"q":"具有行气止痛，软坚散结功用的方剂为","o":["橘核丸","暖肝煎","天台乌药散","金铃子散","半夏厚朴汤"],"a":0,"e":"橘核丸以橘核行气散结、止痛为君，海藻、昆布、海带软坚散结，川楝子、延胡索行气活血止痛，厚朴、木香、枳实行气导滞，桃仁活血，肉桂温阳散寒，共奏行气止痛、软坚散结之功，主治寒湿疝气、睾丸肿胀偏坠。暖肝煎温补肝肾、行气止痛，天台乌药散行气疏肝、散寒止痛，金铃子散行气活血止痛，半夏厚朴汤行气散结、降逆化痰，皆无软坚散结之力，唯橘核丸兼具之"},{"q":"下列不属于桑螵蛸散组成的是","o":["龙骨","鳖甲","菖蒲","远志","当归"],"a":1,"e":"桑螵蛸散由桑螵蛸、远志、菖蒲、龙骨、人参、茯神、当归、龟甲组成，功能调补心肾、涩精止遗，主治心肾两虚之尿频、遗尿、滑精。方中有龙骨、菖蒲、远志、当归及龟甲，唯无鳖甲。鳖甲虽亦滋阴潜阳、软坚散结，但本方用龟甲滋阴益肾、镇心安神，二者不可混淆，故鳖甲不属于桑螵蛸散的组成药物"},{"q":"下列方剂中何方为“培土生金”法中的常用方剂","o":["补中益气汤","参苓白术散","归脾汤","生脉散","四君子汤"],"a":1,"e":"参苓白术散以人参、白术、茯苓益气健脾渗湿，山药、莲子肉、白扁豆、薏苡仁健脾渗湿止泻，砂仁醒脾和胃，桔梗宣肺利气、载药上行，甘草调和，共奏益气健脾、渗湿止泻之功，兼能补肺气，体现培土生金之法，主治脾虚湿盛之泄泻及肺脾气虚之咳嗽。补中益气汤补中升阳，归脾汤益气养血安神，生脉散益气养阴，四君子汤益气健脾，皆非培土生金之常用代表方"},{"q":"补阳还五汤原书用黄芪的量是","o":["一两","二两","三两","四两","五两"],"a":3,"e":"补阳还五汤原方黄芪用四两，取其大补元气、推动血行之意，配以当归尾、赤芍、川芎、桃仁、红花、地龙活血通络，共奏补气、活血、通络之功，主治气虚血瘀之中风后遗症。方中黄芪用量独重，远超余药，体现补气以行血的配伍思想。一两、二两、三两用量不足，五两则非原书之制，故原书用量为四两"},{"q":"九仙散的君药是","o":["五味子","乌梅","罂粟壳","桔梗","人参"],"a":2,"e":"九仙散以罂粟壳为君，敛肺止咳、涩肠止泻，专治久咳肺虚、咳喘不已；人参、黄芪、白术益气健脾，阿胶、五味子、乌梅滋阴敛肺，贝母、桑白皮清肺化痰、降气止咳，款冬花润肺止咳，共奏益气养阴、敛肺止咳之功。五味子、乌梅为臣药助收敛，人参补气，桔梗在本方非君，唯罂粟壳敛肺止咳之力最专，故为君药"},{"q":"主治证病机为“外感风寒，寒饮内停”的方剂是","o":["正柴胡饮","麻黄汤","桂枝汤","小青龙汤","大青龙汤"],"a":3,"e":"小青龙汤以麻黄、桂枝发汗解表、温通经脉，干姜、细辛温肺化饮，半夏燥湿化痰、降逆和胃，五味子敛肺止咳，芍药和营，甘草调和，共奏解表散寒、温肺化饮之功，主治外感风寒、寒饮内停之咳喘，症见恶寒发热、无汗、咳痰清稀。正柴胡饮、麻黄汤、桂枝汤纯解表而无化饮，大青龙汤发汗兼清里热，皆非外寒内饮之剂，唯小青龙汤表里兼顾"},{"q":"具有“解表散寒，温肺化饮”功用的方剂是","o":["苓甘五味姜辛汤","苓桂术甘汤","小青龙汤","华盖散","参苏饮"],"a":2,"e":"小青龙汤以麻黄、桂枝解表散寒，干姜、细辛温肺化饮，半夏化痰降逆，五味子敛肺、芍药和营，甘草调和，共奏解表散寒、温肺化饮之功，主治外感风寒、寒饮内停之喘咳。苓甘五味姜辛汤温肺化饮但无解表之力，苓桂术甘汤温阳化饮、健脾利湿，华盖散宣肺解表、止咳平喘，参苏饮益气解表、理气化痰，皆无解表散寒与温肺化饮并用之特点"},{"q":"滚痰丸中没有的药是","o":["大黄","礞石","沉香","瓜蒌仁","黄芩"],"a":3,"e":"滚痰丸（礞石滚痰丸）由礞石、大黄、黄芩、沉香组成，礞石磙逐顽痰，大黄泻热通便，黄芩清热燥湿，沉香行气降逆，共奏泻火逐痰之功，主治实热老痰、癫狂惊悸、大便秘结。方中大黄、礞石、沉香、黄芩俱在，唯无瓜蒌仁。瓜蒌仁虽能清热化痰、宽胸散结，常用于痰热咳嗽、胸痹，但非滚痰丸逐顽痰之组成，故为没有的药"},{"q":"下列各项中，属于羌活胜湿汤药物组成的是","o":["桑寄生","杜仲","白芷","秦艽","独活"],"a":4,"e":"羌活胜湿汤由羌活、独活、藁本、防风、蔓荆子、川芎、甘草组成，功能祛风胜湿止痛，主治风湿在表之肩背痛、腰脊头项痛。方中羌活、独活共为君药，祛风胜湿、通痹止痛，独活善治下部风湿，故属于本方组成。桑寄生、杜仲补肝肾、强筋骨，白芷祛风止痛、通鼻窍，秦艽清虚热、祛风湿，皆非羌活胜湿汤所用，故唯独活在其组成之列"},{"q":"具有润肠泻热，行气通便功能的方剂是","o":["五仁丸","脾约丸","济川煎","黄龙汤","小承气汤"],"a":1,"e":"脾约丸（麻子仁丸）以麻子仁润肠通便为君，杏仁降气润肠，芍药养血和阴，大黄泻热通便，枳实、厚朴行气导滞，共奏润肠泻热、行气通便之功，主治胃肠燥热、脾约便秘，大便干结、小便频数。五仁丸纯润肠燥，济川煎温肾益精、润肠通便，黄龙汤泻热通便、益气养血，小承气汤轻下热结，皆非润肠与泻热、行气并用之剂，唯脾约丸兼具之"},{"q":"表虚自汗证宜选用","o":["牡蛎散","青蒿鳖甲汤","桂枝汤","清骨散","玉屏风散"],"a":4,"e":"玉屏风散以黄芪益气固表为君，白术健脾益气、助黄芪固表为臣，防风走表祛风为佐，共奏益气固表止汗之功，主治表虚自汗、易感风邪，汗出恶风、面色㿠白。牡蛎散益气固表、敛阴止汗，主治自汗盗汗属卫外不固、阴液外泄；桂枝汤解肌发表、调和营卫，主治外感表虚证；青蒿鳖甲汤、清骨散清虚热，皆非表虚自汗之的选方"},{"q":"具有凉血止血，利水通淋功效的方剂是","o":["小蓟饮子","五苓散","导赤散","八正散","猪苓汤"],"a":0,"e":"小蓟饮子以小蓟、生地凉血止血为君，藕节、蒲黄止血消瘀，滑石、木通、淡竹叶清热利水通淋，栀子泻火除烦，当归养血和血、引血归经，甘草调和，共奏凉血止血、利水通淋之功，主治血淋、尿血，小便赤涩热痛。五苓散利水渗湿、温阳化气，导赤散清心利水养阴，八正散清热泻火、利水通淋，猪苓汤利水清热养阴，皆无凉血止血之能，唯小蓟饮子凉血止血与利水通淋并重"},{"q":"就方剂的组成而言，黄龙汤与乌梅丸共有的药物是","o":["附子、桂枝","人参、当归","黄连、黄柏","枳实、厚朴","生姜、大枣"],"a":1,"e":"黄龙汤含大黄、芒硝、枳实、厚朴、甘草、人参、当归、桔梗、生姜、大枣，乌梅丸含乌梅、细辛、干姜、黄连、当归、附子、蜀椒、桂枝、人参、黄柏，二方共有人参、当归。附子、桂枝只见于乌梅丸，黄连、黄柏只见于乌梅丸，枳实、厚朴只见于黄龙汤，生姜、大枣虽两方皆有但非选项所指，故人参、当归为二方共有之药"},{"q":"八法不包括的是","o":["补法","泻法","汗法","吐法","消法"],"a":1,"e":"方剂治法归纳为汗、吐、下、和、温、清、消、补八法。汗法解表，吐法涌吐，下法泻下通便，和法和解，温法温里，清法清热，消法消食化积，补法补益。泻法并非八法之一，攻下逐水、泻火逐痰等皆归于下法、清法范畴。补法、汗法、吐法、消法皆为八法内容，故不属于八法者为泻法，需注意下法与泻法名称之别"},{"q":"炙甘草汤的组成药物中含有","o":["麦冬、麻仁、枣仁","生地、元参、麦冬","阿胶、当归、芍药","生姜、大枣、黄芪","生地、阿胶、麦冬"],"a":4,"e":"炙甘草汤由炙甘草、生姜、桂枝、人参、生地黄、阿胶、麦冬、麻仁、大枣组成，功能益气滋阴、通阳复脉，主治气血阴阳俱虚之脉结代、心动悸。方中含生地、阿胶、麦冬以滋阴养血，故为正确项。麻仁为火麻仁，非枣仁；元参不在方中；当归、芍药非本方所有；黄芪、茯苓亦非本方药物，故含枣仁、元参、当归、黄芪诸项皆非炙甘草汤组成"},{"q":"牵正散证的病机是","o":["风邪初中头面经络","风湿阻于头面经络","风寒侵袭头面经络","风热侵袭头面经络","风痰阻于头面经络"],"a":4,"e":"牵正散由白附子、白僵蚕、全蝎组成，功能祛风化痰、通络止痉，主治风痰阻于头面经络之口眼㖞斜。方中白附子辛温祛风化痰，白僵蚕、全蝎搜风通络止痉，针对风痰痹阻头面经络而设。风邪初中、风湿阻络、风寒侵袭、风热侵袭虽皆涉及外邪，但本方专为风痰阻络、口眼㖞斜而制，重在化痰通络，故病机为风痰阻于头面经络"},{"q":"下列各项中，属于实脾散药物组成的是","o":["高良姜","大腹皮","砂仁","白芍","木瓜"],"a":4,"e":"实脾散由附子、干姜、白术、茯苓、厚朴、木香、大腹皮、草果、木瓜、甘草、生姜、大枣组成，功能温阳健脾、行气利水，主治阴水。木瓜在方中芳香化湿、舒筋活络，助行气利湿，故属于本方组成。高良姜温胃止痛，砂仁化湿行气，白芍养血柔肝，均非实脾散药物，其中白芍阴柔，与阴水当温化之旨不符，故唯木瓜在其组成之列"},{"q":"以下关于天麻钩藤饮证的辨证要点描述错误的是","o":["头痛","眩晕","痉厥","失眠","脉弦"],"a":2,"e":"天麻钩藤饮以天麻、钩藤平肝息风为君，石决明平肝潜阳，黄芩、栀子清热泻火，牛膝引血下行，杜仲、桑寄生补肝肾，茯神、夜交藤安神，益母草活血利水，共奏平肝息风、清热活血、补益肝肾之功，主治肝阳上亢、肝风内动之眩晕、头痛、失眠、脉弦数。痉厥为热极生风、肝风内动之重症，多见羚角钩藤汤证，非本方辨证要点，故痉厥描述错误"},{"q":"半夏泻心汤的功用是","o":["和胃消痞，散结除水","益气和胃，消痞止呕","寒热平调，散结除痞","平调寒热，理气和胃","泻火解毒，燥湿消痞"],"a":2,"e":"半夏泻心汤以半夏和胃降逆、散结除痞为君，干姜温中散寒，黄芩、黄连清热泄痞，人参、大枣、甘草益气和中，共奏寒热平调、散结除痞之功，主治寒热错杂之痞证，心下痞、但满不痛、呕吐、肠鸣泄泻。和胃消痞、散结除水近似十枣、陷胸之意，益气和胃、消痞止呕偏于旋覆代赭，泻火解毒、燥湿消痞属黄连类方，皆非半夏泻心汤寒热平调之配伍核心"},{"q":"中国历史上第一部由政府编制的成药药典是","o":["《五十二病方》","《太平惠民和剂局方》","《太平圣惠方》","《肘后备急方》","《普济方》"],"a":1,"e":"《太平惠民和剂局方》为宋代太平惠民和剂局所编，是我国历史上第一部由政府组织编制的成药药典，收载大量成方，对后世方剂学影响深远。《五十二病方》为现存最早医方书，非政府编制；《太平圣惠方》为宋代官修大型方书，但晚于局方且非成药药典性质；《肘后备急方》为葛洪所撰；《普济方》为明代大型方书，皆非第一部政府编制的成药药典"},{"q":"何方主治营血虚滞证","o":["四物汤","归脾汤","当归补血汤","胶艾汤","八珍汤"],"a":0,"e":"四物汤以熟地黄滋阴养血、填精益髓为君，当归养血活血、调经，白芍养血柔肝，川芎活血行气，共奏补血和血、调经化瘀之功，主治营血虚滞证，症见心悸失眠、头晕目眩、面色无华、月经量少色淡或经闭、脐腹作痛。归脾汤益气补血、健脾养心，当归补血汤补气生血，胶艾汤养血止血、调经安胎，八珍汤气血双补，皆非专为营血虚滞而设"},{"q":"香薷散主治证为","o":["阴暑","阳暑","暑湿证","湿温证","暑温证"],"a":0,"e":"香薷散以香薷发汗解表、祛暑化湿为君，厚朴行气燥湿、和胃除满，白扁豆健脾化湿，共奏祛暑解表、化湿和中之功，主治阴暑，即夏月乘凉饮冷、外感风寒、内伤湿滞之恶寒发热、无汗、头痛身重、胸闷腹痛吐泻。阳暑、暑温为盛夏暑热炽盛，治宜清暑益气、白虎、清营之类；湿温证属湿热蕴结，暑湿证范围更广，皆非香薷散所主的阴暑"},{"q":"大秦艽汤与小续命汤组成中共有的药物是","o":["白芷、防风、细辛、生地","羌活、黄芩、川芎、麻黄","麻黄、杏仁、肉桂、甘草","川芎、黄芩、熟地、附子","黄芩、防风、川芎、甘草"],"a":4,"e":"大秦艽汤含秦艽、川芎、独活、当归、白芍、石膏、甘草、羌活、防风、白芷、黄芩、白术、茯苓、生地、熟地、细辛；小续命汤含麻黄、防己、人参、黄芩、桂枝、甘草、芍药、川芎、杏仁、附子、防风、生姜。二方共有黄芩、防风、川芎、甘草。白芷、细辛、生地只见于大秦艽汤，麻黄、杏仁、肉桂只见于小续命汤，故所列共有药为黄芩、防风、川芎、甘草"},{"q":"下列哪项不是脾约丸的组成药物","o":["芍药","大黄","芒硝","杏仁","枳实"],"a":2,"e":"脾约丸（麻子仁丸）由麻子仁、芍药、枳实、大黄、厚朴、杏仁六味组成，功能润肠泻热、行气通便，主治胃肠燥热、脾约便秘。方中芍药养血和阴，大黄泻热通便，杏仁降气润肠，枳实、厚朴行气导滞，唯不含芒硝。芒硝咸寒软坚润燥，为调胃承气、大承气之用，本方重在润肠泻热、缓下，不用芒硝之峻，故芒硝非脾约丸组成药物"},{"q":"蒿芩清胆汤中具有芳香透热作用的药物是","o":["淡竹茹","青子芩","陈广皮","青蒿脑","仙半夏"],"a":3,"e":"蒿芩清胆汤中青蒿脑（青蒿）辛苦寒，芳香透热、清泄少阳湿热，引邪热外出，为方中芳香透热之品，与黄芩清胆泄热相须为君。淡竹茹、仙半夏和胃降逆化痰，青子芩即黄芩清胆热，陈广皮理气，皆非芳香透热之主；青蒿芳香清透，善治少阳湿热、寒热如疟，故具芳香透热作用者为青蒿脑"},{"q":"功用为清宣温燥，润肺止咳的方剂是","o":["杏苏散","清燥救肺汤","麦门冬汤","桑杏汤","桑菊饮"],"a":3,"e":"桑杏汤以桑叶轻宣温燥、杏仁润肺止咳为君，贝母化痰止咳，沙参、梨皮养阴润肺，栀子清泄燥热，共奏清宣温燥、润肺止咳之功，主治外感温燥、肺津受灼之轻证，干咳无痰或痰少而黏、身热不甚。杏苏散轻宣凉燥，清燥救肺汤清燥润肺、治温燥重证，麦门冬汤滋养肺胃、降逆下气，桑菊饮疏风清热、宣肺止咳，皆非清宣温燥、润肺止咳之轻剂"},{"q":"主治妇人中风，热入血室而见经水适断，寒热发作有时的方剂是","o":["小柴胡汤","温经汤","逍遥散","血府逐瘀汤","青蒿鳖甲汤"],"a":0,"e":"小柴胡汤由柴胡、黄芩、半夏、人参、甘草、生姜、大枣组成，功能和解少阳，主治伤寒少阳证及妇人热入血室，症见经水适断、寒热发作有时。柴胡、黄芩和解少阳，半夏、生姜和胃降逆，人参、大枣、甘草益气和中，使邪从外解。温经汤温经散寒、养血祛瘀，逍遥散疏肝解郁、养血健脾，血府逐瘀汤活血化瘀、行气止痛，青蒿鳖甲汤养阴透热，皆非热入血室、经水适断之的方"},{"q":"咳血方中用以清热化痰，止咳的药物是","o":["瓜蒌仁","薏苡仁","柏子仁","杏仁","胡麻仁"],"a":0,"e":"咳血方以青黛、栀子清肝泻火、凉血止血为君，瓜蒌仁清热化痰、润燥止咳，诃子敛肺止咳，海粉（海浮石）清肺化痰、软坚，共奏清肝宁肺、凉血止血之功，主治肝火犯肺之咳血。瓜蒌仁在方中清热化痰、止咳，针对痰热咳嗽；薏苡仁健脾渗湿、排脓，柏子仁养心安神，杏仁降气止咳但非本方所用，胡麻仁润燥，皆非咳血方中清热化痰止咳之药，故为瓜蒌仁"},{"q":"小蓟饮子与八正散共有的药物是","o":["小蓟、生地黄","生地黄、山栀子","滑石、山栀子","小蓟、大黄","大黄、淡竹叶"],"a":2,"e":"小蓟饮子含小蓟、生地、滑石、木通、蒲黄、藕节、淡竹叶、当归、山栀子、甘草；八正散含车前子、瞿麦、萹蓄、滑石、山栀子、甘草、木通、大黄。二方共有滑石、山栀子、木通、甘草，选项中为滑石、山栀子。小蓟、生地黄只见于小蓟饮子，大黄、淡竹叶亦非两方共有，故滑石、山栀子为二方共有之药，二者清热利水通淋，体现两方治淋的共同点"},{"q":"逍遥散中体现“实土以御木乘”的药物配伍是","o":["白术、茯苓、甘草","当归、白芍、大枣","柴胡、薄荷、生姜","白术、当归、柴胡","大枣、甘草、茯苓"],"a":0,"e":"逍遥散中白术、茯苓、甘草健脾益气、培土抑木，使脾土健运以抵御肝木之乘，体现实土以御木乘的配伍思想，主治肝郁血虚脾弱之胁痛、月经不调。当归、白芍养血柔肝以补肝体，柴胡、薄荷疏肝解郁以助肝用，生姜和胃，大枣、甘草调和，诸药相合疏肝解郁、养血健脾。凡以当归、白芍或柴胡、薄荷、生姜为实土御木者，皆混淆了补肝体、疏肝用与实土御木的不同配伍"},{"q":"下列诸法中，不属于“八法”内容的是","o":["汗法、吐法","下法、清法","宣法、通法","清法、补法","和法、温法"],"a":2,"e":"八法为汗、吐、下、和、温、清、消、补。汗法发汗解表，吐法涌吐，下法泻下，和法和解，温法温里，清法清热，消法消导，补法补益。宣法、通法不在八法之列，宣肺、通腑等具体治法可分别归属于汗法、下法等范畴。汗法与吐法、下法与清法、清法与补法、和法与温法皆为八法内容，故不属于八法者为宣法、通法"},{"q":"蒿芩清胆汤中具有“导湿热从小便而去”作用的药物是","o":["木通、车前子","苍术、黄柏","茯苓、滑石","泽泻、防己","猪苓、薏苡仁"],"a":2,"e":"蒿芩清胆汤中茯苓、滑石淡渗利湿、清热利尿，使湿热之邪从小便而去，与青蒿、黄芩清泄少阳湿热，半夏、竹茹、陈皮、枳壳和胃化痰相配，共奏清胆利湿、和胃化痰之功。木通、车前子、泽泻、防己、猪苓、薏苡仁虽均利湿，但非本方所用；苍术、黄柏燥湿清热属二妙散，故蒿芩清胆汤中导湿热从小便而去者为茯苓、滑石"},{"q":"旋覆代赭汤主治","o":["胃虚痰阻证","脾虚生痰证","脾虚湿停证","胃虚有热呃逆证","胃气虚寒呃逆证"],"a":0,"e":"旋覆代赭汤以旋覆花消痰下气、降逆止噫，代赭石重镇降逆，半夏、生姜和胃降逆、散结除痰，人参、甘草、大枣益气和中，共奏降逆化痰、益气和胃之功，主治胃虚痰阻气逆证，症见心下痞硬、噫气不除、反胃呕吐。脾虚生痰、脾虚湿停侧重脾失健运，胃虚有热呃逆属橘皮竹茹汤，胃气虚寒呃逆属丁香柿蒂汤，皆非本方胃虚痰阻之主治"},{"q":"《温热经纬》清暑益气汤的主治证为","o":["暑湿证","暑热气津两伤证","暑温证","暑温夹湿证","阴暑"],"a":1,"e":"《温热经纬》清暑益气汤以西洋参、石斛、麦冬益气养阴生津，黄连、竹叶清暑泻火，荷梗、西瓜翠衣清热解暑，知母清热滋阴，粳米、甘草益气和中，共奏清暑益气、养阴生津之功，主治暑热气津两伤证，身热汗多、口渴心烦、体倦少气、脉虚数。暑湿证、暑温证、暑温夹湿证侧重湿邪，阴暑为寒湿袭表，皆非气津两伤之的证，故本方所主为暑热气津两伤"},{"q":"苏子降气汤的病变脏腑是","o":["脾肺","肺胃","脾肾","肺肾","脾肺肾"],"a":3,"e":"苏子降气汤主治上实下虚之喘咳，病变脏腑在肺肾：肺气壅实、痰浊上泛则胸膈满闷、咳喘痰多，肾阳不足、纳气无权则呼多吸少、腰膝酸软。方以苏子、半夏、前胡、厚朴、陈皮降气化痰治其上实，肉桂温肾纳气、当归养血纳气治其下虚，甘草调和。脾肺、肺胃、脾肾、脾肺肾皆未切中本方上实（肺）下虚（肾）的核心病机，故病变脏腑为肺肾"},{"q":"组成中包括干姜与生姜的方剂为","o":["苏子降气汤","厚朴温中汤","暖肝煎","天台乌药散","枳实消痞丸"],"a":1,"e":"厚朴温中汤由厚朴、草豆蔻、陈皮、木香、茯苓、干姜、甘草、生姜组成，功能温中行气、燥湿除满，主治脾胃寒湿气滞之脘腹胀满疼痛。方中干姜温中散寒，生姜温胃散寒、和胃，二姜同用，温中散寒之力增强，故为所问。苏子降气汤、暖肝煎、天台乌药散、枳实消痞丸虽各有温行之选，但不同时含有干姜与生姜，唯厚朴温中汤二者兼备"},{"q":"不属于黄连解毒汤主治证候的是","o":["大热烦躁","错语不眠","热病吐血","大便秘结","小便黄赤"],"a":3,"e":"黄连解毒汤以黄连清心胃之火为君，黄芩清上焦之火，黄柏清下焦之火，栀子通泄三焦之火，共奏泻火解毒之功，主治三焦火毒热盛证，症见大热烦躁、口燥咽干、错语不眠、热病吐血衄血、湿热黄疸、小便黄赤。本方纯用苦寒泻火解毒，无通便泻下之功，故大便秘结非其主治证候；若见大便秘结，当配伍大黄等通腑之品，或改用泻下剂，故大便秘结不属于黄连解毒汤主治"},{"q":"白虎汤与竹叶石膏汤共有的药物是","o":["粳米","知母","人参","半夏","麦门冬"],"a":0,"e":"白虎汤由石膏、知母、炙甘草、粳米组成，竹叶石膏汤由竹叶、石膏、半夏、麦冬、人参、炙甘草、粳米组成，二方共有石膏、炙甘草、粳米，选项中为粳米。知母只见于白虎汤，人参、半夏、麦冬只见于竹叶石膏汤，故粳米为二方共有。粳米在两方中益胃生津、护中，防石膏、知母大寒伤胃，体现清热剂顾护胃气之旨"},{"q":"桂枝汤、小建中汤、当归四逆汤相同的药物是","o":["桂枝、芍药、甘草、大枣","桂枝、芍药、甘草、生姜","桂枝、芍药、生姜、大枣","芍药、甘草、生姜、大枣","桂枝、甘草、生姜、大枣"],"a":0,"e":"桂枝汤由桂枝、芍药、生姜、大枣、甘草组成，小建中汤由桂枝、芍药、甘草、生姜、大枣、饴糖组成，当归四逆汤由当归、桂枝、芍药、细辛、甘草、大枣、木通组成，三方共有桂枝、芍药、甘草、大枣。生姜只见于桂枝汤、小建中汤，当归四逆汤用细辛、木通而无生姜，故凡含生姜选项皆非三方共有，唯桂枝、芍药、甘草、大枣为三方所同有"},{"q":"四神丸的君药是","o":["肉豆蔻","五味子","吴茱萸","补骨脂","生姜"],"a":3,"e":"四神丸以补骨脂为君，辛苦大温，补命门之火以温养脾土，针对五更泄泻之命门火衰、火不暖土；肉豆蔻温中涩肠为臣，五味子敛肠止泻、吴茱萸温中散寒为佐，生姜、大枣温中健胃为使，共奏温肾暖脾、固肠止泻之功。肉豆蔻、五味子、吴茱萸、生姜皆为臣佐使药，助君温阳涩肠，唯补骨脂温补肾阳、暖命门火之力最著，故为君药"},{"q":"六味地黄丸的臣药是","o":["山药、泽泻","山萸肉、牡丹皮","山药、山萸肉","泽泻、牡丹皮","牡丹皮、茯苓"],"a":2,"e":"六味地黄丸以熟地黄滋阴补肾、填精益髓为君，山茱萸补养肝肾、涩精，山药补益脾肾、固精，二者共为臣药，助君滋补三阴；泽泻利湿泄浊、牡丹皮清泄相火、茯苓淡渗脾湿为佐使，合称三泻。山药、泽泻中泽泻为佐，山萸肉、牡丹皮中牡丹皮为佐，泽泻、牡丹皮皆非臣药，故唯山药、山萸肉为臣药，体现三补为主、三泻为佐的配伍"},{"q":"湿热食积，内阻胃肠证，治疗时当首选","o":["保和丸","木香导滞丸","健脾丸","枳实导滞丸","半夏泻心汤"],"a":3,"e":"枳实导滞丸以枳实消积导滞、下气除满为君，大黄泻热通便，黄芩、黄连清热燥湿，神曲消食化积，茯苓、泽泻利湿，白术健脾燥湿，共奏消积导滞、清利湿热之功，主治湿热食积、内阻胃肠之脘腹胀痛、下痢泄泻、大便秘结。保和丸消食和胃，主治食积；木香导滞丸行气导滞；健脾丸健脾消食；半夏泻心汤寒热平调、消痞散结，皆非湿热食积内阻之首选，故用枳实导滞丸"},{"q":"十枣汤的最佳服药时间是","o":["饭后服","饭前服","平旦服","睡前服","不拘时服"],"a":2,"e":"十枣汤以甘遂、大戟、芫花逐水峻药配大枣益气护胃，功能攻逐水饮，主治悬饮、水肿实证。因三味逐水药力峻猛，易伤胃气，故宜平旦（清晨空腹）服，使药力专行攻逐，并配大枣缓和大戟、甘遂、芫花之毒性，服后得快利即止。饭后、饭前、睡前、不拘时服皆非十枣汤最佳服药时间，清晨空腹服可减少对胃气的影响并使攻逐之力集中"},{"q":"主治“痛泻”的方剂是","o":["真人养脏汤","参苓白术散","痛泻要方","四神丸","乌梅丸"],"a":2,"e":"痛泻要方以白术健脾燥湿为君，白芍柔肝缓急止痛，陈皮理气醒脾，防风散肝舒脾、胜湿，共奏补脾柔肝、祛湿止泻之功，主治痛泻，症见肠鸣腹痛、大便泄泻、泻后痛不解，病机为土虚木乘。真人养脏汤涩肠固脱、温补脾肾，主治久泻久痢滑脱；参苓白术散益气健脾、渗湿止泻；四神丸温肾暖脾、固肠止泻治五更泻；乌梅丸温脏安蛔，皆非治痛泻之方"},{"q":"五苓散与猪苓汤共同的药物是","o":["阿胶","泽泻","桂枝","滑石","白术"],"a":1,"e":"五苓散由茯苓、猪苓、泽泻、白术、桂枝组成，猪苓汤由猪苓、茯苓、泽泻、阿胶、滑石组成，二方共有茯苓、猪苓、泽泻，选项中为泽泻。阿胶、滑石只见于猪苓汤，桂枝、白术只见于五苓散，故泽泻为二方共有。泽泻在五苓散中利水渗湿、助膀胱气化，在猪苓汤中利水清热，二者均取其利水渗湿之用，体现了利水剂的共同配伍"},{"q":"止嗽散的功用是","o":["宣利肺气，缓急止痛","发汗解表，宣肺平喘","宣利肺气，疏风止咳","解表散寒，温肺化饮","发汗解表，降逆止咳"],"a":2,"e":"止嗽散以桔梗、白前宣肺降气、化痰止咳，荆芥疏风解表，紫菀、百部润肺止咳，陈皮理气化痰，甘草调和，共奏宣利肺气、疏风止咳之功，主治风邪犯肺之咳嗽，症见咳嗽咽痒、咯痰不爽、微恶风发热。宣利肺气、缓急止痛非本方功用，发汗解表、宣肺平喘属麻黄汤，解表散寒、温肺化饮属小青龙汤，发汗解表、降逆止咳亦非止嗽散之的，本方重在疏风宣肺止咳，药性平和"},{"q":"当归六黄汤中“六黄”是指","o":["黄芩、黄连、黄柏、黄芪、生地黄、熟地黄","黄芩、黄连、大黄、黄芪、生地黄、熟地黄","黄芩、黄连、大黄、麻黄、生地黄、熟地黄","黄芩、姜黄、大黄、麻黄、生地黄、熟地黄","黄柏、姜黄、大黄、麻黄、生地黄、熟地黄"],"a":0,"e":"当归六黄汤中六黄指黄芩、黄连、黄柏、黄芪、生地黄、熟地黄：三黄（芩、连、柏）泻火坚阴，黄芪益气固表，生地、熟地滋阴养血、清热凉血，配当归养血，共奏滋阴泻火、固表止汗之功，主治阴虚火旺之盗汗。方中无大黄、麻黄、姜黄，凡含大黄、麻黄、姜黄诸项皆非六黄所指；三黄泻火、二地滋阴、黄芪固表，是本方滋阴降火、固表止汗的配伍核心"},{"q":"香薷散的功用是","o":["解表散寒，温肺化饮","发汗解表，兼清里热","祛暑解表，化湿和中","发汗祛湿，兼清里热","清暑益气，养阴生津"],"a":2,"e":"香薷散以香薷为君，辛温芳香，发汗解表、祛暑化湿，厚朴行气燥湿、和胃除满为臣，白扁豆健脾化湿为佐，共奏祛暑解表、化湿和中之功，主治阴暑，外感风寒、内伤湿滞之恶寒发热、无汗、腹痛吐泻。解表散寒、温肺化饮属小青龙汤，发汗解表、兼清里热属大青龙汤，清暑益气、养阴生津属清暑益气汤、生脉散，皆非香薷散祛暑解表、化湿和中之功"},{"q":"《古今医鉴》所载参苓白术散，较《局方》参苓白术散方多何药","o":["木香","枳壳","半夏","苍术","陈皮"],"a":4,"e":"《古今医鉴》所载参苓白术散较《太平惠民和剂局方》参苓白术散多陈皮一味，陈皮理气化湿、和胃，加强本方健脾渗湿、行气和中之功，主治脾虚湿盛之泄泻、咳嗽痰多。木香、枳壳、半夏、苍术虽皆为健脾化湿、理气常用药，但均非《古今医鉴》本方较《局方》所加之药，故所多之药为陈皮，体现两书所载本方在理气方面的增补"},{"q":"具有益气生津，敛阴止汗作用的方剂是","o":["四君子汤","补中益气汤","桂枝汤","生脉散","牡蛎散"],"a":3,"e":"生脉散以人参益气生津为君，麦冬养阴清热、润肺生津为臣，五味子敛肺止咳、敛阴止汗为佐，三药合用，共奏益气生津、敛阴止汗之功，主治气阴两虚之体倦气短、咽干口渴、自汗、脉虚数，或久咳肺虚之干咳少痰。四君子汤益气健脾，补中益气汤补中升阳，桂枝汤解肌调和营卫，牡蛎散益气固表、敛阴止汗，皆非益气生津、敛阴止汗之剂，唯生脉散三者兼备"},{"q":"甘麦大枣汤的功用是","o":["养心安神，清热解毒","养心安神，健脾燥湿","养心安神，和中缓急","养血安神，定惊止痛","养心安神，缓急止痛"],"a":2,"e":"甘麦大枣汤以甘草缓急和中、润肺，小麦养心安神、除烦，大枣益气养血、安神，三药合用，共奏养心安神、和中缓急之功，主治脏躁，症见精神恍惚、悲伤欲哭、心中烦乱、睡眠不安。养心安神、清热解毒非本方功用，健脾燥湿、定惊止痛、缓急止痛虽涉及甘草、大枣，但本方专为心阴不足、肝气失和之脏躁而设，重在养心安神、和中缓急，故养心安神、和中缓急为其功用"},{"q":"苏子降气汤的组成中含有","o":["陈皮、苏子","枳壳、桔梗","当归、杏仁","百部、前胡","当归、肉桂"],"a":4,"e":"苏子降气汤含紫苏子、半夏、前胡、厚朴、当归、肉桂、甘草、生姜、大枣、苏叶，当归养血和血、肉桂温肾纳气，共治上实下虚喘咳。陈皮为二陈汤、藿香正气散之药，本方理气化痰靠半夏、厚朴；杏仁是定喘汤宣肺之品，本方不用；前胡虽在方内，但配伍的百部不在，不可混认"},{"q":"治疗温疟，应首选的方剂是","o":["白虎汤","达原饮","败毒散","白虎加桂枝汤","白虎加人参汤"],"a":3,"e":"白虎加桂枝汤于白虎汤中加桂枝，既清气分实热生津，又温通经脉、解肌和营，为治温疟热多寒少之主方。白虎汤只清气分实热，无温通和营之力；白虎加人参汤兼益气生津，主气阴两伤；达原饮开达膜原、辟秽化浊，治瘟疫邪伏膜原；败毒散益气解表，治气虚外感，均非温疟所宜"},{"q":"苏子降气汤、定喘汤共有的药物为","o":["前胡","白芥子","杏仁","厚朴","苏子"],"a":4,"e":"苏子降气汤与定喘汤均含苏子，借其降气化痰、止咳平喘，是两方共有的降逆要药。前胡、厚朴仅见于苏子降气汤，功在降气化痰、宽胸；杏仁、款冬花、桑白皮、黄芩、白果只用于定喘汤，清肺化痰、敛肺定喘；白芥子善祛皮里膜外之痰，两方皆未用"},{"q":"四神丸的主治证是","o":["脾泄","肾泄","痛泄","虚痢","寒痢"],"a":1,"e":"四神丸由补骨脂、肉豆蔻、五味子、吴茱萸（加生姜、大枣）组成，温肾暖脾、固肠止泻，主治脾肾阳虚、命门火衰之五更泄泻，又称肾泄。脾泄多脾气虚弱、运化失司，治宜健脾；痛泄乃肝郁脾虚、腹痛即泻，属痛泻要方证；虚痢、寒痢为痢疾日久或寒湿痢，均非四神丸所主"},{"q":"温脾汤主治证候的病机是","o":["脾阳不足、寒积中阻","津枯肠燥、气机阻滞","饮食积滞、气机壅塞","里寒积滞、阳气不运","肾虚津亏、开合失司"],"a":0,"e":"温脾汤以附子、干姜温脾阳、散寒凝，大黄攻逐寒积，人参、甘草益气和中，主治脾阳不足、寒积中阻之便秘腹痛，故病机为脾阳不足、寒积中阻。津枯肠燥、气机阻滞是麻子仁丸之脾约；饮食积滞、气机壅塞属保和丸类；里寒积滞、阳气不运未点明脾阳不足这一关键；肾虚津亏、开合失司为济川煎所主"},{"q":"参苓白术散在何方的基础上加砂仁、山药、莲子、白扁豆、薏苡仁、桔梗而成","o":["四君子汤","异功散","六君子汤","玉屏风散","补中益气汤"],"a":0,"e":"参苓白术散以四君子汤（人参、白术、茯苓、甘草）益气健脾为底方，再加山药、莲子、白扁豆、薏苡仁健脾渗湿止泻，砂仁醒脾和胃、行气化湿，桔梗宣肺利气、载药上行，体现培土生金。异功散仅四君子加陈皮；六君子汤再加半夏、陈皮；玉屏风散为黄芪、白术、防风；补中益气汤重在升提中气，皆非其基础方"},{"q":"大补阴丸的脉象特点是","o":["脉沉细数","尺脉数而有力","尺脉数而无力","尺脉细数","脉虚数"],"a":1,"e":"大补阴丸滋阴降火，主治阴虚火旺、相火妄动，见骨蒸潮热、盗汗遗精、舌红少苔，尺脉数而有力为相火偏亢之象。尺脉数而无力或细数多为阴虚而火不旺；脉沉细数见阴虚兼里；脉虚数偏气阴两虚。本方以知母、黄柏泻相火，熟地、龟板滋阴，重在泻有余之火，故取有力之数脉为辨证眼目"},{"q":"温胆汤的功用是","o":["燥湿行气，软坚化痰","燥湿化痰，理气和中","理气化痰，和胃利胆","清热化痰，宽胸散结","温肺化痰，降逆消食"],"a":2,"e":"温胆汤由半夏、竹茹、枳实、陈皮、茯苓、甘草、生姜、大枣组成，理气化痰、和胃利胆，主治胆郁痰扰之惊悸不寐、呕吐呃逆、口苦苔腻。燥湿化痰、理气和中是二陈汤功用，本方加竹茹、枳实，增清化痰热、和胃利胆之力；清热化痰、宽胸散结为小陷胸汤；温肺化痰、降逆消食非本方所具"},{"q":"以“燥淫于内，治以苦温，佐以甘辛”为治则的方剂是","o":["桑杏汤","杏苏散","清燥救肺汤","百合固金汤","麦门冬汤"],"a":1,"e":"杏苏散轻宣凉燥、理肺化痰，主治外感凉燥之头微痛、恶寒、咳嗽痰稀、鼻塞咽干，本于燥淫于内、治以苦温、佐以甘辛之则，以苏叶、前胡苦温宣散，杏仁、桔梗、枳壳等宣降。桑杏汤、清燥救肺汤治温燥，宜辛凉甘润，与此相反；百合固金汤滋肾润肺，麦门冬汤养阴润肺、降逆下气，均非治凉燥之方"},{"q":"主治“类中风”的代表方是","o":["大秦艽汤","牵正散","镇肝熄风汤","天麻钩藤饮","羚角钩藤汤"],"a":2,"e":"镇肝熄风汤镇肝息风、滋阴潜阳，主治类中风（肝阳上亢、气血上逆）之头晕目眩、脑部热痛、面色如醉、肢体渐觉不利。大秦艽汤疏风清热、养血活血，治风邪中经络；牵正散祛风化痰，专治风痰阻络之口眼歪斜；天麻钩藤饮平肝息风、清热安神，治肝阳上亢较轻者；羚角钩藤汤凉肝息风，主热盛动风"},{"q":"小陷胸汤之功用是","o":["清热化痰，宽胸散结","清热化痰，理气止咳","温肺散寒，涤痰化饮","燥湿化痰，平肝息风","荡涤实热，攻逐顽痰"],"a":0,"e":"小陷胸汤由黄连、半夏、瓜蒌组成，黄连清热泻火，半夏化痰散结，瓜蒌清热化痰、宽胸散结，共奏清热化痰、宽胸散结之功，主治痰热互结之小结胸证。清热化痰、理气止咳为清气化痰丸；温肺散寒、涤痰化饮是苓甘五味姜辛汤类；燥湿化痰、平肝息风非本方；荡涤实热、攻逐顽痰属大陷胸汤、礞石滚痰丸"},{"q":"四逆散所治厥逆，正如李中梓云：“此证虽云四逆，必不甚冷，或指头微温，或脉不沉微，乃阴中涵阳之证，唯（ ），是为逆冷。”","o":["气不宣通","血不疏散","肾阳虚衰","阴血不濡","痰湿凝滞"],"a":0,"e":"四逆散透邪解郁、疏肝理脾，所治四逆乃肝郁气滞、阳气内郁、不达四末所致，李中梓所谓唯气不宣通是为逆冷，即指此气郁致厥，故虽四逆而不甚冷、指头微温、脉不沉微。肾阳虚衰之四逆必四肢厥冷、脉沉微，属四逆汤证；血不疏散、阴血不濡、痰湿凝滞皆非四逆散厥逆之机，本方以柴胡、芍药、枳实、甘草疏肝和脾、透达郁阳"},{"q":"用治风热湿毒，壅遏肠道之便血的方剂是","o":["理中丸","黄土汤","槐花散","十灰散","四生丸"],"a":2,"e":"槐花散清肠止血、疏风行气，由槐花、侧柏叶、荆芥穗、枳壳组成，主治风热湿毒壅遏肠道、损伤血络之便血，血色鲜红。理中丸温中健脾，主脾胃虚寒之便血；黄土汤温阳健脾、养血止血，主脾阳不足、脾不统血之便血，血色暗淡；十灰散凉血止血，主血热妄行诸出血；四生丸重在凉血，非专治肠道便血"},{"q":"缩泉丸的主治证是","o":["脾肾虚寒证","肝肾虚寒证","膀胱虚寒证","脾胃虚寒证","肠胃虚寒证"],"a":2,"e":"缩泉丸由益智仁、乌药、山药组成，益智仁温肾缩尿，乌药温膀胱、行气散寒，山药健脾补肾，共奏温肾祛寒、缩尿止遗之功，主治膀胱虚寒之尿频、遗尿。脾肾虚寒、肝肾虚寒多兼阳虚寒象，非本方所主；脾胃虚寒、肠胃虚寒病在中焦，见腹痛泄泻，与膀胱失约之遗尿无关，本方关键在膀胱气化失司、约束无权"},{"q":"三仁汤中渗湿且能健脾的药物是","o":["杏仁","竹叶","滑石","薏仁","通草"],"a":3,"e":"三仁汤中薏苡仁甘淡微寒，健脾渗湿、舒筋除痹，渗湿而兼健脾，切合湿温初起湿重于热之病机。杏仁宣利上焦肺气，气化则湿亦化，重在开上；滑石、通草甘寒淡渗，清热利湿，导湿热从小便而去，无健脾之功；竹叶清心利水，清上焦之热。三仁分消三焦，唯薏苡仁渗湿而不伤正、兼能健脾"},{"q":"治疗寒饮咳嗽的常用方是","o":["苓桂术甘汤","止嗽散","小青龙汤","苓甘五味姜辛汤","二陈汤"],"a":3,"e":"苓甘五味姜辛汤温肺化饮，由茯苓、甘草、干姜、细辛、五味子组成，主治寒饮内停之咳嗽痰多清稀、胸膈满闷，为治寒饮咳嗽常用方，重在温化内饮而无解表之力。小青龙汤解表散寒、温肺化饮，主外寒内饮兼表证；苓桂术甘汤温阳化饮、健脾利湿，主中阳不足之痰饮；二陈汤燥湿化痰、理气和中，治湿痰；止嗽散疏风润肺，主风邪犯肺咳嗽"},{"q":"猪苓汤证的病机是","o":["瘀热互结伤阴","痰热互结伤阴","水热互结伤阴","寒湿互结伤阴","湿热互结伤阴"],"a":2,"e":"猪苓汤由猪苓、茯苓、泽泻、滑石、阿胶组成，利水渗湿、清热养阴，主治水热互结、邪热伤阴之小便不利、发热口渴、心烦不寐，或血淋尿血。瘀热互结是桃核承气汤、抵当汤之蓄血；痰热互结为小陷胸汤之结胸；寒湿互结当温阳散寒化湿；湿热互结虽近之，但本方关键在水与热结且灼伤阴液，故以阿胶养阴，区别于单纯湿热"},{"q":"当归四逆汤中通草的作用是","o":["通经脉","通阳气","利水","清热","温阳"],"a":0,"e":"当归四逆汤中通草味淡性寒，功能通经脉、利关节，于温经散寒、养血通脉剂中防温药之燥，并助血脉流通，主治血虚寒厥之手足厥寒、脉细欲绝。通阳气非通草所长，本方通阳靠桂枝、细辛；利水为茯苓、泽泻之功，本方无此；清热、温阳皆非通草在本方之职，其要在于通利经脉以助当归、桂枝养血温通"},{"q":"大蓟、小蓟并用的方剂是","o":["导赤散","小蓟饮子","槐花散","八正散","十灰散"],"a":4,"e":"十灰散由大蓟、小蓟、荷叶、侧柏叶、茅根、茜草、栀子、大黄、牡丹皮、棕榈皮各烧灰存性组成，凉血止血，主治血热妄行之吐血、咯血，大蓟、小蓟相须为用，凉血止血力彰。小蓟饮子只有小蓟，功在凉血止血、利水通淋，主血淋尿血，无大蓟；导赤散清心利水，槐花散清肠止血，八正散清热利水通淋，均无大小蓟同用之配伍"},{"q":"左归丸的证治要点是","o":["头目眩晕，腰膝酸软，舌光少苔，脉细","骨蒸潮热，舌红少苔，尺脉数而有力","头目眩晕， 腰酸腿软，舌淡少苔，脉细数","头目眩晕，胁肋疼痛，吞酸吐苦，舌红少津","腰痛脚弱，小便不利或反多，舌淡而胖，脉虚弱"],"a":0,"e":"左归丸滋阴补肾、填精益髓，主治真阴不足证，以头目眩晕、腰膝酸软、舌光少苔、脉细为辨证要点，纯补无泻、阳中求阴。骨蒸潮热、舌红少苔、尺脉数而有力是阴虚火旺，属知柏地黄丸、大补阴丸；头目眩晕兼胁肋疼痛、吞酸吐苦为一贯煎证；腰痛脚弱、小便不利或反多、舌淡而胖、脉虚弱为肾气丸证"},{"q":"从组成药物看，小建中汤是由桂枝汤（ ）而成","o":["去芍药加饴糖","去芍药倍甘草","倍甘草加饴糖","倍甘草与芍药","倍芍药加饴糖"],"a":4,"e":"小建中汤即桂枝汤倍用芍药再加饴糖而成，饴糖温中补虚、缓急止痛为君，倍增芍药益阴和营、缓急止痛，桂枝温阳散寒，合为温中补虚、和里缓急之剂，主治中焦虚寒之腹痛。去芍药加饴糖、去芍药倍甘草皆非本方；倍甘草加饴糖、倍甘草与芍药亦不符，本方关键在倍芍药与加饴糖，去芍药则失缓急和营之旨"},{"q":"黄土汤方中的黄芩为","o":["君药","臣药","佐制药","反佐药","使药"],"a":3,"e":"黄土汤中黄芩苦寒，于大队温燥止血药中反佐一味，既清肝脾之热以防温燥太过、动血，又使温而不燥、刚柔相济，故为反佐药。君药为灶心土温中止血；臣药白术、附子温阳健脾；佐药生地、阿胶养血止血；使药甘草调和诸药。把黄芩认作君、臣或使，均未识其反佐制温燥之深意"},{"q":"朱砂安神丸的病位以（ ）为主","o":["肾","肺","肝","心","以上都不正确"],"a":3,"e":"朱砂安神丸镇心安神、清热养血，主治心火亢盛、阴血不足之心神烦乱、惊悸失眠、舌红尖疮、脉细数，病位以心为主，方中朱砂重镇安神，黄连清心泻火，生地、当归养血滋阴，甘草调和。肝为主者多见急躁易怒、胁痛，非本方所主；肺、肾亦非其病位；本方专为心火扰神而设，故病位归心"},{"q":"使用理气剂的注意事项，下列哪项除外都是正确的","o":["辨清病变部位","辨清病变属性","辨疾病的内伤外感","理气药多芳香辛燥，易伤津耗气，其治可酌情配伍补益药","年老体弱、阴血不足、孕妇又有气郁、气逆者，应酌情减量，必须兼顾正气。"],"a":2,"e":"使用理气剂须辨清病变部位与病变属性，并知理气药多芳香辛燥、易伤津耗气，必要时酌情配伍补益药；年老体弱、阴血不足及孕妇气郁气逆者应减量并兼顾正气。辨疾病的内伤外感是解表剂、治风剂等需首先考虑的，并非理气剂使用注意的特有内容，故列为除外项，其余各项均为理气剂应用中须遵循的原则"},{"q":"桑螵蛸散主要用治","o":["尿频遗尿","自汗盗汗","久泻久痢","崩漏带下","久咳肺虚"],"a":0,"e":"桑螵蛸散调补心肾、涩精止遗，由桑螵蛸、远志、菖蒲、龙骨、人参、茯神、当归、龟甲组成，主治心肾两虚之尿频、遗尿、滑精及心神恍惚、健忘，故善治尿频遗尿。自汗盗汗属卫表、阴虚，非本方所主；久泻久痢为脾肾虚寒、固涩失司，宜真人养脏汤、四神丸；崩漏带下多冲任不固；久咳肺虚宜补肺固表，均非本方之用"},{"q":"下列各项中，属于独活寄生汤证辨证要点的是","o":["头身重痛","腰膝冷痛","全身酸痛","头痛恶寒","脉沉实"],"a":1,"e":"独活寄生汤祛风湿、止痹痛、益肝肾、补气血，主治痹证日久、肝肾两虚、气血不足，以腰膝冷痛、肢节屈伸不利、麻木酸软、舌淡苔白、脉细弱为辨证要点。头身重痛多为湿邪困表；全身酸痛范围泛化，非本方定位；头痛恶寒属外感表证；脉沉实为实证、里实，与本方肝肾气血不足之虚象相反，故腰膝冷痛最合本方之机"},{"q":"清气化痰丸用法中以何为小丸","o":["水","酒","姜汁","藕汁","乳汁"],"a":2,"e":"清气化痰丸制法以姜汁为小丸，姜汁辛温，既助半夏、胆南星化痰散结，又制黄芩、瓜蒌之寒，兼和胃降逆，使化痰清热而不伤中。以水为丸无辛散化痰之力；酒多活血行药势，非本方所用；藕汁、乳汁偏养阴润燥，与清化热痰、降气止咳之治不符。本方姜汁糊丸，正是针对痰热咳嗽而设的炮制配伍匠心"},{"q":"桂枝茯苓丸的功用是","o":["温经通阳，健脾益气","健脾利水，解肌发表","活血祛瘀，健脾利水","活血化瘀，缓消癥块","消癥除痞，益气温阳"],"a":3,"e":"桂枝茯苓丸由桂枝、茯苓、牡丹皮、赤芍、桃仁组成，活血化瘀、缓消癥块，主治瘀阻胞宫之妇人宿有癥块、妊娠漏下不止、胎动不安，取渐消缓散而不峻攻之意。温经通阳、健脾益气非本方功用；健脾利水、解肌发表分别是五苓散、桂枝汤之能；活血祛瘀兼健脾利水偏混称，本方重在温通血脉、化瘀消癥，故以缓消癥块为要"},{"q":"痛泻要方与固冲汤共用的药物是","o":["陈皮、防风","白术、白芍","白术、山萸肉","黄芪、白术","茜草、甘草"],"a":1,"e":"痛泻要方含白术、白芍、陈皮、防风，补脾柔肝、祛湿止泻；固冲汤含白术、白芍、黄芪、龙骨、牡蛎、山萸肉、茜草、棕榈炭、海螵蛸、五倍子，益气健脾、固冲摄血，两方共用白术、白芍。陈皮、防风只用于痛泻要方，疏肝醒脾；山萸肉、茜草仅见于固冲汤，补肝肾、涩止血；黄芪、甘草亦非两方共有，故白术、白芍为其唯一重合之药"},{"q":"治疗实证水肿，首选方剂是","o":["五苓散","真武汤","大青龙汤","大陷胸汤","十枣汤"],"a":4,"e":"十枣汤以芫花、甘遂、大戟峻下逐水，大枣缓和药性、护中，攻逐水饮之力最强，主治水饮壅盛之实水、悬饮，为治实证水肿之首选。五苓散利水渗湿、温阳化气，主膀胱气化不利之水湿内停，力缓；真武汤温阳利水，主脾肾阳虚之水气内停，属虚；大青龙汤发汗解表、清热，主外寒内热；大陷胸汤泻热逐水，主结胸实证，均非实水通用之剂"},{"q":"六味地黄丸的功用是","o":["养心安神","滋阴补肾","健脾和胃","滋阴疏肝","滋阴降火"],"a":1,"e":"六味地黄丸由熟地黄、山茱萸、山药、泽泻、茯苓、牡丹皮组成，三补三泻、以补为主，滋阴补肾，主治肾阴亏损之头晕耳鸣、腰膝酸软、盗汗遗精、舌红少苔、脉细数。养心安神是天王补心丹、酸枣仁汤；健脾和胃为健脾丸、香砂六君；滋阴疏肝是一贯煎；滋阴降火是知柏地黄丸、大补阴丸，均非六味地黄丸滋补肾阴之基本功用"},{"q":"应用开窍剂，首先应辨清","o":["实证和虚证","表证和里证","闭证和脱证","阴证和阳证","寒证和热证"],"a":2,"e":"应用开窍剂首当辨清闭证与脱证，闭证属实、邪气内闭清窍，见神昏谵语、牙关紧闭、两手握固，可用开窍剂芳香开闭；脱证属虚、元气暴脱，见神昏、汗出肢冷、脉微欲绝，治宜回阳固脱，禁用开窍，否则耗气散阳。实证虚证、表里、阴阳、寒热虽均须辨别，但开窍剂使用首要关键在区分闭与脱以定能否开窍"},{"q":"金锁固精丸的组成中除莲须、莲子粉、煅龙骨、煅牡蛎外还有","o":["桑螵蛸、益智仁","菖蒲、远志","乌药、山药","沙苑子、芡实","山药、芡实"],"a":3,"e":"金锁固精丸由沙苑子、芡实、莲须、煅龙骨、煅牡蛎、莲子粉组成，沙苑子补肾固精，芡实益肾健脾、固精，共奏补肾涩精之功，主治肾虚不固之遗精滑泄。桑螵蛸、益智仁是缩泉丸主药，温肾缩尿；菖蒲、远志开窍宁心，见桑螵蛸散；乌药、山药为缩泉丸组成；山药虽与芡实并列，但不在本方，故唯有沙苑子、芡实为正确配伍"},{"q":"治疗伤寒邪在少阳、肝脾不和、寒热错杂的方剂属于","o":["解表剂","和解剂","清热剂","补益剂","理气剂"],"a":1,"e":"和解剂具有和解少阳、调和肝脾、调和寒热等作用，主治邪在少阳、肝脾不和、寒热错杂等证，伤寒邪在少阳、肝脾不和、寒热错杂者正属此类，如小柴胡汤、逍遥散、半夏泻心汤。解表剂主外感表证，邪在肌表；清热剂主里热证；补益剂补虚扶正；理气剂行气解郁，皆不涵盖少阳、肝脾、寒热错杂这一和解范畴"},{"q":"半夏白术天麻汤中治疗风痰眩晕头痛之要药是","o":["半夏、橘红","半夏、白术","白术、天麻","半夏、天麻","天麻、橘红"],"a":3,"e":"半夏白术天麻汤中半夏燥湿化痰、降逆止呕，天麻平肝息风、定眩，二药相伍为治风痰眩晕头痛之要药，针对风痰上扰之眩晕头痛、胸闷呕恶。橘红、白术健脾燥湿、理气化痰，为辅助之品，非治眩晕之主药；白术配天麻虽健脾息风，但缺半夏化痰，不成药对；天麻、橘红亦失化痰降逆之半夏，故以半夏、天麻为要"},{"q":"应用天王补心丹的辨证要点是","o":["失眠，惊悸，舌红，脉细数","失眠心悸，手足心热，舌红少苔，脉细数","虚烦失眠，咽干口燥，舌红，脉弦细","精神恍惚，悲伤欲哭，舌红苔少，脉细","心悸失眠，体倦食少，舌淡，脉细弱"],"a":1,"e":"天王补心丹滋阴养血、补心安神，主治阴虚血少、神志不安，以心悸失眠、手足心热、舌红少苔、脉细数为辨证要点，兼口舌生疮、大便干结。仅言失眠、惊悸、舌红、脉细数未突出阴虚内热之手足心热；虚烦失眠、咽干口燥、脉弦细偏酸枣仁汤之肝血不足；精神恍惚、悲伤欲哭为甘麦大枣汤之脏躁；体倦食少、舌淡脉细弱为归脾汤"},{"q":"回阳救急汤中不需煎煮的药物是","o":["五味子","麝香","茯苓","陈皮","肉桂"],"a":1,"e":"回阳救急汤于回阳救逆、益气生脉剂中加麝香，麝香芳香走窜、开窍醒神，辛散力强，久煎则挥发失效，故不入煎，宜冲服或化服，借其通关窍、助阳气布散以救危急。五味子、茯苓、陈皮、肉桂均为方中常规入煎之品：五味子敛阴固脱，茯苓健脾渗湿，陈皮理气，肉桂温阳，皆可随汤煎煮取效，唯麝香需冲服"},{"q":"大青龙汤的组成是","o":["麻黄汤倍用麻黄、甘草，减少杏仁用量，再加石膏、生姜、大枣","麻黄汤倍用麻黄、甘草，增加杏仁用量，再加石膏、生姜、大枣","麻黄汤倍用桂枝、甘草，减少杏仁用量，再加石膏、生姜、大枣","麻黄汤倍用麻黄、甘草，减少杏仁用量，再加石膏、干姜、大枣","麻黄汤倍用麻黄、甘草，增加杏仁用量，再加石膏、干姜、大枣"],"a":0,"e":"大青龙汤即麻黄汤倍用麻黄、甘草，减少杏仁用量，再加石膏、生姜、大枣而成，发汗解表、清热除烦，主治外感风寒、内有蕴热之恶寒发热、无汗烦躁。若增加杏仁用量则与本方宣散为主、减少杏仁以免降泄之旨相悖；倍桂枝、甘草者为桂枝汤加味思路，非本方；加干姜者偏温中，本方用生姜和中，故唯倍麻黄甘草、减杏仁、加石膏生姜大枣为是"},{"q":"当归四逆汤组成中没有","o":["细辛","通草","大枣","川芎","甘草"],"a":3,"e":"当归四逆汤由当归、桂枝、芍药、细辛、炙甘草、通草、大枣组成，养血通脉、温经散寒，主治血虚寒厥。细辛温经散寒、通窍，通草通经脉，大枣、甘草益气和中、调和诸药，皆为方中之品；川芎活血行气虽常用于四物汤、血府逐瘀汤等血虚血瘀诸方，但当归四逆汤重在养血温通、并未用川芎，故不含川芎"},{"q":"以活血祛瘀，行气止痛为主要功效的方剂是","o":["温经汤","失笑散","金铃子散","桂枝茯苓丸","血府逐瘀汤"],"a":4,"e":"血府逐瘀汤以桃红四物汤合四逆散加桔梗、牛膝而成，活血祛瘀、行气止痛，主治胸中血瘀之胸痛、头痛、心悸失眠、舌暗红或有瘀斑。温经汤温经散寒、养血祛瘀，主冲任虚寒瘀阻；失笑散活血祛瘀、散结止痛，力专瘀血疼痛；金铃子散行气活血、疏肝泄热，主肝郁化热之痛；桂枝茯苓丸活血化瘀、缓消癥块，皆非以行气止痛为主要功效"},{"q":"下列药物，哪一组为健脾丸的组成","o":["白术、甘草、黄芩、谷芽、砂仁、神曲、山楂、山药","白术、茯苓、人参、木香、黄连、神曲、砂仁、山楂","黄连、木香、肉豆蔻、玄参、苍术、神曲、山药、麦芽","人参、山药、白术、麦芽、陈皮、砂仁、香附、神曲","茯苓、人参、甘草、黄芪、黄连、神曲、肉豆蔻、木香"],"a":1,"e":"健脾丸由白术、茯苓、人参、木香、黄连、神曲、砂仁、山楂、山药、麦芽、陈皮、肉豆蔻、甘草组成，健脾和胃、消食止泻，主治脾虚食积。所列白术、茯苓、人参、木香、黄连、神曲、砂仁、山楂皆在方中，为本方核心药物。含黄芩、谷芽且无茯苓、人参者不符；含玄参、苍术、香附、黄芪者皆非健脾丸配伍，故唯有此组合正确"},{"q":"龟鹿二仙胶的组成中有","o":["鹿角","黄芪","桃仁","红花","生地黄"],"a":0,"e":"龟鹿二仙胶由鹿角、龟板、人参、枸杞子组成，鹿角温阳益精、龟板滋阴填髓，一阳一阴，人参补气，枸杞子滋阴，共奏滋阴填精、益气壮阳之功，主治真元虚损、精血不足。黄芪、桃仁、红花、生地黄皆非本方所有：黄芪补气固表，桃仁、红花活血祛瘀，生地黄清热凉血养阴，与本方填补精血、阴阳并补之立方旨趣不合"},{"q":"体现“疏柔合法，肝脾同调，气血兼顾”配伍特点的方剂是","o":["小柴胡汤","柴胡疏肝散","越鞠丸","逍遥散","四逆散"],"a":3,"e":"逍遥散疏肝解郁、养血健脾，方中柴胡疏肝解郁，当归、白芍养血柔肝，白术、茯苓健脾，薄荷、生姜助疏散，甘草调和，体现疏柔合法、肝脾同调、气血兼顾之配伍特点，主治肝郁血虚脾弱证。小柴胡汤和解少阳；柴胡疏肝散疏肝行气、活血止痛，无养血健脾；越鞠丸行气解郁，治六郁；四逆散透邪解郁、疏肝理脾，重在畅达气机"},{"q":"小柴胡汤与桂枝汤共用的药物是","o":["柴胡、桂枝","人参、甘草","生姜、大枣","半夏、白芍","黄芩、大枣"],"a":2,"e":"小柴胡汤含柴胡、黄芩、半夏、人参、炙甘草、生姜、大枣，桂枝汤含桂枝、芍药、炙甘草、生姜、大枣，两方共有炙甘草、生姜、大枣，选项中为生姜、大枣，同属调和营卫、和中调药之品。柴胡、桂枝、黄芩、半夏、人参、白芍皆非两方共有：柴胡、黄芩、半夏、人参仅小柴胡汤有，桂枝、白芍仅桂枝汤有"},{"q":"清燥救肺汤中用量最大的药物是","o":["石膏","麦冬","人参","阿胶","桑叶"],"a":4,"e":"清燥救肺汤中桑叶经霜者轻宣肺燥、清泻肺热，为君药且用量最大，配石膏、麦冬清肺润燥，人参、甘草益气生津，阿胶、胡麻仁养阴润肺，杏仁、枇杷叶降气止咳，主治温燥伤肺之干咳无痰、气逆而喘。石膏、麦冬虽为臣药清润，用量次之；人参益气、阿胶滋阴用量更轻，皆辅助桑叶清宣润燥"},{"q":"治疗暑湿证的基础方剂是","o":["香薷散","六一散","生脉散","竹叶石膏汤","白虎汤"],"a":1,"e":"六一散由滑石六两、甘草一两组成，滑石清暑利湿、解肌，甘草清热和中，共奏清暑利湿之功，药简力专，为治疗暑湿证之基础方，暑湿所致身热烦渴、小便不利皆可用之，并可随证加味。香薷散祛暑解表、化湿和中，主阴暑外感；生脉散益气养阴、敛汗，主暑热伤气阴；竹叶石膏汤清热生津、益气和胃；白虎汤清气分实热，均非单纯暑湿基础方"},{"q":"凉膈散的功用是","o":["辛凉透表，清热解毒","泻火通便，清上泄下","辛凉疏表，清肺平喘","清热解毒，疏风散邪","清热解毒，凉血泻火"],"a":1,"e":"凉膈散以大黄、芒硝、栀子、黄芩、连翘、薄荷、竹叶、甘草加蜂蜜组成，清上焦之热、泻下焦之结，功用泻火通便、清上泄下，主治上中二焦邪郁生热之胸膈烦热、口舌生疮、便秘溲赤。辛凉透表、清热解毒是银翘散；辛凉疏表、清肺平喘是麻杏甘石汤；清热解毒、疏风散邪是普济消毒饮；清热解毒、凉血泻火是清瘟败毒饮"},{"q":"具有攻下热结，益气养血功用的方剂是","o":["脾约丸","五仁丸","十枣汤","济川煎","黄龙汤"],"a":4,"e":"黄龙汤即大承气汤加人参、当归、甘草、桔梗（加生姜、大枣），在大黄、芒硝、枳实、厚朴攻下热结的同时，以人参、当归益气养血，主治阳明腑实而气血不足之便秘腹痛、神倦少气、脉虚。脾约丸润肠通便，主肠燥脾约；五仁丸润肠，主津枯便秘；十枣汤攻逐水饮；济川煎温肾益精、润肠通便，均无攻下热结兼益气养血之双重作用"},{"q":"下列不属于苏子降气汤主治证临床表现的症状是","o":["痰涎壅盛","喘咳短气","腰痛脚软","肢体浮肿","头晕目眩"],"a":4,"e":"苏子降气汤降气平喘、祛痰止咳，主治上实下虚喘咳，上实见痰涎壅盛、喘咳短气、胸膈满闷，下虚见腰痛脚软、肢体浮肿、大便或秘或溏，皆其主治范围。头晕目眩非本方证典型表现，多属肝阳上亢、痰浊中阻或气血不足，如天麻钩藤饮、半夏白术天麻汤所主，故不属于本方主治证临床表现"},{"q":"肾气丸比六味地黄丸多的药是","o":["薯蓣、山茱萸","山药、泽泻","茯苓、牡丹皮","桂枝、附子","肉桂、附子"],"a":3,"e":"肾气丸于六味地黄丸（熟地、山萸肉、山药、泽泻、茯苓、牡丹皮）基础上加桂枝、附子而成，温补肾阳、化气行水，主治肾阳不足之腰痛脚弱、下半身冷感、小便不利或反多、舌淡而胖。薯蓣即山药、山茱萸、泽泻、茯苓、牡丹皮本已见于六味地黄丸，非肾气丸所独有；肉桂、附子虽亦温阳，但金匮肾气丸原方用桂枝而非肉桂"},{"q":"参苓白术散的组成中有","o":["人参、麦芽","白术、神曲","茯苓、半夏","茯苓、山药","人参、黄芪"],"a":3,"e":"参苓白术散由人参、白术、茯苓、山药、莲子肉、白扁豆、薏苡仁、砂仁、桔梗、甘草组成，益气健脾、渗湿止泻，主治脾虚湿盛之泄泻，茯苓、山药皆在方中。麦芽、神曲为消食药，非本方所用；半夏燥湿化痰，见二陈汤；黄芪补气升提，见补中益气汤，皆非参苓白术散组成，故本方所含为茯苓、山药，重在健脾渗湿"},{"q":"旋覆代赭汤主治病证是","o":["中虚痰阻气逆证","脾虚生痰证","脾虚食停证","胃虚有热呃逆证","胃气虚寒呃逆证"],"a":0,"e":"旋覆代赭汤由旋覆花、代赭石、半夏、人参、生姜、甘草、大枣组成，降逆化痰、益气和胃，主治胃虚痰阻气逆之心下痞硬、噫气不除、反胃呕吐，病机为中虚痰阻气逆。脾虚生痰证重在健脾化痰，非本方所主；脾虚食停宜健脾消食；胃虚有热呃逆宜橘皮竹茹汤；胃气虚寒呃逆宜丁香柿蒂汤，均非本方降逆化痰、益气和胃之主治"},{"q":"生脉散的组成为","o":["人参、白术、甘草","人参、麦门冬、五味子","五味子、麦门冬、甘草","知母、人参、杏仁","知母、人参、五味子"],"a":1,"e":"生脉散由人参、麦门冬、五味子三味组成，人参益气生津，麦冬养阴清热、润肺生津，五味子敛阴止汗、宁心，共奏益气养阴、敛汗生脉之功，主治气阴两虚之体倦气短、咽干口渴、汗多脉虚。白术、甘草健脾，为四君子汤之品；知母清热滋阴，杏仁降肺气，均非本方所有，故生脉散之组成为人参、麦门冬、五味子"},{"q":"大青龙汤主治证候的病机是","o":["外感风寒，营卫不和","外感风寒湿邪，内有蕴热","外感风寒，内有蕴热","外感风寒，肺气失宣","外感风寒，水饮内停"],"a":2,"e":"大青龙汤发汗解表、清热除烦，主治外感风寒、内有蕴热之恶寒发热、无汗、烦躁、口渴，故其病机为外感风寒、内有蕴热。外感风寒、营卫不和是桂枝汤证；外感风寒湿邪、内有蕴热是九味羌活汤证；外感风寒、肺气失宣见麻黄汤、三拗汤；外感风寒、水饮内停为小青龙汤证。本方独特处在表寒重而里热郁，故倍麻黄发汗、加石膏清热"},{"q":"半夏白术天麻汤与定痫丸主治证的病机是","o":["脾虚生痰","肝风夹痰","上扰清窍","蔽阻心窍","痰阻经络"],"a":1,"e":"半夏白术天麻汤燥湿化痰、平肝息风，主治风痰上扰之眩晕头痛；定痫丸涤痰熄风、开窍安神，主治风痰蕴结之癫痫，二者病机均离不开肝风夹痰、风痰上扰清窍。脾虚生痰仅为半夏白术天麻汤致病之一环，定痫丸不专主脾虚；上扰清窍是风痰作用之部位趋势，非病机本体；蔽阻心窍偏痰迷心窍；痰阻经络见中风麻木，故以肝风夹痰为是"},{"q":"具有补血和血功用的方剂是","o":["当归补血汤","归脾汤","八珍汤","四物汤","胶艾汤"],"a":3,"e":"四物汤由熟地黄、当归、白芍、川芎组成，熟地、白芍补血养阴，当归补血和血，川芎活血行气，共奏补血和血之功，为补血调经之基础方，主治营血虚滞之月经不调、痛经、面色无华。当归补血汤重在补气生血，主血虚发热；归脾汤益气补血、健脾养心，主心脾两虚；八珍汤气血双补；胶艾汤养血止血、调经安胎，皆非单纯补血和血之剂"},{"q":"以下关于川芎茶调散证的辨证要点描述错误的是","o":["头痛","咳嗽","鼻塞","脉浮","苔薄"],"a":1,"e":"川芎茶调散疏风止痛，主治外感风邪头痛，辨证要点为头痛、鼻塞、流涕、苔薄白、脉浮，兼有恶风发热等表证。咳嗽虽可因风邪犯肺而见，但非本方辨证要点，本方专为风邪上犯头目之头痛而设，故列为错误描述。头痛、鼻塞、脉浮、苔薄皆直接反映风邪在表、上扰清窍，是辨识本方证的关键，咳嗽不具定位价值"},{"q":"属于白虎汤组成药物的是","o":["黄芩","秫米","糯米","粳米","贝母"],"a":3,"e":"白虎汤由石膏、知母、炙甘草、粳米组成，清热生津，主治气分实热之大热、大渴、大汗、脉洪大，粳米益胃生津，防石膏、知母大寒伤中。黄芩清热燥湿，非本方所有；秫米即高粱米，多用于半夏秫米汤和胃安神；糯米、贝母亦不在方，糯米偏温补，贝母润肺化痰，与本方清气分实热之旨不合"},{"q":"六一散中甘草与滑石的用量比例是","o":["6∶1","5∶1","3∶1","1∶6","1∶1"],"a":3,"e":"六一散原名益元散，由滑石六两、甘草一两组成，滑石与甘草用量比例为六比一，故名六一，滑石清热利湿、解肌，甘草和中清热，共奏清暑利湿之功。六比一颠倒了主辅，滑石为君用量独重；五比一、三比一、一比一皆不符原方配比。本方药仅两味，比例固定，甘草与滑石之比当为一比六，即滑石六倍于甘草"},{"q":"枳实导滞丸之君药是","o":["枳实","大黄","厚朴","枳实、大黄","神曲、大黄"],"a":1,"e":"枳实导滞丸以大黄为君，泻热通便、荡涤胃肠湿热积滞，主治湿热食积之脘腹胀痛、下痢泄泻、小便短赤，佐以枳实消痞、黄连黄芩清热燥湿、神曲消食、茯苓泽泻利湿、白术健脾。枳实虽为方名之药，但消痞除满力逊于大黄攻逐湿热积滞，故为臣；厚朴、神曲非君药；枳实与大黄合称、神曲与大黄并列均未突出大黄攻下之主导地位"},{"q":"清燥救肺汤的组成药物是","o":["桑叶","苏叶","瓜蒌","沙参","贝母"],"a":0,"e":"清燥救肺汤由桑叶、石膏、甘草、人参、胡麻仁、阿胶、麦冬、杏仁、枇杷叶组成，清燥润肺、养阴益气，主治温燥伤肺之干咳无痰、气逆而喘、咽干口渴。苏叶辛温发散，用于凉燥之杏苏散，非本方所宜；瓜蒌清热化痰、宽胸，贝母润肺止咳，均不在本方；沙参养阴清肺，虽治燥咳但本方未用，故其组成药物为桑叶，且为君药"},{"q":"主治血虚外感风寒证的方剂是","o":["败毒散","参苏饮","葱白七味饮","麻黄附子细辛汤","加减葳蕤汤"],"a":2,"e":"葱白七味饮由葱白、豆豉、葛根、生姜、麦冬、干地黄、劳水组成，养血解表，主治血虚外感风寒之头痛身热、恶寒无汗、舌淡脉细，于解表中兼养血滋阴，使汗出而不伤血。败毒散益气解表，主气虚外感；参苏饮益气解表、理气化痰，主气虚外感兼痰；麻黄附子细辛汤助阳解表，主阳虚外感；加减葳蕤汤滋阴解表，主阴虚外感"},{"q":"贝母瓜蒌散组成中无","o":["贝母","瓜蒌","茯苓","橘红","甘草"],"a":4,"e":"贝母瓜蒌散由贝母、瓜蒌、天花粉、茯苓、橘红、桔梗组成，润肺清热、理气化痰，主治燥痰咳嗽之咳嗽呛急、咯痰不爽、涩而难出、咽喉干燥，无甘草。贝母、瓜蒌为君，清热润肺、化痰止咳；茯苓健脾渗湿以杜生痰之源；橘红理气化痰；天花粉、桔梗清热生津、宣肺利咽，皆在方中，唯甘草不在"},{"q":"黄土汤治证的病机是","o":["脾阳不足，统摄失常","气虚不固，统摄失常","气血两亏，统摄失常","血热妄行，统摄失常","心脾两虚，统摄失常"],"a":0,"e":"黄土汤温阳健脾、养血止血，主治脾阳不足、脾不统血之便血、吐血、衄血、崩漏，血色暗淡、四肢不温、面色萎黄，其病机为脾阳不足、统摄失常。气虚不固、统摄失常偏气虚证，无温阳之针对；气血两亏、统摄失常未点明阳虚；血热妄行、统摄失常属十灰散、犀角地黄汤之血热出血；心脾两虚、统摄失常为归脾汤所主"},{"q":"炙甘草汤之君药是","o":["炙甘草","生地黄","麦门冬","人参","桂枝"],"a":1,"e":"炙甘草汤（复脉汤）以生地黄为君，滋阴养血、益心复脉，主治阴阳气血俱虚之心悸怔忡、脉结代、心动悸，方中炙甘草益气和中、通脉，人参、桂枝、生姜温阳通脉，麦冬、阿胶、麻仁、大枣养血滋阴。炙甘草虽为方名且益气复脉，然滋阴养血之力不及生地；麦门冬、人参养阴益气为臣佐；桂枝温通心阳，非君药"},{"q":"桂枝汤的功用是","o":["发汗解表，缓急止痛","发汗解表，宣肺平喘","解肌发表，调和营卫","温经散寒，养血通脉","发汗解表，平冲降逆"],"a":2,"e":"桂枝汤由桂枝、芍药、炙甘草、生姜、大枣组成，解肌发表、调和营卫，主治外感风寒表虚证之头痛发热、汗出恶风、脉浮缓。发汗解表、缓急止痛非本方；发汗解表、宣肺平喘为麻黄汤、三拗汤；温经散寒、养血通脉是当归四逆汤；发汗解表、平冲降逆偏桂枝加桂汤之类。桂枝汤重在解肌和营卫，而非峻汗，故以调和营卫为功用核心"},{"q":"何方最能体现王冰所谓“益火之源，以消阴翳”之意","o":["白虎汤","地黄饮子","右归丸","左归丸","四逆汤"],"a":2,"e":"右归丸温补肾阳、填精益髓，大队温阳药配熟地、山萸肉、山药、枸杞等滋阴填精，于阴中求阳，体现王冰益火之源、以消阴翳之法，主治肾阳不足、命门火衰。白虎汤清气分实热；地黄饮子滋肾阴、补肾阳、开窍化痰，主喑痱；左归丸纯补真阴，滋阴补肾；四逆汤回阳救逆，主阳虚欲脱，皆非益火消阴之剂"},{"q":"龙骨、牡蛎并用的方是","o":["桑螵蛸散","金锁固精丸","真人养脏汤","缩泉丸","牡蛎散"],"a":1,"e":"金锁固精丸由沙苑子、芡实、莲须、煅龙骨、煅牡蛎、莲子粉组成，龙骨、牡蛎煅用涩精止遗，共奏补肾涩精之功，主治肾虚精关不固之遗精滑泄。桑螵蛸散用龙骨但配龟甲、桑螵蛸等，无牡蛎同用；真人养脏汤含龙骨、牡蛎但重在涩肠止泻，非固精；缩泉丸为益智仁、乌药、山药；牡蛎散只有牡蛎，无龙骨"},{"q":"具有逐瘀泻热功用的方剂是","o":["桃核承气汤","血府逐瘀汤","复元活血汤","补阳还五汤","生化汤"],"a":0,"e":"桃核承气汤由桃仁、大黄、桂枝、甘草、芒硝组成，逐瘀泻热，主治下焦蓄血证之少腹急结、小便自利、谵语烦渴、至夜发热，瘀热互结故逐瘀兼泻热。血府逐瘀汤活血化瘀、行气止痛，无泻热之功；复元活血汤活血祛瘀、疏肝通络，主跌打损伤瘀血；补阳还五汤补气活血通络，主气虚血瘀中风；生化汤养血祛瘀，主产后瘀阻"},{"q":"泻痢日久，每伤阴血，真人养脏汤中养血和血的药物是","o":["当归、白芍","生地、当归","生地、白芍","当归、阿胶","生地、阿胶"],"a":0,"e":"真人养脏汤于温补脾肾、涩肠固脱方中配当归、白芍养血和血，既补泻痢日久所伤之阴血，又缓急止痛、防温燥涩滞伤血，主治久泻久痢、脾肾虚寒、滑脱不禁。生地、阿胶虽滋阴养血，但滋腻碍胃，非本方所用，且本方重在温涩，不用寒凉滋腻之品；本方以当归、白芍和血养血，配合罂粟壳、肉豆蔻、诃子涩肠"},{"q":"下列选项中，不属于八珍汤药物组成的是","o":["人参、白术","当归、川芎","白芍、甘草","茯苓、熟地","黄芪、肉桂"],"a":4,"e":"八珍汤即四君子汤（人参、白术、茯苓、甘草）合四物汤（当归、川芎、白芍、熟地黄）而成，气血双补，主治气血两虚。人参、白术、当归、川芎、白芍、甘草、茯苓、熟地皆在方中；黄芪、肉桂不在，二者加入十全大补汤（八珍汤加黄芪、肉桂）方有，故黄芪、肉桂不属于八珍汤组成，其余各项均为八珍汤固有药物"},{"q":"炙甘草汤的功用是","o":["益气补血，健脾养心","益气补血","滋阴养血，益气温阳，复脉定悸","营血虚滞","益气健脾，养血安胎"],"a":2,"e":"炙甘草汤滋阴养血、益气温阳、复脉定悸，主治气虚血弱之心动悸、脉结代、形体消瘦、咽干舌燥，方以生地滋阴养血，炙甘草、人参益气，桂枝、生姜温阳通脉，麦冬、阿胶、麻仁养阴润燥。益气补血、健脾养心是归脾汤；益气补血表述笼统，未及温阳复脉；营血虚滞是四物汤之机；益气健脾、养血安胎为泰山磐石散"},{"q":"下列各项中，均属于独活寄生汤药物组成的是","o":["独活、羌活、细辛","杜仲、牛膝、桑寄生","熟地黄、当归、芍药","人参、白术、甘草","独活、桂枝、防风"],"a":1,"e":"独活寄生汤由独活、桑寄生、杜仲、牛膝、细辛、秦艽、茯苓、肉桂心、防风、川芎、人参、甘草、当归、芍药、干地黄组成，杜仲、牛膝、桑寄生皆在方中，补肝肾、强筋骨、引药下行，治痹证日久肝肾两虚。羌活不在本方，本方用独活；桂枝非本方，本方用肉桂心；熟地黄、白术亦非本方原药，故杜仲、牛膝、桑寄生为完全属于本方的一组"},{"q":"甘露消毒丹的功用是","o":["利湿化浊，清热凉血","利湿化浊，清热泻火","利湿化浊，清热解毒","利湿化浊，清热利咽","利湿化浊，清热通络"],"a":2,"e":"甘露消毒丹由滑石、茵陈、黄芩、石菖蒲、川贝母、木通、藿香、射干、连翘、薄荷、白蔻仁组成，利湿化浊、清热解毒，主治湿温时疫、湿热并重之发热倦怠、胸闷腹胀、颐肿咽痛、泄泻淋浊。清热凉血非本方，无犀角、生地类；清热泻火偏白虎、黄连类；清热利咽、通络仅为局部作用，不能概括全方，故功用为利湿化浊与清热解毒并举"},{"q":"独活寄生汤证主治","o":["风寒湿痹","风湿热痹","顽痹","风湿犯表之痹证","外感风寒湿、里有蕴热证"],"a":2,"e":"独活寄生汤祛风湿、止痹痛、益肝肾、补气血，主治痹证日久、肝肾两虚、气血不足之久痹、顽痹，症见腰膝疼痛、肢节屈伸不利、麻木酸软、畏寒喜温。风寒湿痹为痹证初起、邪实为主，非本方补虚之所宜；风湿热痹见关节红肿热痛，宜白虎加桂枝汤；风湿犯表之痹证病位在表；外感风寒湿、里有蕴热是九味羌活汤证"},{"q":"组成药物中无山栀子的方剂是","o":["十灰散","咳血方","小蓟饮子","茵陈蒿汤","槐花散"],"a":4,"e":"十灰散、咳血方、小蓟饮子、茵陈蒿汤均用栀子清热泻火、凉血或利湿：十灰散、小蓟饮子用栀子凉血止血，咳血方用栀子清肝泻火，茵陈蒿汤用栀子清热利湿退黄。槐花散由槐花、侧柏叶、荆芥穗、枳壳组成，清肠止血、疏风行气，无山栀子，故为组成中无山栀子之方"},{"q":"消风散的功用是","o":["祛风散邪，清热利湿","养血祛风，散热除湿","疏风祛邪，清热除湿","疏风养血，清热除湿","养血疏风，清热利湿"],"a":3,"e":"消风散由荆芥、防风、牛蒡子、蝉蜕、苍术、苦参、石膏、知母、当归、生地、胡麻仁、木通、甘草组成，疏风养血、清热除湿，主治风湿浸淫血脉之瘾疹、湿疹，皮肤瘙痒、疹出色红。祛风散邪、清热利湿未及养血；养血祛风、散热除湿表述次序与配伍不符；疏风祛邪、清热除湿缺养血一味，本方配当归、生地、胡麻仁养血活血、滋阴润燥"},{"q":"大黄附子汤的功用是","o":["温里散寒，通便止痛","攻下冷积，温补脾阳","温阳补血，散寒通滞","温经通脉，养血止血","润肠通便，行气止痛"],"a":0,"e":"大黄附子汤由大黄、附子、细辛组成，温里散寒、通便止痛，主治寒积里实之腹痛便秘、胁下偏痛、发热、手足厥冷、脉紧弦，以温药配大黄攻下寒积。攻下冷积、温补脾阳是温脾汤，含人参、甘草之补；温阳补血、散寒通滞是阳和汤；温经通脉、养血止血非本方；润肠通便、行气止痛属麻子仁丸类"},{"q":"槐花散的药物组成是","o":["槐花、地榆、荆芥穗、枳实","槐花、侧柏叶、荆芥穗、枳壳","槐花、侧柏叶、防风、枳壳","槐花、荷叶、荆芥穗、枳壳","槐花、地榆、荆芥穗、枳壳"],"a":1,"e":"槐花散由槐花、侧柏叶、荆芥穗、枳壳四味组成，槐花、侧柏叶凉血止血，荆芥穗疏风止血，枳壳宽胸行气，共奏清肠止血、疏风行气之功，主治肠风脏毒下血。地榆虽常治便血、痔疮出血，如槐角丸用地榆，但本方原方无地榆；防风、荷叶虽可疏风，本方用荆芥穗；本方用枳壳而非枳实，故组成唯有槐花、侧柏叶、荆芥穗、枳壳"},{"q":"黄芪桂枝五物汤中具有补在表之卫气的药物是","o":["桂枝","黄芪","大枣","芍药","生姜"],"a":1,"e":"黄芪桂枝五物汤中黄芪益气固表、补在表之卫气，与桂枝、芍药、生姜、大枣相伍，益气温经、和血通痹，主治血痹之肌肤麻木不仁、脉微涩而紧。桂枝温经通阳、散风寒，非补卫气之品；生姜散寒和胃；大枣、芍药养血和营，皆无补卫气之功。本方即桂枝汤去甘草、倍生姜、加黄芪，重用黄芪补卫气而固表，使气旺血行"},{"q":"四磨饮子的组成中不含有","o":["人参","槟榔","沉香","乌药","当归"],"a":4,"e":"四磨饮子由人参、槟榔、沉香、乌药四味浓磨煎服，行气降逆、宽胸散结，主治肝气郁结之胸膈胀闷、上气喘急、心下痞满。人参、槟榔、沉香、乌药皆在方中：乌药、沉香降气，槟榔破气消积，人参益气扶正以防行气伤正。当归养血活血，为四物汤、血府逐瘀汤常用，四磨饮子专主行气降逆，不用血分药，故不含当归"},{"q":"不属于清燥救肺汤主治证候的是","o":["头痛身热，胸膈满闷","干咳无痰，气逆而喘","咽喉干燥，口渴鼻燥","烦渴饮引，小便频数","舌红少苔，脉虚大而数"],"a":3,"e":"清燥救肺汤主治温燥伤肺、气阴两伤之头痛身热、干咳无痰或痰少而黏、气逆而喘、咽喉干燥、口渴鼻燥、舌红少苔、脉虚大而数。烦渴饮引、小便频数属消渴阴虚燥热、肾失固摄之表现，如玉液汤、六味地黄丸所主，非清燥救肺汤证。其余头痛身热、干咳气逆、咽干鼻燥及舌红脉虚数，均契合温燥伤肺、气阴两亏之病机"},{"q":"生脉散中用人参的作用是","o":["益气生津，补养肺气","补益正气，扶正祛邪","大补元气，滋补后天","补中益气，升阳举陷","补气生血，强壮脾胃"],"a":0,"e":"生脉散中人参甘温，大补元气、益气生津、补养肺气，为君药，配麦冬养阴清热、五味子敛阴止汗，共奏益气养阴、敛汗生脉之功，主治气阴两虚之体倦乏力、气短汗多、脉虚。补益正气、扶正祛邪为参苏饮、败毒散之意；大补元气、滋补后天偏人参单用或四君子汤；补中益气、升阳举陷是补中益气汤；补气生血为当归补血汤"},{"q":"症见肢节沉重肿痛，苔白腻微黄，脉数者，治宜","o":["利湿清热，理气和中","利湿清热，舒筋壮骨","利湿清热，宣畅气机","利湿清热，疏风止痛","利湿清热，通络止痛"],"a":3,"e":"肢节沉重肿痛、苔白腻微黄、脉数，为风湿热痹湿邪偏盛兼化热之象，治宜利湿清热、疏风止痛，故疏风止痛与利湿清热相合为治。利湿清热、理气和中偏中焦湿滞；舒筋壮骨非痹证急性期所主；宣畅气机是三仁汤治湿温之法；通络止痛偏瘀血阻络之痛，皆与风湿热痹、湿重肿痛之机不合"},{"q":"可用于脾阳不足之肌衄证的方剂是","o":["理中汤","四物汤","四神丸","四君子汤","七厘散"],"a":0,"e":"肌衄为血液溢于肌肤之外，脾阳不足、统血无权者治宜温中健脾、益气摄血，理中汤以人参、干姜、白术、甘草温中祛寒、健脾益气，可使脾阳复、统摄有权而血归经，故可用治脾阳不足之肌衄。四物汤补血和血，无温阳摄血；四神丸温肾暖脾、涩肠止泻，主五更泄；四君子汤益气健脾，力平和无温中祛寒之能；七厘散活血散瘀，主跌打损伤"},{"q":"咳血方的病机是","o":["肺经实火，损伤肺络","阴虚火旺，损伤肺络","肺中伏火，损伤肺络","血热妄行，损伤肺络","肝火犯肺，损伤肺络"],"a":4,"e":"咳血方清肝宁肺、凉血止血，主治肝火犯肺之咳嗽咯血、心烦易怒、胸胁作痛、口苦咽干、舌红苔黄，其病机为肝火犯肺、损伤肺络，木火刑金、迫血妄行。肺经实火、损伤肺络是泻白散证；阴虚火旺、损伤肺络见百合固金汤、知柏地黄丸；肺中伏火、损伤肺络非本方；血热妄行、损伤肺络属十灰散、犀角地黄汤"},{"q":"以自利清水，脘腹胀痛，身热口渴，神倦少气，舌苔焦黄，脉虚为辨证要点的方剂是","o":["黄龙汤","调胃承气汤","济川煎","脾约丸","大承气汤"],"a":0,"e":"黄龙汤主治阳明腑实、气血不足证，见自利清水、脘腹胀痛、身热口渴、神倦少气、舌苔焦黄、脉虚，以大承气汤攻下热结，兼人参、当归益气养血，攻补兼施。调胃承气汤和缓泻下，无补益之力；济川煎温肾润肠，主肾虚便秘；脾约丸润肠通便，主肠燥脾约；大承气汤峻下热结，无益气养血，均不能兼顾气血不足"},{"q":"组成中含有地龙的方剂是","o":["血府逐瘀汤","补阳还五汤","复元活血汤","温经汤","生化汤"],"a":1,"e":"补阳还五汤由黄芪、当归尾、赤芍、地龙、川芎、桃仁、红花组成，补气活血通络，主治中风后遗症之气虚血瘀、半身不遂、口眼歪斜，地龙通经活络，为方中通痹要药。血府逐瘀汤活血行气，无地龙；复元活血汤活血疏肝，无地龙；温经汤温经养血祛瘀，无地龙；生化汤养血祛瘀，主产后瘀阻，无地龙"},{"q":"咳血方的组成药物中无","o":["龙胆草","青黛","海粉","诃子","山栀子"],"a":0,"e":"咳血方由青黛、瓜蒌仁、海粉、山栀子、诃子组成，清肝宁肺、凉血止血，青黛、栀子清肝泻火，海粉、瓜蒌化痰软坚，诃子敛肺止咳。龙胆草虽为清泻肝火要药，如龙胆泻肝汤、当归龙荟丸用之，但咳血方清肝火用的是青黛、栀子，并未用龙胆草，故组成中无龙胆草，其余青黛、海粉、诃子、山栀子皆在方中"},{"q":"七宝美髯丹的组成中包括","o":["熟地黄","鹿角胶","龟板胶","人参","枸杞子"],"a":4,"e":"七宝美髯丹由何首乌、茯苓、牛膝、当归、枸杞子、菟丝子、补骨脂组成，滋补肝肾、益精血、乌须发，主治肝肾不足之须发早白、盗汗、腰膝酸软、遗精。熟地黄虽滋阴补血，本方不用；鹿角胶、龟板胶为龟鹿二仙胶之品，温阳填精；人参补气，非本方所有。枸杞子滋补肝肾、益精明目，正合本方补肝肾、乌须发之旨"},{"q":"小陷胸汤组成中有","o":["半夏","黄芩","黄柏","紫苏子","莱菔子"],"a":0,"e":"小陷胸汤由黄连、半夏、瓜蒌三味组成，黄连清热泻火，半夏化痰散结、降逆，瓜蒌清热化痰、宽胸散结，共奏清热化痰、宽胸散结之功，主治痰热互结之小结胸证。黄芩、黄柏虽清热燥湿，但本方用的是黄连；紫苏子降气化痰，见苏子降气汤、定喘汤；莱菔子消食化痰，见保和丸、三子养亲汤，故组成中有半夏"},{"q":"炙甘草是四逆汤中的","o":["反佐药","佐制药","佐助药","佐使药","臣佐药"],"a":3,"e":"四逆汤由附子、干姜、炙甘草组成，回阳救逆，炙甘草益气和中、缓急，既助附子、干姜回阳，又缓和其峻烈燥烈之性，并调和诸药，兼佐、使之职，故为佐使药。反佐药是与主药性味相反相成以防格拒，本方炙甘草非反佐；佐制药侧重制约主药毒性烈性；佐助、臣佐之说均不确，唯佐使药概括其佐助与调和双重作用"},{"q":"下列各项中，属于萆薢分清饮药物组成的是","o":["益智仁","醋香附","川厚朴","远志","山药"],"a":0,"e":"萆薢分清饮由川萆薢、益智仁、石菖蒲、乌药（或加茯苓、甘草梢、食盐）组成，温肾利湿、分清去浊，主治下焦虚寒之膏淋、白浊，小便频数、浑浊如米泔。醋香附疏肝理气，川厚朴燥湿行气，远志宁心祛痰，山药健脾补肾，皆非本方组成。益智仁温肾助阳、缩尿止浊，与萆薢、菖蒲、乌药相伍，温肾化气、分清泄浊"},{"q":"不属于龙胆泻肝汤主治证候的是","o":["肝火上炎之胁痛","肝火上炎之目赤","肝火上炎之耳肿","肝火犯胃之呕吐吞酸","肝经湿热下注之阴肿"],"a":3,"e":"龙胆泻肝汤泻肝胆实火、清下焦湿热，主治肝胆实火上炎之头痛目赤、胁痛口苦、耳聋耳肿，及肝经湿热下注之阴肿阴痒、小便淋浊、妇女带下。肝火犯胃之呕吐吞酸、胁痛口苦，系肝火横逆犯胃、胃失和降，为左金丸主治，非龙胆泻肝汤所主。肝火上炎之胁痛、目赤、耳肿及肝经湿热下注之阴肿均属本方证"},{"q":"主治火毒结聚之疔疮的方剂是","o":["仙方活命饮","五味消毒饮","四妙勇安汤","阳和汤","大黄牡丹汤"],"a":1,"e":"五味消毒饮由金银花、野菊花、蒲公英、紫花地丁、天葵子组成，清热解毒、消散疔疮，主治火毒结聚之疔疮痈肿、疮形如粟、坚硬根深、焮热疼痛。仙方活命饮清热解毒、消肿溃坚、活血止痛，主阳证疮疡初起；四妙勇安汤清热解毒、活血止痛，主脱疽；阳和汤温阳补血、散寒通滞，主阴疽；大黄牡丹汤泻热破瘀、散结消肿，主肠痈"},{"q":"咳血方的功效是","o":["滋阴清热，凉血止血","泻肺泄热，凉血止血","清肝宁肺，凉血止血","养阴润肺，止咳化痰","清心宁肺，养阴止血"],"a":2,"e":"咳血方以青黛、栀子清肝泻火，瓜蒌仁、海粉清肺化痰，诃子敛肺止咳，共奏清肝宁肺、凉血止血之功，主治肝火犯肺之咯血。滋阴清热、凉血止血为百合固金汤、知柏地黄丸类；泻肺泄热、凉血止血偏泻白散合凉血药；养阴润肺、止咳化痰是贝母瓜蒌散、百合固金汤之用；清心宁肺、养阴止血非本方"},{"q":"痛泻要方的功用是","o":["温补脾肾，涩肠止泻","清热燥湿，厚肠止泻","清热解毒，凉血止痢","补脾柔肝，祛湿止泻","健脾和中，渗湿止泻"],"a":3,"e":"痛泻要方由白术、白芍、陈皮、防风组成，补脾柔肝、祛湿止泻，主治脾虚肝旺之痛泻，肠鸣腹痛、大便泄泻、泻后痛缓、脉弦。温补脾肾、涩肠止泻是真人养脏汤、四神丸；清热燥湿、厚肠止泻为葛根芩连汤、芍药汤类；清热解毒、凉血止痢是白头翁汤；健脾和中、渗湿止泻为参苓白术散，皆非痛泻要方之主治"},{"q":"六味地黄丸加何药为都气丸","o":["枸杞子","五味子","麦门冬","知母","黄柏"],"a":1,"e":"六味地黄丸加五味子即为都气丸，于滋补肾阴之中加五味子敛肺纳气、涩精止泻，主治肾阴虚兼肺气上逆之喘促、久咳、遗精、泄泻。枸杞子加入六味地黄丸为杞菊地黄丸，养肝明目；麦门冬加入为麦味地黄丸，滋阴润肺；知母、黄柏加入为知柏地黄丸，滋阴降火，故加五味子成都气丸，功在纳气归肾"},{"q":"川芎茶调散配伍的臣药是","o":["薄荷、防风","荆芥、羌活","防风、白芷","薄荷、荆芥","羌活、白芷"],"a":3,"e":"川芎茶调散以川芎为君，祛风活血、止痛，尤善治少阳、厥阴头痛；臣药薄荷、荆芥辛散轻扬，清利头目、疏风止痛，助君药祛风止痛。防风、白芷、羌活、细辛各入不同经络以治诸经头痛，为佐药；羌活、白芷治太阳、阳明头痛，属分经论治之佐药，非臣药，故臣药为薄荷、荆芥"},{"q":"六味地黄丸中用量最大的药物是","o":["熟地黄","山茱萸","山药","茯苓","泽泻"],"a":0,"e":"六味地黄丸中熟地黄用量最大，滋阴补肾、填精益髓为君，重在补肾阴；山茱萸补养肝肾、涩精，山药补益脾肾、固精，共为臣药，三补之药熟地量最重。泽泻利湿泄浊、防熟地之滋腻，牡丹皮清泄相火、制山萸肉之温涩，茯苓淡渗脾湿、助山药之健运，为三泻，用量较轻。全方三补三泻、补重于泻，熟地黄用量独大"},{"q":"症见喉间起白如腐，不易拭去，咽喉肿痛，鼻干唇燥，呼吸有声，宜选的方剂是","o":["百合固金汤","当归六黄汤","清燥救肺汤","玉液汤","养阴清肺汤"],"a":4,"e":"养阴清肺汤养阴清肺、解毒利咽，主治白喉，症见喉间起白如腐、不易拭去、咽喉肿痛、鼻干唇燥、呼吸有声、脉数，为阴虚燥热、疫毒上攻咽喉。百合固金汤滋养肺肾、止咳化痰，主肺肾阴虚咳嗽咯血；当归六黄汤滋阴泻火、固表止汗，主盗汗；清燥救肺汤清燥润肺，主温燥伤肺；玉液汤益气滋阴、固肾止渴，主消渴"},{"q":"方剂中针对兼病或兼证起主要治疗作用的药物是","o":["臣药","佐助药","使药","反佐药","佐制药"],"a":0,"e":"方剂中臣药有双重意义：一是辅助君药加强治疗主病、主证的药物，二是针对重要的兼病或兼证起主要治疗作用的药物。佐助药协助君、臣药加强治疗作用，或直接治疗次要兼证；使药引经或调和诸药；反佐药与君药性味相反而相成，防格拒；佐制药制约君、臣药的峻烈毒性。故针对兼病或兼证起主要治疗作用者归属臣药"},{"q":"槐花散的组成药物中无以下哪种药物","o":["侧柏叶","荆芥穗","枳壳","槐花","地榆"],"a":4,"e":"槐花散由槐花、侧柏叶、荆芥穗、枳壳组成，清肠止血、疏风行气，主治肠风脏毒下血。侧柏叶、荆芥穗、枳壳、槐花皆在方中：槐花、侧柏叶凉血止血，荆芥穗疏风，枳壳行气。地榆凉血止血、解毒敛疮，虽常用于便血、痔血，如槐角丸用地榆，但槐花散原方并未用之，故组成中无地榆"},{"q":"肾气丸中山茱萸与附子的用量比例是","o":["8∶1","6∶1","2∶1","3∶1","4∶1"],"a":4,"e":"金匮肾气丸用量为干地黄八两、山药四两、山茱萸四两、泽泻三两、茯苓三两、牡丹皮三两、桂枝一两、附子一两，山茱萸四两与附子一两之比为四比一。八比一、六比一、二比一、三比一皆与原方剂量不符。本方重用滋阴之品，仅少佐桂枝、附子温阳化气，取少火生气之意，故山茱萸用量远大于附子"},{"q":"定喘汤的功用是","o":["宣肺降气，疏风止咳","降气平喘，祛痰止咳","宣肺降气，清肺平喘","降气快膈，化痰消食","降逆化痰，益气和胃"],"a":2,"e":"定喘汤由白果、麻黄、苏子、甘草、款冬花、杏仁、桑白皮、黄芩、半夏组成，宣肺降气、清肺平喘，主治风寒外束、痰热内蕴之哮喘咳嗽、痰多黄稠、恶寒发热。宣肺降气、疏风止咳偏止嗽散、杏苏散；降气平喘、祛痰止咳是苏子降气汤；降气快膈、化痰消食非本方；降逆化痰、益气和胃是旋覆代赭汤"},{"q":"肝肺同治，于清肝宁肺中求止血之功的方剂是","o":["咳血方","龙胆泻肝汤","小蓟饮子","十灰散","镇肝熄风汤"],"a":0,"e":"咳血方以青黛、栀子清肝泻火，瓜蒌、海粉清肺化痰，诃子敛肺止咳，于清肝宁肺之中求止血之功，体现肝肺同治、木火刑金者清肝即所以宁肺，主治肝火犯肺之咯血。龙胆泻肝汤泻肝胆实火、清下焦湿热，不涉肺；小蓟饮子凉血止血、利水通淋，主血淋；十灰散凉血止血，主血热妄行；镇肝熄风汤镇肝息风，主类中风"},{"q":"黄芪桂枝五物汤功用是","o":["温经散寒，养血通脉","温补阳气，益气生脉","益气和营，温经通痹","温阳补血，散寒通滞","益气补血，散寒温阳"],"a":2,"e":"黄芪桂枝五物汤由黄芪、桂枝、芍药、生姜、大枣组成（即桂枝汤去甘草、倍生姜、加黄芪），益气温经、和营通痹，主治血痹之肌肤麻木不仁、脉微涩而紧。温经散寒、养血通脉是当归四逆汤；温补阳气、益气生脉非本方；温阳补血、散寒通滞是阳和汤；本方重在黄芪益气固表、桂枝温经、姜枣和营，故功用为益气和营、温经通痹"},{"q":"半夏泻心汤与小柴胡汤两方相同的药物是","o":["人参、黄芩、半夏、干姜、甘草","人参、生姜、半夏、甘草、大枣","半夏、黄芩、人参、甘草、大枣","柴胡、人参、黄芩、甘草、生姜","半夏、黄连、黄芩、甘草、大枣"],"a":2,"e":"半夏泻心汤含半夏、黄芩、干姜、人参、黄连、甘草、大枣，小柴胡汤含柴胡、黄芩、半夏、人参、甘草、生姜、大枣，两方共有半夏、黄芩、人参、甘草、大枣五味。干姜仅半夏泻心汤有，生姜仅小柴胡汤有，二者不可混同；柴胡为小柴胡汤君药，半夏泻心汤无；黄连仅半夏泻心汤有"},{"q":"下列各项，其中哪项不是苏子降气汤用药","o":["苏子，半夏","杏仁，冬花","当归，甘草","前胡，厚朴","肉桂，生姜"],"a":1,"e":"苏子降气汤由紫苏子、半夏、前胡、厚朴、当归、肉桂、甘草、生姜、大枣、苏叶组成，苏子、半夏降气化痰，当归、甘草养血和中，前胡、厚朴降气宽胸，肉桂、生姜温肾散寒，皆为方中用药。杏仁、款冬花为定喘汤之品，功在降气止咳、温肺化痰，苏子降气汤并未用此二味，故杏仁、冬花不属于苏子降气汤用药"},{"q":"药物配伍具有“温润和平，不寒不热”特点的方剂是","o":["正柴胡饮","止嗽散","桑菊饮","小青龙汤","三拗汤"],"a":1,"e":"止嗽散由荆芥、紫菀、白前、桔梗、陈皮、百部、甘草组成，宣利肺气、疏风止咳，主治风邪犯肺之咳嗽迁延、咯痰不爽，其配伍温润和平、不寒不热，宣肺而不峻散、润肺而不滋腻，故加减可通治诸般咳嗽。正柴胡饮解表散寒，主外感风寒轻证；桑菊饮疏风清热、宣肺止咳，主风温初起；小青龙汤温肺化饮，辛散温燥；三拗汤宣肺解表，力峻"},{"q":"用治热结下焦之血淋、尿血的方剂是","o":["五苓散","小蓟饮子","槐花散","肾气丸","二妙散"],"a":1,"e":"小蓟饮子由小蓟、生地黄、藕节、蒲黄、滑石、木通、栀子、当归、竹叶、甘草组成，凉血止血、利水通淋，主治热结下焦之血淋、尿血，尿中带血、小便频数赤涩热痛。五苓散利水渗湿、温阳化气，无凉血止血；槐花散清肠止血，主便血；肾气丸温补肾阳、化气行水；二妙散清热燥湿，主湿热下注痿痹"},{"q":"一贯煎的功用是","o":["滋补肝肾","滋阴清热","滋阴降火","滋阴疏肝","滋阴凉血"],"a":3,"e":"一贯煎由北沙参、麦冬、当归、生地黄、枸杞子、川楝子组成，滋阴疏肝，主治肝肾阴虚、肝气不舒之胸胁胀痛、吞酸吐苦、咽干口燥、舌红少津、脉细弱，于大队滋阴药中少佐川楝子疏肝泄热、行气止痛，使滋阴而不滞、疏肝而不伤阴。滋补肝肾偏左归丸；滋阴清热是知柏地黄丸；滋阴降火是大补阴丸；滋阴凉血非本方"},{"q":"小建中汤中桂枝与芍药的用量比例","o":["1∶1","1∶2","1∶3","2∶1","3∶1"],"a":1,"e":"小建中汤由桂枝汤倍用芍药再加饴糖而成，桂枝汤中桂枝、芍药等量，小建中汤倍芍药后桂枝与芍药用量之比为一比二，重用芍药益阴和营、缓急止痛，配饴糖温中补虚，主治中焦虚寒之腹痛。一比一为桂枝汤之比；一比三、二比一、三比一均非小建中汤原方比例"},{"q":"小蓟饮子与八正散均可利尿通淋，小蓟饮子重在","o":["清心除烦","凉血止血","收涩止血","清肝宁肺","养血安神"],"a":1,"e":"小蓟饮子与八正散均能利尿通淋，但小蓟饮子以小蓟、生地、藕节、蒲黄凉血止血为主，配栀子、滑石、木通、竹叶清热利水，主治热结下焦之血淋、尿血，故重在凉血止血。清心除烦仅竹叶、栀子之辅功；收涩止血非本方，本方凉血止血兼利尿，不用收涩；清肝宁肺是咳血方；养血安神非本方所具，八正散则重在清热利水通淋"},{"q":"槐花散证的病机是","o":["血热妄行，损伤血络","风热湿毒，壅遏肠道","脾阳不足，脾不统血","下焦瘀热，损伤血络","肝火犯肺，损伤肺络"],"a":1,"e":"槐花散清肠止血、疏风行气，主治肠风、脏毒下血，其病机为风热湿毒壅遏肠道、损伤血络，血色鲜红、喷射而出或便后滴血。血热妄行、损伤血络是十灰散、犀角地黄汤之机；脾阳不足、脾不统血属黄土汤证，血色暗淡；下焦瘀热、损伤血络为小蓟饮子血淋；肝火犯肺、损伤肺络是咳血方"},{"q":"“病痰饮者当以温药和之”的代表方剂是","o":["苓桂术甘汤","防己黄芪汤","肾著汤","真武汤","实脾散"],"a":0,"e":"苓桂术甘汤由茯苓、桂枝、白术、甘草组成，温阳化饮、健脾利湿，主治中阳不足之痰饮（胸胁支满、目眩心悸、短气而咳），正合病痰饮者当以温药和之之旨，温阳健脾以绝生痰之源、利水化饮以祛已成之饮。防己黄芪汤益气祛风、健脾利水，主风湿、风水；肾著汤温中除湿，主寒湿腰痛；真武汤温阳利水，主脾肾阳虚水泛；实脾散温阳健脾、行气利水，主阴水"},{"q":"苏子降气汤的主治病证是","o":["痰热喘咳证","上实下虚喘咳证","肺热喘咳证","湿痰咳嗽证","寒饮咳嗽证"],"a":1,"e":"苏子降气汤降气平喘、祛痰止咳，主治上实下虚之喘咳证，上实为痰浊壅肺、喘咳痰多、胸膈满闷，下虚为肾阳不足、腰痛脚软、肢体浮肿，方以苏子、半夏、前胡、厚朴降气化痰治上实，当归、肉桂温补下元治下虚。痰热喘咳、肺热喘咳宜清化，非本方温降之剂；湿痰咳嗽宜二陈汤；寒饮咳嗽宜苓甘五味姜辛汤"},{"q":"《温热经纬》清暑益气汤的君药是","o":["西瓜翠衣和黄连","西洋参和石斛","石斛和麦冬","西瓜翠衣和石斛","西瓜翠衣和西洋参"],"a":4,"e":"《温热经纬》清暑益气汤以西瓜翠衣、西洋参为君，西瓜翠衣清解暑热，西洋参益气养阴，共奏清暑益气、养阴生津之功，主治暑热气津两伤之身热汗多、口渴心烦、体倦少气、脉虚数。黄连、石斛、麦冬、知母、竹叶等清热养阴为臣佐，荷叶、粳米、甘草清暑和中。西瓜翠衣配黄连、西洋参配石斛等均未抓住益气与清暑并重的君药组合"},{"q":"朱砂安神丸中黄连的炮制方法为","o":["生用","姜汁炒","蜜炙黄连","酒洗","以上都不正确"],"a":3,"e":"朱砂安神丸中黄连用酒洗，酒制可缓其苦寒之性，并引药上行、清心除烦，与朱砂重镇安神、生地当归养血相伍，主治心火亢盛、阴血不足之心烦失眠。生用苦寒力强，易伤胃，非本方所用；姜汁炒偏温中和胃，增强止呕；蜜炙缓和中，多用于补中或润肺，皆非朱砂安神丸黄连之制法，故炮制方法为酒洗"},{"q":"苏子降气汤的功用是","o":["宣肺降气，清热化痰","降逆化痰，益气和胃","降气平喘，祛痰止咳","温肺化饮","宣利肺气，疏风止咳"],"a":2,"e":"苏子降气汤以紫苏子降气化痰、止咳平喘为君，半夏、前胡、厚朴降气化痰、宽胸，肉桂温肾纳气，当归养血，功用降气平喘、祛痰止咳，主治上实下虚喘咳。宣肺降气、清热化痰是清气化痰丸、定喘汤之类；降逆化痰、益气和胃为旋覆代赭汤；温肺化饮是苓甘五味姜辛汤、小青龙汤；宣利肺气、疏风止咳为止嗽散"},{"q":"组成中生地和熟地同用的方剂是","o":["养阴清肺汤","百合固金汤","清燥救肺汤","增液汤","麦门冬汤"],"a":1,"e":"百合固金汤由百合、生地黄、熟地黄、麦冬、玄参、当归、白芍、贝母、桔梗、甘草组成，生地、熟地同用，滋阴凉血、补肾填精，主治肺肾阴虚、虚火上炎之咳嗽气喘、痰中带血、咽喉燥痛。养阴清肺汤只用生地，无熟地；清燥救肺汤无二地同用；增液汤用生地、玄参、麦冬；麦门冬汤养阴润肺，均无生地、熟地并用之配伍"},{"q":"主治外感风寒，郁而化热证的方剂是","o":["小青龙汤","升麻葛根汤","竹叶柳蒡汤","柴葛解肌汤","葱豉桔梗汤"],"a":3,"e":"柴葛解肌汤解肌清热，主治外感风寒、郁而化热证，见恶寒渐轻、身热增盛、无汗头痛、目疼鼻干、心烦不眠、眼眶痛、脉浮微洪，方以柴胡、葛根解肌清热，黄芩、石膏清热，羌活、白芷、桔梗散邪。小青龙汤解表散寒、温肺化饮，主外寒内饮；升麻葛根汤解肌透疹，主麻疹初起；竹叶柳蒡汤透疹清热，主痧疹；葱豉桔梗汤疏风清热，主风温初起"},{"q":"天麻钩藤饮配伍的臣药是","o":["杜仲、怀牛膝","川牛膝、石决明","杜仲、桑寄生","川牛膝、桑寄生","杜仲、石决明"],"a":1,"e":"天麻钩藤饮以天麻、钩藤平肝息风为君，臣以川牛膝引血下行、活血通经，石决明平肝潜阳、除热明目，助君药平肝息风、引阳下潜，佐以栀子、黄芩清热，杜仲、桑寄生补肝肾，茯神、夜交藤安神，益母草活血利水。杜仲、桑寄生重在补益肝肾，为佐药，非臣药，故臣药为川牛膝、石决明"},{"q":"温脾汤的功用是","o":["温里散寒、通便止痛","泻下寒积、散寒止痛","温补脾阳、润肠通便","温肾益精、攻逐寒积","攻下冷积、温补脾阳"],"a":4,"e":"温脾汤由大黄、附子、干姜、人参、甘草（或加当归、芒硝）组成，攻下冷积、温补脾阳，主治阳虚寒积之腹痛便秘、脐腹绞痛、手足不温、脉沉弦，以大黄攻逐寒积，附子、干姜温阳散寒，人参、甘草补脾益气。温里散寒、通便止痛是大黄附子汤，无补脾；泻下寒积、散寒止痛未及温补；温补脾阳、润肠通便偏温阳润下；温肾益精、攻逐寒积非本方"},{"q":"阳和汤中可达皮里膜外，具有温化寒痰，通络散结作用的药物是","o":["麻黄","白芥子","肉桂","炮姜炭","生甘草"],"a":1,"e":"阳和汤中白芥子辛温，善达皮里膜外，温化寒痰、通络散结，与熟地、鹿角胶养血助阳，肉桂、姜炭温阳散寒，麻黄开腠达表，生甘草调和相伍，温阳补血、散寒通滞，主治阴疽漫肿无头、皮色不变、酸痛无热。麻黄开腠理、散风寒，非化寒痰；肉桂、炮姜炭温阳散寒，无祛痰通络之长；生甘草调和诸药，故温化寒痰、通络散结者白芥子"},{"q":"大承气汤和大陷胸汤中均有的药物是","o":["大黄、甘草","芒硝、甘草","芒硝、枳实","枳实、厚朴","大黄、芒硝"],"a":4,"e":"大承气汤由大黄、芒硝、枳实、厚朴组成，峻下热结；大陷胸汤由大黄、芒硝、甘遂组成，泻热逐水，两方共有大黄、芒硝，同为泻下攻逐之要药。甘草二方均无；枳实、厚朴仅大承气汤有，行气除满；芒硝、枳实组合，枳实不在大陷胸汤；枳实、厚朴更非大陷胸汤所有，故两方共有药物为大黄、芒硝"},{"q":"蒿芩清胆汤的主治证是","o":["湿热壅阻膀胱证","脾胃湿浊阻滞证","肝郁血虚脾弱证","表里寒热错杂证","少阳湿热痰浊证"],"a":4,"e":"蒿芩清胆汤清胆利湿、和胃化痰，由青蒿、黄芩、竹茹、半夏、枳壳、陈皮、茯苓、碧玉散组成，主治少阳湿热痰浊之寒热如疟、寒轻热重、口苦膈闷、吐酸苦水、胸胁胀痛，病机为少阳湿热、痰浊内阻。湿热壅阻膀胱宜八正散；脾胃湿浊阻滞宜平胃散、藿香正气散；肝郁血虚脾弱是逍遥散证；表里寒热错杂是柴胡桂枝汤、半夏泻心汤类"},{"q":"茵陈蒿汤中，清热降火，导邪从小便而出的药物是","o":["栀子","茵陈","大黄","青蒿","滑石"],"a":0,"e":"茵陈蒿汤中栀子清热降火、通利三焦，导湿热从小便而出，与茵陈蒿清热利湿退黄、大黄泻热逐瘀通便相伍，共奏清热、利湿、退黄之功，主治湿热黄疸（阳黄）身目俱黄、黄色鲜明、腹满便秘、小便短赤。茵陈为君，重在利湿退黄；大黄泻热通便，导瘀热从大便而去；青蒿、滑石非本方药物，故导邪从小便而出者栀子"},{"q":"以下关于大秦艽汤的配伍特点描述错误的是","o":["辛温甘寒","外散内补","气血兼顾","寓降于升","清养并行"],"a":3,"e":"大秦艽汤疏风清热、养血活血，主治风邪初中经络之口眼歪斜、舌强不能言语、手足不能运动，其配伍特点为辛温药与甘寒药并用（辛温甘寒）、外散风邪与内补气血兼顾（外散内补）、气血兼顾、清热与养阴并行（清养并行）。寓降于升并非本方特点，本方以疏风散邪、升散通络为主，无降逆降火之配伍意图，故寓降于升为错误描述"},{"q":"四神丸的组成中有","o":["肉豆蔻、山茱萸","肉豆蔻、赤石脂","肉豆蔻、补骨脂","五味子、山茱萸","五味子、赤石脂"],"a":2,"e":"四神丸由补骨脂、肉豆蔻、五味子、吴茱萸（加生姜、大枣）组成，温肾暖脾、固肠止泻，主治脾肾阳虚之五更泄泻。山茱萸补肝肾、涩精，非本方；赤石脂涩肠止泻，见桃花汤、真人养脏汤；五味子虽在方，但与山茱萸、赤石脂的搭配均不成立，唯有肉豆蔻、补骨脂温肾暖脾、固肠止泻，为四神丸核心药对"},{"q":"组成中有山药的方是","o":["金锁固精丸","缩泉丸","桑螵蛸散","固冲汤","四神丸"],"a":1,"e":"缩泉丸由益智仁、乌药、山药三味组成，温肾祛寒、缩尿止遗，主治膀胱虚寒之小便频数、遗尿，山药健脾补肾、固精缩尿，为本方组成。金锁固精丸用沙苑子、芡实、莲须、龙骨、牡蛎、莲子粉，无山药；桑螵蛸散用桑螵蛸、龙骨、龟甲等，无山药；固冲汤、四神丸亦无山药，故组成中有山药者为缩泉丸"},{"q":"四君子汤证的病机是","o":["脾肾阳虚，水湿内停","脾胃虚弱，湿自内生","脾胃气虚，纳谷与运化乏力","脾胃气虚，饮食停滞","脾胃虚弱，中气下陷"],"a":2,"e":"四君子汤由人参、白术、茯苓、甘草组成，益气健脾，主治脾胃气虚证，见面色苍白、语声低微、四肢乏力、食欲不振、大便溏薄、舌淡苔白、脉虚弱，其病机为脾胃气虚、纳谷与运化乏力。脾肾阳虚、水湿内停偏真武汤、实脾散；脾胃虚弱、湿自内生偏参苓白术散；脾胃气虚、饮食停滞宜健脾丸、香砂六君；脾胃虚弱、中气下陷是补中益气汤证"},{"q":"普济消毒饮中体现“火郁发之”治法的药物是","o":["黄连、黄芩","桔梗、连翘","升麻、柴胡","玄参、板蓝根","橘红、牛蒡子"],"a":2,"e":"普济消毒饮中升麻、柴胡辛凉升散，疏散风热、引药上行头面，并寓火郁发之之意，使郁遏之热毒发散而出，与黄芩、黄连清热解毒相伍，主治大头瘟风热疫毒上攻头面之头面红肿焮痛。黄连、黄芩苦寒清热泻火，属清泄而非发散；桔梗、连翘、牛蒡子疏风利咽；玄参、板蓝根清热解毒、凉血；橘红理气，皆非体现火郁发之之药"},{"q":"下列哪味药不是温胆汤的组成","o":["竹茹","枳壳","橘皮","半夏","茯苓"],"a":1,"e":"温胆汤由半夏、竹茹、枳实、陈皮、茯苓、炙甘草、生姜、大枣组成，理气化痰、和胃利胆。竹茹清热化痰、除烦止呕，橘皮即陈皮理气化痰，半夏燥湿化痰、降逆和胃，茯苓健脾渗湿，皆为方中药物。枳壳与枳实虽同类，但温胆汤原方用枳实破气消积、化痰除痞，而非枳壳之力较缓和、偏宽中下气，故枳壳不属于温胆汤组成"},{"q":"四逆散与四逆汤共用的药物是","o":["柴胡","干姜","甘草","枳实","芍药"],"a":2,"e":"四逆散由柴胡、芍药、枳实、炙甘草组成，透邪解郁、疏肝理脾；四逆汤由附子、干姜、炙甘草组成，回阳救逆，两方共有炙甘草，益气和中、调和诸药。柴胡、枳实、芍药仅四逆散有，疏肝理脾；干姜、附子仅四逆汤有，温阳散寒回阳，故两方共用药物为甘草。两方虽同名四逆，然一治气郁致厥、一治阳虚寒厥，仅甘草为共有"},{"q":"定喘汤清泻肺热的药物是","o":["桑白皮、地骨皮","桑白皮 、黄芩","地骨皮、黄芩、石膏","石膏、知母","黄芩、黄连"],"a":1,"e":"定喘汤中桑白皮泻肺平喘、清肺热，黄芩清热燥湿、泻火，二药相伍清泻肺热、化痰平喘，针对痰热内蕴之哮喘咳嗽、痰多黄稠。地骨皮清虚热、凉血，非本方清泻肺热之品；石膏、知母清气分实热，本方不用；黄连清心胃火，非肺经专药，本方用黄芩不用黄连，故清泻肺热者为桑白皮、黄芩"},{"q":"仙方活命饮与普济消毒饮两方共同的药物是","o":["贝母","连翘","金银花","陈皮","乳香"],"a":3,"e":"仙方活命饮含白芷、贝母、防风、赤芍、当归尾、甘草节、皂角刺、穿山甲、天花粉、乳香、没药、金银花、陈皮；普济消毒饮含黄芩、黄连、陈皮、甘草、玄参、柴胡、桔梗、连翘、板蓝根、马勃、牛蒡子、薄荷、僵蚕、升麻。两方共有陈皮、甘草，选项中为陈皮，理气和中、助消肿散结。贝母、连翘、乳香、金银花仅仙方活命饮有"},{"q":"增液汤的组成是","o":["人参、麦冬、生地","玄参、麦冬、生地","人参、天冬、生地","玄参、天冬、熟地","人参、麦冬、熟地"],"a":1,"e":"增液汤由玄参、麦冬、生地黄三味组成，滋阴清热、润燥通便，主治阳明温病、津亏便秘（增液行舟），玄参滋阴降火、解毒，麦冬养阴润肺、益胃生津，生地滋阴凉血、生津。人参补气，非本方；天冬滋阴润肺，本方未用；熟地滋腻偏补血，本方用生地不用熟地，故增液汤组成为玄参、麦冬、生地"},{"q":"下列选项中，不属于黄龙汤组成的是","o":["麦冬","人参","当归","大黄","桔梗"],"a":0,"e":"黄龙汤由大黄、芒硝、枳实、厚朴、人参、当归、甘草、桔梗（加生姜、大枣）组成，即大承气汤加益气养血之品，攻下热结、益气养血，主治阳明腑实、气血不足。人参、当归、大黄、桔梗皆在方中：人参、当归益气养血，大黄攻下，桔梗宣肺利气、助通腑。麦冬养阴润肺，不在黄龙汤原方，故麦冬不属于其组成"},{"q":"治疗湿痰的代表方剂为","o":["清气化痰丸","贝母瓜蒌散","温胆汤","二陈汤","茯苓丸"],"a":3,"e":"二陈汤由半夏、橘红（陈皮）、茯苓、炙甘草（加生姜、乌梅）组成，燥湿化痰、理气和中，主治湿痰咳嗽之痰多色白易咯、胸膈痞闷、恶心呕吐、舌苔白腻、脉滑，为治湿痰之代表方，后世化痰方多由此加减。清气化痰丸治痰热；贝母瓜蒌散治燥痰；温胆汤治胆郁痰扰；茯苓丸治痰停中脘，皆非湿痰通治之基础代表方"},{"q":"体现“实则泻其子”治法的方剂是","o":["导赤散","左金丸","泻青丸","龙胆泻肝汤","当归龙荟丸"],"a":1,"e":"左金丸由黄连、吴茱萸（六比一）组成，清肝泻火、降逆止呕，主治肝火犯胃之胁肋胀痛、呕吐吞酸、口苦，肝属木，心属火为肝之子，泻心火即泻肝之子，体现实则泻其子之法，同时辛开苦降、寒温并用。导赤散清心利水；泻青丸清肝泻火；龙胆泻肝汤泻肝胆实火、清下焦湿热；当归龙荟丸泻肝火，皆非以实则泻其子的配伍立论"},{"q":"清气化痰丸中没有使用的药物是","o":["陈皮","半夏","茯苓","紫菀","胆南星"],"a":3,"e":"清气化痰丸由陈皮、杏仁、枳实、黄芩、瓜蒌仁、茯苓、胆南星、半夏（姜汁糊丸）组成，清热化痰、理气止咳，主治痰热咳嗽。陈皮、半夏、茯苓理气化痰、健脾燥湿，胆南星清热化痰，皆在方中；紫菀润肺下气、止咳化痰，性温，多用于风寒或虚劳咳嗽，如止嗽散，清气化痰丸治痰热并未用紫菀"},{"q":"《温热经纬》清暑益气汤功能清暑益气，尚可","o":["敛阴止汗","利水化湿","和胃止呕","化湿止泻","养阴生津"],"a":4,"e":"《温热经纬》清暑益气汤于清暑益气之外，尚能养阴生津，方中西洋参、石斛、麦冬、知母等益气养阴、清热生津，主治暑热伤气阴之身热汗多、口渴心烦、体倦少气、小便短赤、脉虚数。敛阴止汗偏生脉散之五味子；利水化湿偏六一散、五苓散；和胃止呕偏藿香正气散、半夏类；化湿止泻偏葛根芩连汤、六一散"},{"q":"原方特别注明“不用姜”的方剂是","o":["平胃散","二陈汤","定喘汤","苏子降气汤","半夏白术天麻汤"],"a":2,"e":"定喘汤原方特别注明不用姜，因其主治风寒外束、痰热内蕴之哮喘，方中麻黄宣肺散寒，黄芩、桑白皮清泻肺热，生姜辛温助热，恐其助痰热、动火伤肺，故不用。平胃散、二陈汤均用生姜和胃化痰；苏子降气汤用生姜、苏叶散寒降逆；半夏白术天麻汤用生姜和胃，皆未注明不用姜"},{"q":"黄土汤的功效是","o":["益气健脾，养血止血","温经散寒，祛瘀止血","温补脾胃，温经止血","温阳健脾，养血止血","益气养血，收敛止血"],"a":3,"e":"黄土汤以灶心土温中止血为君，白术、附子温阳健脾，生地、阿胶养血止血，黄芩反佐清热，甘草调和，共奏温阳健脾、养血止血之功，主治脾阳不足、脾不统血之便血、吐衄、崩漏，血色暗淡。益气健脾、养血止血偏归脾汤；温经散寒、祛瘀止血是温经汤；温补脾胃、温经止血表述重复；益气养血、收敛止血非本方刚柔相济之能"},{"q":"何方配伍取“少火生气”之义","o":["肾气丸","十补丸","右归丸","右归饮","龟鹿二仙胶"],"a":0,"e":"肾气丸于大队滋阴药（干地黄、山药、山萸肉）中，少佐桂枝、附子温阳之品，温阳之力小而缓，取少火生气之义，意在温补肾阳、化气行水而不燥烈伤阴，主治肾阳不足之腰痛脚弱、小便不利或反多。十补丸、右归丸、右归饮温补肾阳之力较强，纯补命门，无少火生气之妙；龟鹿二仙胶填补精血"},{"q":"真人养脏汤、四神丸两方中共有的药物是","o":["补骨脂","肉桂","人参","肉豆蔻","五味子"],"a":3,"e":"真人养脏汤含人参、白术、当归、白芍、肉桂、肉豆蔻、诃子、罂粟壳、木香、甘草，温补脾肾、涩肠固脱；四神丸含补骨脂、肉豆蔻、五味子、吴茱萸、生姜、大枣，温肾暖脾、固肠止泻，两方共有肉豆蔻，温中涩肠止泻。补骨脂仅四神丸有；肉桂、人参仅真人养脏汤有；五味子仅四神丸有，故两方共有药物为肉豆蔻"},{"q":"补中益气汤证的病机为","o":["脾胃气虚","脾胃气虚，湿自内生","脾胃气虚，清阳下陷","卫气虚弱，不能固表","肺肾虚衰，气逆不降"],"a":2,"e":"补中益气汤补中益气、升阳举陷，由黄芪、人参、白术、甘草、当归、陈皮、升麻、柴胡组成，主治脾胃气虚、清阳下陷之脱肛、子宫脱垂、久泻久痢、少气懒言、气虚发热，其病机为脾胃气虚、清阳下陷。单纯脾胃气虚是四君子汤证；脾胃气虚、湿自内生是参苓白术散证；卫气虚弱、不能固表是玉屏风散证；肺肾虚衰、气逆不降属苏子降气汤、都气丸类"},{"q":"大秦艽汤与独活寄生汤组成中共有的药物是","o":["秦艽、防风、独活、生地黄、茯苓","细辛、甘草、当归、羌活、川芎","秦艽、芍药、独活、熟地黄、川芎","独活、茯苓、细辛、当归、防风","秦艽、独活、干地黄、川芎、甘草"],"a":3,"e":"大秦艽汤含秦艽、川芎、独活、芍药、防风、白芷、细辛、黄芩、石膏、甘草、当归、白术、茯苓、生地、熟地、羌活；独活寄生汤含独活、桑寄生、杜仲、牛膝、细辛、秦艽、茯苓、肉桂心、防风、川芎、人参、甘草、当归、芍药、干地黄。两方共有独活、茯苓、细辛、当归、防风、秦艽、川芎、芍药、甘草等，所列独活、茯苓、细辛、当归、防风全部为两方共有，余项多含羌活、桂枝等不共有之品"},{"q":"葛根黄芩黄连汤的主治证是","o":["外感风热证","表证未解，邪热入里证","邪热壅肺证","湿热痢疾","外寒内饮证"],"a":1,"e":"葛根黄芩黄连汤解表清热，由葛根、黄芩、黄连、甘草组成，主治表证未解、邪热入里之协热下利，身热下利、胸脘烦热、口干作渴、喘而汗出、舌红苔黄、脉数，葛根升阳解肌、止泻，芩连清热燥湿止痢。外感风热证宜银翘散；邪热壅肺证宜麻杏甘石汤；湿热痢疾宜芍药汤、白头翁汤；外寒内饮证宜小青龙汤"},{"q":"交泰丸的主治证是","o":["心火偏亢，气血两虚证","心火偏亢，肝阳上亢证","心肾气虚，心肾不交证","心肝血虚，虚火上炎证","心火偏亢，心肾不交证"],"a":4,"e":"交泰丸仅黄连、肉桂两味，黄连清降心火，肉桂温肾助阳、引火归元，一清一温使心肾相交，主治心火偏亢、心肾不交之失眠。气血两虚当用归脾汤，非A项所主；肝阳上亢与心肝血虚虚火上炎分别为镇肝熄风汤、酸枣仁汤类证，B、D项不符；本方针对心火而非心肾气虚，C项排除"},{"q":"地黄饮子主治的病证为","o":["痰饮","喑痱","消渴","脚气","转胞"],"a":1,"e":"地黄饮子熟地、山茱萸滋肾填精，附子、肉桂温养下元，石菖蒲、远志、茯苓化痰开窍、交通心肾，主治下元虚衰、虚阳上浮、痰浊阻窍之喑痱，见舌强不能言、足废不能用。痰饮为饮停中焦，消渴与阴虚燥热相关，脚气多湿热下注，转胞为妊娠小便不通，均与本方病机无涉，A、C、D、E项各有所主"},{"q":"下列哪项不是大枣在十枣汤中配伍意义","o":["益脾缓中","固护胃气","培土制水","缓诸药毒","补脾养血"],"a":4,"e":"十枣汤以芫花、甘遂、大戟峻下逐水，用大枣十枚煮汤送服，意在益脾缓中、固护胃气，并缓和三药毒性，又以培土制水顾护中焦，使攻下不伤正。大枣于此并不取补脾养血之功，补血当归、熟地类，故E项非其配伍意义；A、B、C、D均体现护中减毒之旨"},{"q":"以下关于阿胶鸡子黄汤证的辨证要点描述错误的是","o":["高热神昏","筋脉拘急","手足瘛疭","舌绛苔少","脉细数"],"a":0,"e":"阿胶鸡子黄汤滋阴养血、柔肝息风，主治热邪久羁、阴血亏虚、虚风内动，辨证以筋脉拘急、手足瘛疭、舌绛苔少、脉细数为要点。高热神昏属热闭心包、邪热炽盛之实证，当用安宫牛黄丸类凉开，非本方虚风内动所见，A项描述错误；B、C、D、E均为本方主证"},{"q":"白虎汤中配伍石膏的意义是","o":["清热解毒","清热滋阴","清热凉血","清退虚热","清热除烦止渴"],"a":4,"e":"白虎汤石膏辛甘大寒，直清阳明气分大热，又能透热外出，解肌清热而不遏邪，配知母助清热滋阴，共奏清热除烦止渴之效，为治气分热盛之要药。清热解毒指板蓝根、黄连类；清热凉血属犀角地黄汤；清退虚热为青蒿、地骨皮；B项清热滋阴是知母、生地之能，均非石膏主要意义"},{"q":"不属于白虎汤适应证的是","o":["壮热面赤","烦渴引饮","汗出恶热","脉洪大无力","脉洪大有力"],"a":3,"e":"白虎汤主治气分热盛，见壮热面赤、烦渴引饮、汗出恶热、脉洪大有力，为实热证。脉洪大无力提示气虚或虚阳外越，非实热，投以大寒之品更伤中阳，故属禁忌。A、B、C、E皆阳明经热盛典型表现，与本方证相符；D项脉无力当以白虎加人参汤或他方辨证，不单用白虎汤"},{"q":"槐花散中用以行气宽肠，使气调血调的药物是","o":["厚朴","槟榔","枳壳","陈皮","木香"],"a":2,"e":"槐花散用槐花、侧柏叶凉血止血，荆芥穗疏风理血，佐枳壳行气宽肠，使气机调畅则血行归经，气调血调，共治肠风脏毒下血。厚朴、陈皮重在燥湿行气消胀，木香行气止痛多用于痢疾后重，槟榔偏破气导滞，皆非本方行气宽肠、调气和血之品，A、B、D、E项不符"},{"q":"导赤散中的君药是","o":["黄连","甘草","竹叶","木通","生地黄"],"a":4,"e":"导赤散生地黄甘寒，凉血滋阴以制心火，又滋肾水，标本兼顾而为君药。木通清心降火、利水通淋为臣，竹叶清心除烦，甘草梢清热解毒、缓急调和为使。黄连清心解毒力强，为黄连阿胶汤、朱砂安神丸之属，非本方所有；甘草、竹叶、木通在此为臣佐使，均非君药，A、B、C、D项排除"},{"q":"大秦艽汤配伍的臣药是","o":["羌活、独活、防风、白芷、细辛","生地、熟地、当归、白芍、川芎","羌活、独活、川芎、当归、白术","生地、当归、白芍、白术、甘草","熟地、川芎、白芷、羌活、独活"],"a":0,"e":"大秦艽汤以秦艽为君，祛风通络、清虚热；臣以羌活、独活、防风、白芷、细辛诸辛温之品，祛风散邪、胜湿止痛，助君药搜剔经络之风。生地、熟地、当归、白芍、川芎等为养血活血之佐，寓治风先治血之意；白术、甘草健脾益气，均非臣药，故B、C、D、E项所列多为佐药或混杂组方"},{"q":"可以治疗湿温病及风湿热痹的方剂是","o":["三仁汤","竹叶石膏汤","白虎加苍术汤","白虎加桂枝汤","白虎加人参汤"],"a":2,"e":"白虎加苍术汤即白虎汤加苍术，石膏、知母清气分实热，苍术燥湿健脾，共奏清热祛湿之功，主治湿温身热、胸闷及风湿热痹。三仁汤宣上畅中渗下，治湿温初起湿重于热，无清气分之能；白虎加桂枝汤虽治风湿热痹但无燥湿之力，不主湿温；白虎加人参汤益气生津，竹叶石膏汤养阴和胃，A、B、D、E项排除"},{"q":"下列方剂中，需要去滓，再煎的是","o":["小柴胡汤","银翘散","麻黄汤","小建中汤","痛泻要方"],"a":0,"e":"小柴胡汤煎法特殊，诸药同煎后去滓，再煎取汁，使药性醇和、和解少阳而不峻烈，为和解剂代表。银翘散、麻黄汤均芳香辛散，久煎则药性散失，当轻煎或后下；小建中汤重在饴糖缓中，痛泻要方亦无再煎之法，B、C、D、E项均不取去滓再煎，惟A项合和解法度"},{"q":"小柴胡汤中，一散一清，恰入少阳，以解少阳之邪的配伍是","o":["半夏、生姜","柴胡、黄芩","柴胡、生姜","黄芩、大枣","半夏、黄芩"],"a":1,"e":"小柴胡汤柴胡辛散，透泄少阳之邪、疏畅气机，黄芩苦寒，清泄少阳之热，一散一清恰入少阳，共解少阳之邪，为和解少阳的核心配伍。半夏、生姜和胃降逆止呕，针对胆气犯胃；大枣益气和中，非清泄之品；诸药各司其职，均无透邪清热的双重作用，A、C、D、E项不构成此配伍"},{"q":"牵正散的君药是","o":["白附子","黑附子","白僵蚕","黑僵蚕","全蝎"],"a":0,"e":"牵正散白附子辛温有毒，善祛头面之风痰、通络止痛，直中病所而为君药。白僵蚕祛风通络、化痰散结为臣，全蝎搜风通络、止痉为佐，热酒送服引药入络。方中并无黑附子、黑僵蚕，B、D项属臆造；白僵蚕、全蝎分别为臣佐，C、E项非君药，故均排除"},{"q":"当归拈痛汤与五苓散共司的药物是","o":["泽泻，白术，苍术","茯苓，苍术，猪苓","泽泻，苍术，猪苓","泽泻，白术，茯苓","泽泻，白术，猪苓"],"a":4,"e":"当归拈痛汤清热利湿、疏风止痛，方中伍泽泻、猪苓、白术利水渗湿健脾；五苓散由茯苓、猪苓、泽泻、白术、桂枝组成，功主利水渗湿、温阳化气。两方共有的利水健脾药正是泽泻、白术、猪苓。苍术只见于当归拈痛汤，茯苓仅五苓散有之，故含苍术的A、B、C项与含茯苓的B、D项均非共有药物"},{"q":"下列方剂组成中不含大黄的是","o":["大陷胸汤","麻子仁丸","温脾汤","济川煎","黄龙汤"],"a":3,"e":"济川煎温肾益精、润肠通便，由肉苁蓉、当归、牛膝、泽泻、升麻、枳壳组成，主治肾虚便秘，方中并无大黄。大陷胸汤、麻子仁丸、温脾汤、黄龙汤均配大黄以泻下攻积或泄热通腑，其中麻子仁丸含小承气汤、黄龙汤含大承气汤，皆以大黄为攻下主药，A、B、C、E项均含大黄，D项符合"},{"q":"四逆散中一升一降配伍的药物是","o":["柴胡配芍药","柴胡配甘草","柴胡配枳实","枳实配芍药","柴胡配枳壳"],"a":2,"e":"四逆散柴胡升发阳气、疏肝解郁、透邪外出，枳实降气导滞、消积除痞，一升一降，使气机升降复常、郁热得达，共为君药，配合芍药、甘草柔肝缓急。柴胡配芍药偏柔肝和血，柴胡配甘草宗泻心之意，枳实配芍药重在行气和血，均非升降相因之配；E项枳壳非原方用药，A、B、D、E项不合"},{"q":"痛泻要方与补中益气汤组成中共有的药物是","o":["黄芪","防风","当归","柴胡","白术"],"a":4,"e":"痛泻要方由白术、白芍、陈皮、防风组成，补中益气汤含黄芪、人参、白术、炙甘草、当归、陈皮、升麻、柴胡，两方共有的药物为白术（陈皮虽亦共有，但选项中未列）。黄芪、柴胡、当归只见于补中益气汤，防风为痛泻要方所独有，均非两方共有，A、B、C、D项排除，E项白术即痛泻要方之君药"},{"q":"功用为清热化痰，理气止咳的方剂是","o":["小陷胸汤","清气化痰丸","贝母瓜蒌散","温胆汤","麻黄汤"],"a":1,"e":"清气化痰丸胆南星、瓜蒌仁清热化痰，黄芩清肺热，杏仁、陈皮、枳实、茯苓理气化痰，主治痰热咳嗽，功擅清热化痰、理气止咳。小陷胸汤清热化痰、宽胸散结，主痰热结胸；贝母瓜蒌散润肺清热、理气化痰，治燥痰；温胆汤理气化痰、和胃利胆，治胆郁痰扰；麻黄汤发汗解表，均非本功，A、C、D、E项排除"},{"q":"贝母瓜萎散组成中没有","o":["半夏","瓜蒌","茯苓","桔梗","天花粉"],"a":0,"e":"贝母瓜蒌散由贝母、瓜蒌、天花粉、茯苓、橘红、桔梗组成，润肺清热、理气化痰，主治燥痰咳嗽。方中刻意不用半夏等辛温燥烈之品，恐其劫伤肺津、燥痰愈燥，故半夏不在其列。瓜蒌、茯苓、桔梗、天花粉均为原方药物，B、C、D、E项即本方组成，A项半夏是二陈汤、清气化痰丸之属，非本方所有"},{"q":"五积散的主治证是","o":["外寒内饮证","表证未解，邪热入里证","邪热壅肺证","湿热痢疾","外感风寒，内伤生冷证"],"a":4,"e":"五积散表里双解，外散风寒、内温里寒，兼祛湿、消食、理气、活血，消散寒、湿、气、血、食五积，主治外感风寒、内伤生冷之证。外寒内饮为小青龙汤所主，表证未解邪热入里是葛根芩连汤之类，邪热壅肺属麻杏石甘汤，湿热痢疾用白头翁汤，A、B、C、D项各有专方，E项符合本方表里同治之旨"},{"q":"防风通圣散的主治证是","o":["外感风寒表实证","外寒内饮证","邪热雍肺证","协热下利","风热壅盛，表里俱实证"],"a":4,"e":"防风通圣散防风、荆芥、薄荷疏风解表，大黄、芒硝、栀子、黄芩等泻热通腑、清热利湿，表里双解、汗下并用，主治风热壅盛、表里俱实之证。外感风寒表实宜麻黄汤，外寒内饮宜小青龙汤，邪热壅肺宜麻杏石甘汤，协热下利属葛根芩连汤，A、B、C、D项均非防风通圣散表里俱实、上下分消之主治，E项准确"},{"q":"肾气丸和右归丸共有的药是","o":["枸杞子","杜仲","薯蓣","泽泻","鹿角胶"],"a":2,"e":"肾气丸（金匮肾气丸）以干地黄、薯蓣、山茱萸滋补肾阴，配桂枝、附子温阳化气，寓少火生气之意；右归丸温补肾阳、填精益髓，亦用熟地黄、山药、山茱萸、附子等。两方共有的药物为薯蓣（即山药）。枸杞子、杜仲、鹿角胶仅见于右归丸，泽泻为肾气丸三泻之一、右归丸不用，A、B、D、E项非共有，C项符合"},{"q":"阿胶鸡子黄汤的功用是","o":["滋阴复脉，潜阳息风","平肝息风，补益肝肾","镇肝息风，滋阴潜阳","滋阴养血，柔肝息风","凉肝息风，增液舒筋"],"a":3,"e":"阿胶鸡子黄汤以阿胶、鸡子黄、生地、白芍滋阴养血，钩藤、牡蛎、石决明、茯神、络石藤、甘草柔肝息风、宁心安神，功用为滋阴养血、柔肝息风，主治阴虚血少、虚风内动。镇肝息风、滋阴潜阳是镇肝熄风汤；凉肝息风、增液舒筋属羚角钩藤汤；平肝息风、补益肝肾偏杞菊地黄类；滋阴复脉近炙甘草汤，A、B、C、E项各归他方"},{"q":"下述选项中不属于凉开剂的是","o":["安宫牛黄丸","紫雪","至宝丹","抱龙丸","紫金锭"],"a":4,"e":"凉开剂以牛黄、冰片、麝香等芳香清热开窍药为主，安宫牛黄丸、紫雪、至宝丹并称凉开三宝，抱龙丸亦清热化痰、凉肝镇惊，属凉开之列。紫金锭（玉枢丹）由山慈菇、红芽大戟、千金子、麝香、雄黄等组成，辟秽解毒、化痰散结，性偏温燥，归温开剂，非凉开，E项符合题干要求，A、B、C、D均为凉开代表方"},{"q":"下列各项中，均属于完带汤药物组成的是","o":["人参、白术、茯苓","柴胡、枳壳、白芍","苍术、荆芥穗、山药","车前子、柴胡、木香","党参、苍术、白术"],"a":2,"e":"完带汤白术、山药健脾益气、固摄带脉为君，苍术燥湿健脾，荆芥穗疏风胜湿，与陈皮、柴胡、白芍、车前子等共奏健脾疏肝、化湿止带之功，主治脾虚肝郁、湿浊下注之白带。茯苓非本方药物，枳壳、木香未见，党参虽可代人参但原方用人参，A、B、D、E项所列均含非本方药，C项三味均属原方组成"},{"q":"远志、菖蒲、茯神并用的方是","o":["归脾汤","天王补心丹","酸枣仁汤","桑螵蛸散","金锁固精丸"],"a":3,"e":"桑螵蛸散桑螵蛸补肾固精、缩尿为君，龙骨、龟甲滋阴潜阳、固涩，人参、当归益气养血，茯神、远志、菖蒲宁心安神、开窍交通心肾，主治心肾两虚之尿频、遗尿、遗精。归脾汤、天王补心丹虽用远志、茯神，但无菖蒲配伍；酸枣仁汤主虚烦不眠，金锁固精丸专固肾涩精，均无此三药同用，A、B、C、E项排除"},{"q":"乌梅在二陈汤中的配伍意义是","o":["涩肠止泻","收敛止血","安蛔止痛","生津止渴","收敛肺气"],"a":4,"e":"二陈汤半夏、橘红燥湿化痰、理气和中，茯苓健脾渗湿，甘草和中，生姜制半夏之毒并助化痰，少佐乌梅收敛肺气，与半夏之燥散相制，使燥湿化痰而不耗伤肺气，专为咳嗽痰多而设。涩肠止泻、收敛止血、安蛔止痛、生津止渴虽皆乌梅之功，但非本方配伍意图，A、B、C、D项不合，E项准确"},{"q":"大补阴丸的主治证是","o":["肾之阴阳两虚证","肾阳不足证","真阴不足证","肝肾阴虚证","阴虚火旺证"],"a":4,"e":"大补阴丸熟地黄、龟板滋阴填精、潜阳，知母、黄柏清泻相火，猪脊髓、蜂蜜滋阴润燥，主治阴虚火旺之骨蒸潮热、盗汗遗精、咳嗽咯血、心烦易怒。肾阴阳两虚宜地黄饮子，肾阳不足宜右归丸，真阴不足宜左归丸，肝肾阴虚偏一贯煎、杞菊地黄丸，A、B、C、D项病机各有对应方，E项与大补阴丸滋阴降火之旨相合"},{"q":"痛泻要方的君药是","o":["防风","白术","陈皮","白芍","黄芪"],"a":1,"e":"痛泻要方白术苦甘温，健脾燥湿、固中州以御肝木之乘，为君药；白芍养血柔肝、缓急止痛为臣，陈皮理气醒脾，防风疏肝解郁、升阳胜湿，共治脾虚肝郁之痛泻。防风为臣佐而非君，陈皮理气、白芍柔肝亦非主药；黄芪益气升提，本方不用，A、C、D、E项均非君药，B项白术切合扶土抑木之制方主旨"},{"q":"猪苓汤组成中润燥且滋阴的药物是","o":["阿胶","茯苓","玄参","生地","麦冬"],"a":0,"e":"猪苓汤猪苓、茯苓、泽泻利水渗湿，滑石清热利水通淋，阿胶滋阴润燥、养血止血，既防利水伤阴，又润泽燥象，主治水热互结、邪热伤阴之小便不利、发热口渴。玄参、生地、麦冬虽皆滋阴，但均非本方药物；茯苓、猪苓专于利水渗湿，无滋阴润燥之能，B、C、D、E项排除，A项阿胶为方中唯一滋阴润燥之品"},{"q":"三子养亲汤的功用是","o":["温肺化痰，降气消食","温肺化饮，降气平喘","温肺化痰，利气畅膈","降气消痰，止咳平喘","消食导滞，降气祛痰"],"a":0,"e":"三子养亲汤紫苏子降气化痰、止咳平喘，白芥子温肺化痰、利气散结，莱菔子消食导滞、降气化痰，三药皆属种子类，降气为主，共奏温肺化痰、降气消食之功，主治痰壅气逆食滞之咳嗽喘逆、痰多胸痞。温肺化饮、降气平喘偏小青龙汤、苏子降气汤；降气消痰、止咳平喘为苏子降气汤；消食导滞非本方主功，B、C、D、E项不确切，A项完整概括本方功用"},{"q":"大柴胡汤的主治证是","o":["少阳证","阳明证","太阳证","少阳阳明合病","三阳经合病"],"a":3,"e":"大柴胡汤小柴胡汤去人参、甘草，加枳实、大黄、芍药，和解少阳与内泻热结并行，主治少阳阳明合病，见往来寒热、胸胁苦满、呕不止、心下痞硬、大便不解。单纯少阳证宜小柴胡汤，阳明证宜承气汤，太阳证宜麻黄汤、桂枝汤，三阳合病另有所主，A、B、C、E项均偏执一经，D项体现本方表里双解、两经并治之特点"},{"q":"旋覆代赭汤中原方旋覆花与代赭石的用量比例是","o":["1∶1","1∶2","1∶3","3∶1","3∶2"],"a":3,"e":"旋覆代赭汤原方旋覆花三两、代赭石一两，用量之比为3∶1。旋覆花重用消痰下气、软坚散结以降逆，代赭石量轻取其重镇降逆而不伤胃气，配人参、甘草、大枣益气和胃，生姜、半夏化痰降逆，共治胃虚痰阻气逆之噫气不除。比例1∶1、1∶2、1∶3与3∶2均不合原方用量，A、B、C、E项排除，D项即原方三两与一两之比"},{"q":"橘皮竹茹汤的功效是","o":["降逆止呃，益气清热","养阴补肺，清热止血","和胃止呕，散饮降逆","回阳救急，益气生脉","温中散寒，养血通脉"],"a":0,"e":"橘皮竹茹汤橘皮、竹茹清胃热、降逆止呃，人参、甘草、大枣益气补虚和中，生姜和胃降逆，主治胃虚有热之呃逆，功效为降逆止呃、益气清热。养阴补肺、清热止血是百合固金汤类；和胃止呕、散饮降逆偏小半夏汤、生姜泻心汤；回阳救急、益气生脉属参附汤；温中散寒、养血通脉为当归四逆汤，B、C、D、E项各归他方，A项符合本方虚实兼顾之制"},{"q":"温脾汤中用量最大的药物是","o":["当归","人参","大黄","附子","芒硝"],"a":2,"e":"温脾汤温补脾阳、攻下冷积，原方大黄用量最重，配合芒硝泻下软坚，附子、干姜温阳散寒，人参、当归、甘草益气养血和中，寓温补于攻下之中，主治脾阳不足、冷积内停之便秘腹痛。附子、干姜温中但量次于大黄，人参、当归补益气血亦非主药，芒硝助泻而用量较轻，A、B、D、E项均非用量最大者，C项大黄体现温下主攻之力"},{"q":"以下关于小活络丹的辨证要点描述错误的是","o":["腰膝酸软无力","肢体筋脉挛痛","关节屈伸不利","舌质淡紫","舌苔白"],"a":0,"e":"小活络丹川乌、草乌温经散寒止痛，天南星化痰燥湿，地龙通经活络，乳香、没药活血止痛，主治风寒湿痹、痰瘀阻络，辨证以肢体筋脉挛痛、关节屈伸不利、舌质淡紫、舌苔白为要点。腰膝酸软无力提示肝肾不足、筋骨失养，多见于独活寄生汤证，非本方风寒湿痰瘀实证所见，A项描述错误，B、C、D、E项均为本方主证"},{"q":"桃核承气汤的组成含有","o":["大承气汤","小承气汤","调胃承气汤","增液承气汤","复方大承气汤"],"a":2,"e":"桃核承气汤由桃仁、大黄、桂枝、甘草、芒硝组成，其中大黄、芒硝、甘草即调胃承气汤，再加桃仁活血破瘀、桂枝通行血脉，共奏逐瘀泻热之功，主治下焦蓄血证。大承气汤另含枳实、厚朴，小承气汤无芒硝，增液承气汤伍生地、麦冬、玄参，复方大承气汤为后世加减方，A、B、D、E项均非桃核承气汤所含，C项准确"},{"q":"配伍体现酸苦辛并进的方剂是","o":["酸枣仁汤","半夏泻心汤","乌梅丸","平胃散","黄连解毒汤"],"a":2,"e":"乌梅丸重用乌梅酸收涩肠、安蛔，黄连、黄柏苦寒清热燥湿，附子、桂枝、干姜、细辛、蜀椒辛温散寒，酸苦辛并进、寒热并用、邪正兼顾，主治蛔厥及久利，为治蛔之主方。半夏泻心汤辛开苦降、寒热平调，重在和胃消痞；酸枣仁汤养血安神、清热除烦；平胃散燥湿运脾；黄连解毒汤纯苦寒泻火，均无酸苦辛三味并进之法，A、B、D、E项不合，C项符合"},{"q":"真人养脏汤的组成中有","o":["诃子、乌梅","诃子、罂粟壳","诃子、五倍子","诃子、山萸肉","诃子、赤石脂"],"a":1,"e":"真人养脏汤罂粟壳涩肠止泻为君，诃子、肉豆蔻助涩肠固脱，肉桂温肾暖脾，人参、白术、甘草益气健脾，当归、白芍养血和血，木香行气止痛，共治脾肾虚寒、久泻久痢。乌梅、五倍子、山萸肉、赤石脂虽皆收涩，但均非本方组成，A、C、D、E项所列药物不全属原方，B项诃子、罂粟壳同见于真人养脏汤"},{"q":"犀角地黄汤的主治证是","o":["热入营分证","热入血分证","气分热盛证","三焦火热证","气血两燔证"],"a":1,"e":"犀角地黄汤水牛角、生地清热凉血解毒，芍药、丹皮凉血散瘀，主治热入血分，见吐血、衄血、便血、尿血、斑疹紫黑、神昏谵语等，功用清热解毒、凉血散瘀。热入营分宜清营汤，气分热盛宜白虎汤，三焦火热宜黄连解毒汤，气血两燔宜清瘟败毒饮，A、C、D、E项病机层次各不相同，B项切合本方凉血散血之主治"},{"q":"贝母瓜蒌散之功用是","o":["润肺清热，理气化痰","清热化痰，宽胸散结","温肺散寒，涤痰化饮","燥湿化痰，平肝熄风","荡涤实热，攻逐顽痰"],"a":0,"e":"贝母瓜蒌散贝母、瓜蒌润肺清热、化痰散结，天花粉润燥生津，茯苓健脾渗湿，橘红理气化痰，桔梗宣肺利气，共奏润肺清热、理气化痰之功，主治肺燥有痰之咳嗽痰少、咯吐不爽。清热化痰、宽胸散结为小陷胸汤；温肺散寒、涤痰化饮属苓甘五味姜辛汤；燥湿化痰、平肝熄风非本方；荡涤实热、攻逐顽痰为滚痰丸，B、C、D、E项不合，A项准确"},{"q":"大补阴丸的功用是","o":["滋阴补肾","滋阴疏肝","滋阴降火","滋阴补肺，清热止血","滋阴补肾，填精益髓"],"a":2,"e":"大补阴丸熟地黄、龟板滋阴填精、潜阳制火，知母、黄柏清泻肾中相火，猪脊髓、蜂蜜滋润，功用为滋阴降火，专治阴虚火旺之骨蒸潮热、盗汗、遗精。单纯滋阴补肾是六味地黄丸；滋阴疏肝属一贯煎；滋阴补肺、清热止血是百合固金汤；滋阴补肾、填精益髓偏左归丸、右归丸，A、B、D、E项各有对应方，C项体现本方滋阴与降火并行之制方特点"},{"q":"具有“益气解表，理气化痰”功用的方剂是","o":["败毒散","参苏饮","麻黄附子细辛汤","再造散","加减葳蕤汤"],"a":1,"e":"参苏饮人参、甘草、茯苓益气健脾，紫苏叶、葛根解表散邪，半夏、前胡、陈皮、枳壳、桔梗理气化痰、宣降肺气，主治气虚外感风寒、内有痰湿之证，功用益气解表、理气化痰。败毒散益气解表、散风祛湿，无化痰之功；麻黄附子细辛汤助阳解表；再造散助阳益气、解表散寒；加减葳蕤汤滋阴解表，A、C、D、E项均不具理气化痰之能，B项符合"},{"q":"防己黄芪汤与五苓散共同的药物是","o":["茯苓","猪苓","白术","泽泻","甘草"],"a":2,"e":"防己黄芪汤防己祛风利水，黄芪益气固表，白术健脾燥湿，甘草、姜、枣调和，功益气祛风、健脾利水；五苓散猪苓、茯苓、泽泻、白术、桂枝利水渗湿、温阳化气。两方共有药物为白术，均取其健脾燥湿以助利水。茯苓、猪苓、泽泻仅见于五苓散，甘草虽在防己黄芪汤中但五苓散原方无甘草，A、B、D、E项排除，C项符合"},{"q":"生脉散证的病机特点是","o":["肺肾不足，阴虚火旺","温热暑邪，气阴耗伤","肺肾虚衰，气逆不降","津伤气耗，虚火内盛","风热犯肺，肺失肃降"],"a":1,"e":"生脉散人参补气生津，麦冬养阴清热，五味子敛肺止汗、生津，三药合用益气养阴、敛汗生脉，主治温热暑邪或久咳耗伤气阴之体倦气短、咽干口渴、脉虚数。肺肾不足、阴虚火旺属知柏地黄丸类；肺肾虚衰、气逆不降为苏子降气汤、都气丸类；津伤气耗兼虚火内盛偏竹叶石膏汤；风热犯肺宜桑菊饮，A、C、D、E项病机不合，B项切中气阴两伤之核心"},{"q":"主治“风温初起，邪客肺络证”的方剂是","o":["麻黄杏仁甘草石膏汤","香薷散","银翘散","香苏散","桑菊饮"],"a":4,"e":"桑菊饮桑叶、菊花轻宣肺气、疏风清热，杏仁、桔梗宣肺止咳，连翘、薄荷辛凉透邪，芦根清热生津，甘草调和，主治风温初起、邪客肺络之咳嗽、身热不甚、口微渴，功擅疏风清热、宣肺止咳。麻杏石甘汤清泻肺热，主邪热壅肺喘咳；香薷散祛暑解表；银翘散辛凉透表，主治风温初起发热重、咽痛；香苏散疏肝理气解表，A、B、C、D项各有主证，E项符合邪客肺络之轻证"},{"q":"消风散的主治证是","o":["风寒湿","破伤风","类中风","风疹","风湿热"],"a":3,"e":"消风散荆芥、防风、牛蒡子、蝉蜕疏风止痒，苍术、苦参、黄柏清热燥湿，当归、生地、胡麻仁养血活血、滋阴润燥，石膏、知母清热，甘草调和，主治风湿浸淫血脉所致风疹、湿疹，见皮肤瘙痒、疹出色红。风寒湿痹宜羌活胜湿汤；破伤风宜玉真散；类中风宜镇肝熄风汤；风湿热痹宜白虎加苍术汤，A、B、C、E项各有专方，D项符合本方疏风养血、清热除湿之主治"},{"q":"小蓟饮子的药物组成含有何方","o":["碧玉散","鸡苏散","四生丸","六一散","五苓散"],"a":3,"e":"小蓟饮子小蓟、藕节、蒲黄凉血止血，生地、当归、栀子、竹叶、滑石、甘草、木通等清热利水、养血和血，其中滑石、甘草即六一散，清热利水通淋，主治热结下焦之血淋、尿血。碧玉散为六一散加青黛，鸡苏散加薄荷，四生丸为生地、艾叶、荷叶、柏叶，五苓散利水渗湿温阳，均非小蓟饮子所含，A、B、C、E项排除，D项准确"},{"q":"玉屏风散主治","o":["营卫失调，恶风自汗","表虚自汗，易感风邪","阴虚火旺，汗液外泄","诸虚不足，自汗盗汗","暑热耗气，短气自汗"],"a":1,"e":"玉屏风散黄芪益气固表止汗为君，白术健脾益气、固表为臣，防风走表祛风，与黄芪相伍散中寓补、补中寓疏，使气旺表实、邪不易侵，主治表虚自汗、易感风邪。营卫失调、恶风自汗宜桂枝汤；阴虚火旺、汗液外泄宜当归六黄汤；诸虚不足、自汗盗汗宜牡蛎散；暑热耗气、短气自汗宜生脉散，A、C、D、E项病机有别，B项符合本方益气固表止汗之主治"},{"q":"下列各项中，属于实脾散功用的是","o":["温阳利水","温阳健脾，行气利水","温阳化饮，健脾利水","利水消肿，理气健脾","温阳化气，利水渗湿"],"a":1,"e":"实脾散附子、干姜温阳散寒，白术、茯苓、甘草健脾渗湿，厚朴、木香、槟榔、草果行气导滞，木瓜利水，生姜、大枣调和，功用温阳健脾、行气利水，主治脾肾阳虚、水气内停之阴水。单纯温阳利水偏真武汤；温阳化饮、健脾利水为苓桂术甘汤；利水消肿、理气健脾是五皮散；温阳化气、利水渗湿属五苓散，A、C、D、E项各有侧重，B项完整体现本方温阳与行气并重之法"},{"q":"逍遥散中具有“疏散郁遏之气，透达肝经郁热”作用的药物是","o":["当归","白芍","生姜","薄荷","柴胡"],"a":3,"e":"逍遥散柴胡疏肝解郁、条达肝气为君，当归、白芍养血柔肝为臣，白术、茯苓、甘草健脾益气，生姜温胃和中，少许薄荷辛凉，疏散郁遏之气、透达肝经郁热，助柴胡条达肝木而清郁热。当归、白芍功在养血柔肝，生姜温中和胃，柴胡虽疏肝但无透达郁热之能，A、B、C、E项各司其职，D项薄荷的辛凉透散正合题干所述"},{"q":"朱砂安神丸与天王补心丹组成中共有的药物为","o":["生地","玄参","柏子仁","桔梗","以上都不正确"],"a":0,"e":"朱砂安神丸朱砂重镇安神，黄连清心泻火，生地黄、当归滋阴养血，甘草调和，主治心火亢盛、阴血不足之神烦失眠；天王补心丹滋阴养血、补心安神，亦用生地黄、当归、朱砂。两方共有的药物为生地黄。玄参、柏子仁、桔梗仅见于天王补心丹，朱砂安神丸无此三味，B、C、D项非共有，E项以上都不正确不成立，A项生地为两方共有之品"},{"q":"大补阴丸的君药是","o":["熟地黄","龟板","熟地黄、龟板","知母、黄柏","黄柏"],"a":2,"e":"大补阴丸熟地黄滋阴填精、大补真阴，龟板滋阴潜阳、益肾健骨，二者相须为君，滋肾阴以制相火；知母、黄柏清泻肾中虚火为臣，猪脊髓、蜂蜜滋润为使，共奏滋阴降火之功。知母、黄柏清火但为臣药，单用熟地或龟板未能体现相须为君之制，D、E项偏泻火，A、B项各举其一，C项二者合为君药，符合本方滋阴为主、降火为辅的配伍"},{"q":"归脾汤组成中有","o":["当归","阿胶","干地黄","白芍药","川芎"],"a":0,"e":"归脾汤人参、黄芪、白术、甘草益气健脾，当归、龙眼肉养血安神，茯苓、远志、酸枣仁宁心安神，木香理气醒脾，姜、枣调和，主治心脾气血两虚及脾不统血之证。阿胶、干地黄、白芍药、川芎虽多见于四物汤、炙甘草汤等，但均非归脾汤原方药物，B、C、D、E项排除，A项当归为方中养血和血、宁心安神之要药，体现气血双补之制"},{"q":"被柯琴称为“治癫痫之圣剂”的是","o":["朱砂安神丸","磁朱丸","珍珠母丸","交泰丸","以上都不正确"],"a":1,"e":"磁朱丸磁石、朱砂、神曲组成，重镇安神、潜阳明目，柯琴赞其为治癫痫之圣剂，主治癫痫、心悸失眠、耳鸣目昏。朱砂安神丸清心安神，主心火亢盛之失眠；珍珠母丸滋阴养血、重镇安神，主肝阳上亢之心神不宁；交泰丸交通心肾治失眠；以上都不正确不成立，A、C、D、E项不合，B项磁朱丸即柯琴所誉之方"},{"q":"集凉血、止血、清降祛瘀诸法于一方的方剂是","o":["龙胆泻肝汤","咳血方","百合固金汤","黄土汤","十灰散"],"a":4,"e":"十灰散大蓟、小蓟、荷叶、侧柏叶、白茅根、茜草、栀子、大黄、牡丹皮、棕榈皮十味烧灰存性，凉血止血、清降祛瘀，诸药炒炭具收敛止血之性，又清血分之热、降上炎之火并祛瘀，主治血热妄行之吐血、咯血。龙胆泻肝汤清肝胆实火、利湿热；咳血方清肝宁肺、凉血止血；百合固金汤滋阴润肺；黄土汤温阳健脾、养血止血，A、B、C、D项治法各偏，E项集四法于一身"},{"q":"何方以滋阴填精，益气壮阳为功","o":["六味地黄丸","龟鹿二仙胶","十补丸","七宝美髯丹","肾气丸"],"a":1,"e":"龟鹿二仙胶龟板滋阴填精、鹿角胶温阳益精，二者一阴一阳、峻补精髓，人参、枸杞子益气养阴、补肝肾，共奏滋阴填精、益气壮阳之功，主治真元虚损、精血不足之腰膝酸软、遗精、不孕。六味地黄丸滋补肾阴，十补丸温补肾阳兼滋阴，七宝美髯丹补肝肾、益精血，肾气丸温阳化气，A、C、D、E项功效各有侧重，B项完整概括本方阴阳并补之特点"},{"q":"参苓白术散的主治病证是","o":["脾虚夹湿","脾胃气虚","气虚下陷","气虚发热","脾肾两虚"],"a":0,"e":"参苓白术散四君子汤加山药、莲子肉、白扁豆、薏苡仁、砂仁、桔梗，益气健脾、渗湿止泻，主治脾虚夹湿之饮食不化、胸脘痞闷、肠鸣泄泻、四肢乏力。单纯脾胃气虚宜四君子汤；气虚下陷宜补中益气汤；气虚发热宜补中益气汤或升阳益胃汤；脾肾两虚宜附子理中汤、四神丸，B、C、D、E项病机有别，A项体现本方健脾与祛湿并行之主治"},{"q":"具有益气生津，润燥止渴功用的方剂是","o":["麦门冬汤","生脉散","清燥救肺汤","玉液汤","琼玉膏"],"a":3,"e":"玉液汤黄芪、山药益气健脾、生津，知母、天花粉、葛根清热滋阴、生津止渴，鸡内金、五味子助消化、敛津，主治气阴不足之消渴，功用益气生津、润燥止渴。麦门冬汤养阴润肺、降逆下气；生脉散益气养阴、敛汗生脉；清燥救肺汤清燥润肺、养阴益气；琼玉膏滋阴润肺、益气补中，A、B、C、E项各有专主，D项切合本方益气生津治消渴之特点"},{"q":"四逆汤与当归四逆汤二方组成中均含有的药物","o":["附子","桂枝","当归","甘草","干姜"],"a":3,"e":"四逆汤附子、干姜、炙甘草回阳救逆，主治心肾阳衰之厥逆；当归四逆汤当归、桂枝、芍药、细辛、通草、大枣、炙甘草温经散寒、养血通脉，主治血虚寒厥。两方均用炙甘草调和诸药、益气和中，为共有药物。附子、干姜仅见于四逆汤，桂枝、当归仅见于当归四逆汤，A、B、C、E项均非共有，D项甘草即两方同用之品"},{"q":"定痫丸中的君药是","o":["竹沥、胆南星","天麻、半夏","竹沥、天麻","胆南星、半夏","全蝎、胆南星"],"a":0,"e":"定痫丸竹沥、胆南星清热化痰、开窍定痫，针对痫证痰热阻窍之核心病机而为君药；天麻、全蝎、僵蚕平肝息风止痉，半夏、川贝母、茯苓、陈皮等化痰，石菖蒲、远志、茯神开窍宁心，辰砂、琥珀镇惊安神。天麻、半夏、全蝎等或为臣佐，或重在息风镇惊，均非君药，B、C、D、E项所列各有侧重，A项竹沥、胆南星直清痰热开窍，符合本方主痫之制"},{"q":"四物汤和当归补血汤共有的药是","o":["干地黄","黄芪","川芎","芍药","当归"],"a":4,"e":"四物汤熟地黄、当归、白芍、川芎养血活血，为补血调经基础方；当归补血汤重用黄芪大补元气以生血，配当归养血和营，主治血虚发热。两方共有的药物为当归，均取其补血和血之功。干地黄、川芎、芍药仅见于四物汤，黄芪为当归补血汤主药而四物汤不用，A、C、D、B项排除，E项当归切合两方养血之共同取向"},{"q":"四君子汤的主治病证为","o":["脾胃虚寒证","湿邪困脾证","脾胃气虚证","脾阳不足证","脾虚泄泻证"],"a":2,"e":"四君子汤人参、白术、茯苓、炙甘草益气健脾，主治脾胃气虚之面色萎黄、语声低微、四肢乏力、食少便溏，为补气基础方。脾胃虚寒宜理中丸、附子理中汤；湿邪困脾宜平胃散；脾阳不足宜实脾散、附子理中丸；脾虚泄泻宜参苓白术散，A、B、D、E项各有对应方，C项脾胃气虚正是四君子汤补益中气之主治，亦为后续补气方之基础"},{"q":"保和丸中清热散结的药物是","o":["神曲","莱菔子","栀子","连翘","连翘、莱菔子"],"a":3,"e":"保和丸山楂、神曲、莱菔子消食化积，半夏、陈皮、茯苓理气化痰、和胃，连翘苦微寒，清热散结，针对食积郁而化热之象，为佐药。神曲消食和胃，莱菔子消食降气，均无清热之能；栀子虽清热但不属本方，E项连翘、莱菔子并列亦不准确，A、B、C、E项排除，D项连翘体现本方消食兼清郁热之配伍"},{"q":"四物汤与归脾汤共有的药是","o":["当归","人参","酸枣仁","白芍药","甘草"],"a":0,"e":"四物汤熟地黄、当归、白芍、川芎补血调血；归脾汤人参、黄芪、白术、当归、龙眼肉、酸枣仁、茯苓、远志、木香、甘草等益气补血、健脾养心。两方共有药物为当归，均用于养血和血。人参、酸枣仁仅见于归脾汤，白芍药为四物汤所有而归脾汤不用，甘草虽在归脾汤但四物汤无，B、C、D、E项非共有，A项符合"},{"q":"大补阴丸与左归丸的共有药物是","o":["猪脊髓","熟地黄","山药","鹿角胶","菟丝子"],"a":1,"e":"大补阴丸熟地黄、龟板、知母、黄柏、猪脊髓滋阴降火；左归丸熟地黄、山药、山茱萸、菟丝子、鹿角胶、龟板胶、牛膝、枸杞子滋阴补肾、填精益髓。两方共有熟地黄、龟板之类，选项中熟地黄为共有且为君药。猪脊髓仅大补阴丸有，山药、鹿角胶、菟丝子仅左归丸有，A、C、D、E项非共有，B项熟地黄符合"},{"q":"二陈汤组成中含有","o":["半夏、橘红、生姜、大枣","半夏、橘红、生姜、乌梅","半夏、橘红、炙甘草、大枣","半夏、橘红、生姜、五味子","半夏、橘红、白术、茯苓"],"a":1,"e":"二陈汤由半夏、橘红、茯苓、炙甘草、生姜、乌梅组成，燥湿化痰、理气和中，为治痰基础方。方中半夏、橘红各陈久者良，故名二陈；生姜制半夏毒并助化痰，乌梅收敛肺气，与燥药相制。大枣非本方药物，炙甘草不可或缺，白术、五味子亦不在原方，A、C、D、E项所列均含非二陈汤之品，B项准确列出半夏、橘红、生姜、乌梅"},{"q":"四逆汤与下列哪一个方剂所用药物相同","o":["通脉四逆汤","四逆散","白通汤","参附汤","当归四逆汤"],"a":0,"e":"通脉四逆汤即四逆汤加重附子、干姜用量而成，药物组成仍为附子、干姜、炙甘草，主治阴盛格阳之证，故与四逆汤用药相同而分量有别。四逆散为柴胡、枳实、芍药、甘草，白通汤为附子、干姜、葱白，参附汤为人参、附子，当归四逆汤含当归、桂枝、芍药、细辛、通草、大枣，均非同方，B、C、D、E项排除，A项通脉四逆汤符合"},{"q":"以下除哪项外，均是清暑益气汤的辨证要点","o":["身热汗多","口渴心烦","体倦少气","腹痛吐泻","脉虚数"],"a":3,"e":"清暑益气汤西洋参、石斛、麦冬等益气养阴，西瓜翠衣、荷梗、黄连、知母等清热解暑，主治暑热气津两伤，辨证以身热汗多、口渴心烦、体倦少气、脉虚数为要点。腹痛吐泻为外感风寒、内伤湿滞之藿香正气散证，非本方所主，D项不属于其辨证要点；A、B、C、E四项均体现暑热伤气伤津之象，符合题干除哪项外之问"},{"q":"以下不属于安宫牛黄丸主治证的是","o":["高热烦躁","神昏谵语","小儿惊厥","舌红绛","脉迟"],"a":4,"e":"安宫牛黄丸牛黄、麝香、冰片、水牛角、黄连、黄芩、栀子等清热解毒、开窍醒神，主治热闭心包之高热烦躁、神昏谵语、小儿惊厥、舌红绛、脉数。脉迟主寒证、里寒或阳虚，与热闭之病机相反，非本方主治所见，E项符合题干否定式提问；A、B、C、D均为邪热内陷心包之典型表现，属安宫牛黄丸适应证"},{"q":"越鞠丸所治郁证的成因包括","o":["风、寒、暑、湿、燥、火","风、寒、痰、湿、燥、食","气、血、痰、火、食、湿","气、血、痰、热、食、湿","气、血、痰、火、暑、燥"],"a":2,"e":"越鞠丸香附行气、川芎活血、栀子清火、苍术燥湿、神曲消食，统治气、血、痰、火、食、湿六郁，其中气郁为主，诸郁多由气机郁滞而致，故以香附为君。A项六淫、B项风寒痰湿、E项暑燥均非六郁内容；D项以热代火，与越鞠丸原旨火郁不符，A、B、D、E项排除，C项准确概括六郁成因"},{"q":"镇肝熄风汤的主治证是","o":["风痰上扰证","肝风上扰证","阴虚风动证","肝热生风证","类中风"],"a":4,"e":"镇肝熄风汤怀牛膝引血下行、补益肝肾为君，代赭石、龙骨、牡蛎、龟板重镇降逆、滋阴潜阳，白芍、玄参、天冬滋阴柔肝，川楝子、茵陈、麦芽疏肝泄热，主治肝肾阴虚、肝阳上亢、气血逆乱之类中风，见头目眩晕、脑部热痛、面色如醉、肢体渐觉不利。风痰上扰宜半夏白术天麻汤，肝热生风宜羚角钩藤汤，阴虚风动宜大定风珠，A、C、D项病机有别，E项符合本方镇肝潜阳、引血下行之主治"},{"q":"体现“苦寒直折”治法的方剂是","o":["白虎汤","清营汤","犀角地黄汤","普济消毒饮","黄连解毒汤"],"a":4,"e":"黄连解毒汤黄连、黄芩、黄柏、栀子四味皆大苦大寒，直折三焦火毒，使火热清解而无留邪，主治三焦火毒热盛之发热烦躁、口燥咽干、吐血发斑，为苦寒直折治法之代表。白虎汤辛寒清热生津，清营汤清营透热，犀角地黄汤凉血散瘀，普济消毒饮疏散风热、清热解毒，A、B、C、D项治法各异，E项体现苦寒药直接清泻实火之特点"},{"q":"复元活血汤中配伍瓜蒌根的用意是","o":["消瘀散结、清热消肿","清热散结、生津止渴","消肿泻火排脓","活血化瘀、行气解郁","祛瘀通经、并退虚热"],"a":0,"e":"复元活血汤柴胡、天花粉（瓜蒌根）、当归、红花、甘草、穿山甲、大黄、桃仁活血祛瘀、疏肝通络，其中瓜蒌根既能入血分助消瘀散结，又清热消肿，针对跌打损伤、瘀血留于胁下之肿痛。生津止渴虽为瓜蒌根之功，但非本方配伍意图；消肿泻火排脓偏薏苡附子败酱散；活血行气解郁为柴胡、香附；祛瘀通经退虚热非其所主，B、C、D、E项不合，A项准确"},{"q":"养阴清肺汤的君药是","o":["麦冬","丹皮","生地","玄参","白芍"],"a":2,"e":"养阴清肺汤生地黄滋阴清热、凉血解毒为君药，麦冬、玄参、白芍养阴润肺、清热利咽，贝母润肺化痰，丹皮凉血，薄荷疏风利咽，甘草调和，主治白喉之阴虚燥热、咽喉肿痛。麦冬虽养阴但为臣，丹皮凉血、玄参利咽、白芍养血柔肝，均非君药，A、B、D、E项各有分工，C项生地体现本方养阴清肺、凉血解毒之主药地位"},{"q":"定喘汤中配伍白果的意义是","o":["敛肺定喘而祛痰","宣肺散邪以平喘","清泻肺热，止咳平喘、调和诸药","清热化痰","燥湿化痰"],"a":0,"e":"定喘汤麻黄宣肺散邪、止咳平喘，白果敛肺定喘、祛痰，二药一宣一敛，既增强平喘之效，又防麻黄过散耗气，配苏子、半夏、杏仁、桑白皮、黄芩、甘草等降气清热化痰，主治风寒外束、痰热内蕴之哮喘。宣肺散邪以平喘是麻黄之功；清泻肺热、止咳平喘、调和诸药指桑白皮、黄芩、甘草；清热化痰、燥湿化痰分别为黄芩、半夏，B、C、D、E项各归其药，A项符合白果在本方之配伍"},{"q":"不属于玉女煎的主治证候是","o":["头痛","牙痛","消渴","肺痿","舌红苔黄而干"],"a":3,"e":"玉女煎石膏、知母清胃热，熟地黄、麦冬、牛膝滋阴降火、引热下行，主治胃热阴虚之头痛、牙痛、消渴、舌红苔黄而干。肺痿为肺阴亏虚、肺叶萎弱，见咳吐浊唾涎沫，宜麦门冬汤、百合固金汤类，非胃热阴虚之玉女煎所主，D项符合否定式提问；A、B、C、E均属胃热伤阴之象，为本方主治证候"},{"q":"下列各项中，属于完带汤主治症状的是","o":["带下色白","有异味","质黏稠","舌红苔少","脉细数"],"a":0,"e":"完带汤白术、山药健脾益气、固摄带脉，苍术、陈皮、荆芥穗、车前子燥湿理气、化湿止带，白芍、柴胡柔肝疏肝，甘草和中，主治脾虚肝郁、湿浊下注之带下色白或淡黄、质清稀无臭、面色萎黄。带下有异味、质黏稠多属湿热下注（如易黄汤证），舌红苔少、脉细数为阴虚之象，B、C、D、E项与完带汤脾虚湿浊之证不符，A项带下色白为其典型表现"},{"q":"以下关于牵正散的药物组成描述正确的是","o":["蜈蚣、全蝎、白僵蚕","全蝎、白僵蚕、黑附子","蜈蚣、白僵蚕、黑附子","全蝎、白僵蚕、白附子","蜈蚣、全蝎、白附子"],"a":3,"e":"牵正散由白附子、白僵蚕、全蝎三味等分为末，热酒调服，白附子祛头面风痰、通络为君，白僵蚕祛风通络、化痰散结，全蝎搜风通络、止痉，共治风痰阻络之口眼歪斜。方中并无蜈蚣，亦无黑附子、黑僵蚕，A、B、C、E项所列均含原方所无之品，D项三味准确对应牵正散的药物组成，体现祛风痰、通经络之配伍"},{"q":"大承气汤的功用是","o":["攻下冷积","峻下热结","润肠通便","轻下热结","缓下热结"],"a":1,"e":"大承气汤大黄、芒硝泻热通便、软坚润燥，枳实、厚朴行气导滞、消痞除满，四药合用攻下力峻，主治阳明腑实之大便不通、频转矢气、脘腹痞满、潮热谵语，功用为峻下热结。攻下冷积是温脾汤、三物备急丸；润肠通便属麻子仁丸、济川煎；轻下热结为小承气汤；缓下热结是调胃承气汤，A、C、D、E项泻下之力与适应证各有区别，B项准确"},{"q":"补益剂应用时需注意","o":["真虚假实证、真实假虚证均可使用补益剂","补益剂中须配伍健胃消导之品，注意补而不滞","若血虚急证与大失血者，尤当着重补血","气虚重者应适当补气，血虚重者应适当补血","补益剂性质温和，适用范围广，虚证实证均可"],"a":1,"e":"补益剂多滋腻壅滞，久服易碍胃气，故常配伍陈皮、砂仁等健脾消导之品，使补而不滞、滋而不腻，此为应用补益剂之重要注意。真虚假实可补、真实假虚当攻，不可概用补益，A项笼统而言有误；血虚急证、大失血当益气固脱、急则治标，非单纯着重补血，C项偏颇；D项仅泛言补气补血，未体现防滋腻之关键；补益剂针对虚证，实证禁用，E项错误，B项切中配伍宁胃之要"},{"q":"逍遥散与实脾散共用的药物是","o":["当归、白芍","茯苓、白术","干姜、甘草","附子、生姜","大枣、柴胡"],"a":1,"e":"逍遥散柴胡、当归、白芍、白术、茯苓、甘草、生姜、薄荷疏肝养血、健脾和营；实脾散附子、干姜、白术、茯苓、甘草、厚朴、木香、槟榔、草果、木瓜等温阳健脾、行气利水。两方共用白术、茯苓，均取健脾渗湿之功。当归、白芍、柴胡仅见于逍遥散，干姜、附子、生姜仅见于实脾散，大枣虽两方或用但非主药，A、C、D、E项非共有，B项符合"},{"q":"十灰散的功效是","o":["清热止血","凉血止血","收敛止血","祛瘀止血","温经止血"],"a":1,"e":"十灰散十味药烧灰存性，大蓟、小蓟、侧柏叶、白茅根、茜草、栀子、大黄、丹皮等凉血止血、清热降火，棕榈皮收敛止血，主治血热妄行之上部出血，功效为凉血止血。清热止血偏指清肺、清胃止血药；收敛止血为花蕊石、仙鹤草类；祛瘀止血属三七、茜草炭；温经止血是黄土汤、艾叶，A、C、D、E项治法不同，B项符合本方凉血与收敛并用、以凉血为主之功效"},{"q":"二陈汤中“二陈”指下列哪组药","o":["半夏、茯苓","半夏、甘草","半夏、橘红","橘红、茯苓","橘红、乌梅"],"a":2,"e":"二陈汤以半夏、橘红为主药，二者皆以陈久者良，故得二陈之名，半夏燥湿化痰、和胃降逆，橘红理气化痰，配茯苓健脾渗湿、甘草和中、生姜制毒、乌梅敛肺。茯苓、甘草、乌梅虽为方中药物，但不属二陈命名之列，A、B、D、E项所列或含茯苓、甘草、乌梅，均非二陈本义，C项半夏、橘红准确对应方名由来"},{"q":"甘露消毒丹的病机是","o":["湿热内蕴，升降失常","湿热内蕴，气机阻滞","湿热内蕴，下注膀胱","湿热疫毒，蕴于气分","湿热疫毒，蕴于血分"],"a":3,"e":"甘露消毒丹滑石、茵陈、黄芩清热利湿解毒，石菖蒲、藿香、薄荷、白蔻仁芳香化浊、宣畅气机，木通、川贝母、射干、连翘等清热利咽散结，主治湿温时疫、湿热疫毒蕴于气分，见发热倦怠、胸闷腹胀、颐肿咽痛。湿热内蕴、升降失常偏三仁汤；下注膀胱宜八正散；湿热并重非其确切病机；蕴于血分宜犀角地黄汤、清瘟败毒饮，A、B、C、E项不合，D项符合本方气分湿热疫毒之病机"},{"q":"炙甘草汤与一贯煎共有的药物是","o":["沙参、麦门冬","生地黄、麦门冬","生地黄、当归","生地黄、人参","阿胶、麦门冬"],"a":1,"e":"炙甘草汤炙甘草、人参、大枣、桂枝、生姜、生地黄、麦冬、阿胶、麻仁、清酒益气滋阴、通阳复脉，主治心动悸、脉结代；一贯煎北沙参、麦冬、当归、生地黄、枸杞子、川楝子滋阴疏肝，主治阴虚肝郁胁痛。两方共有生地黄、麦门冬，均取滋阴养血生津之功。沙参仅一贯煎有，阿胶仅炙甘草汤有，当归、人参各见一方，A、C、D、E项非两方共有，B项准确"},{"q":"清胃散的主治证是","o":["胃热牙痛","阳明经热证","胃阴不足证","胃热阴虚证","脾胃伏火证"],"a":0,"e":"清胃散黄连清胃泻火，生地黄、牡丹皮凉血清热，当归养血和血，升麻散火解毒、引药入阳明，主治胃有积热之牙痛、牙龈红肿、唇颊肿痛，功用清胃凉血。阳明经热证宜白虎汤；胃阴不足、胃热阴虚宜玉女煎；脾胃伏火宜泻黄散，B、C、D、E项病机与治法有别，A项胃热牙痛正是清胃散清胃凉血、散火止痛之主治"},{"q":"山栀子在咳血方中的配伍意义是","o":["清热凉血，清心除烦","凉血止血，清心除烦","清热除烦，解毒利湿","清热解毒，凉血除烦","清肝泻火，凉血除烦"],"a":4,"e":"咳血方青黛、栀子清肝泻火、凉血止血，瓜蒌仁、海蛤壳清化痰热，诃子敛肺止咳，主治肝火犯肺之咳血，栀子在此清泻肝火、凉血除烦，助青黛使肝火清则肺不受犯。清热凉血、清心除烦偏清营汤、导赤散；凉血止血指大蓟、小蓟类；清热除烦、解毒利湿非栀子在此之专义；清热解毒、凉血除烦表述笼统，A、B、C、D项不确切，E项符合栀子在咳血方中清肝凉血之配伍"},{"q":"十灰散的组成药物中无","o":["大蓟","仙鹤草","侧柏叶","山栀子","白茅根"],"a":1,"e":"十灰散由大蓟、小蓟、荷叶、侧柏叶、茅根、茜草、栀子、大黄、牡丹皮、棕榈皮十味烧灰组成，凉血止血，主治血热妄行出血。仙鹤草虽为收敛止血要药，但不在十灰散原方之列，B项符合题干否定式提问。大蓟、侧柏叶、山栀子、白茅根均为原方药物，A、C、D、E项均属十灰散组成，故排除"},{"q":"茵陈蒿汤的主治病证是","o":["湿热并重证","热重于湿证","湿重于热证","黄疸阳黄","黄疸阴黄"],"a":3,"e":"茵陈蒿汤茵陈蒿清热利湿、退黄为君，栀子清泻三焦湿热，大黄泄热逐瘀、通利大便，三药合用清热利湿退黄，主治湿热黄疸之阳黄，见一身面目俱黄、黄色鲜明、腹微满、小便短赤。湿热并重、热重于湿、湿重于热为湿温辨证分型，非本方主治之病名；黄疸阴黄色暗，宜茵陈四逆汤，A、B、C、E项不合，D项阳黄符合本方清热利湿退黄之主治"},{"q":"不属于温里剂的方剂是","o":["小建中汤","温胆汤","四逆汤","当归四逆汤","理中丸"],"a":1,"e":"温里剂以附子、干姜、肉桂等温热药为主，小建中汤温中补虚、和里缓急，四逆汤回阳救逆，当归四逆汤温经散寒，理中丸温中祛寒，均属温里剂。温胆汤半夏、陈皮、茯苓、甘草、枳实、竹茹、生姜、大枣理气化痰、和胃利胆，主治胆郁痰扰，药性平和偏凉，归祛痰剂范畴，非温里剂，B项符合否定式提问，A、C、D、E均为温里代表方"},{"q":"失笑散主治证的病机是","o":["瘀血内停，脉道阻滞","寒凝血滞，冲任失调","气血郁滞，血行失畅","气虚血瘀，脉络阻滞","营血虚滞，气机失畅"],"a":0,"e":"失笑散五灵脂、蒲黄活血散瘀、止痛，主治瘀血内停、脉道阻滞之胸腹疼痛、痛经、产后瘀阻腹痛，病机为瘀血内停、不通则痛。寒凝血滞、冲任失调偏温经汤、少腹逐瘀汤；气血郁滞、血行失畅偏柴胡疏肝汤、血府逐瘀汤；气虚血瘀、脉络阻滞宜补阳还五汤；营血虚滞、气机失畅是四物汤类，B、C、D、E项病机各有归属，A项符合失笑散活血祛瘀止痛之主治"},{"q":"肾虚不固之遗精宜选","o":["固冲汤","固经丸","牡蛎散","金锁固精丸","桑螵蛸散"],"a":3,"e":"金锁固精丸沙苑子补肾固精为君，芡实、莲须固肾涩精，龙骨、牡蛎煅用涩精止遗，莲子肉健脾固肾，共奏涩精补肾之功，专治肾虚不固之遗精滑泄。固冲汤固冲摄血、益气健脾，主崩漏；固经丸滋阴清热、固经止崩；牡蛎散固表敛汗，主自汗盗汗；桑螵蛸散调补心肾、涩精缩尿，主心肾两虚之遗尿尿频，A、B、C、E项各有专主，D项符合肾虚遗精之治"},{"q":"柴胡在四逆散中作用是","o":["疏肝解郁，透邪外出","透泄少阳之邪","解表退热","升举阳陷","截疟解毒"],"a":0,"e":"四逆散柴胡疏肝解郁、升发阳气、透邪外出，使郁热外达、气机条畅，为君药，配枳实一升一降，芍药、甘草柔肝缓急，主治阳郁厥逆及肝郁脾虚之证。透泄少阳之邪是小柴胡汤中柴胡之用；解表退热为柴胡在解表剂中之功；升举阳陷属补中益气汤、升麻之配；截疟解毒非常用表述，B、C、D、E项各归他方他药，A项符合柴胡在四逆散中疏肝透邪之配伍意义"},{"q":"痛泻要方中配伍防风的意义是","o":["疏风解表","祛风除湿","散寒止痛","疏肝解郁","升阳举陷"],"a":3,"e":"痛泻要方防风辛温，疏肝解郁、条达肝气，助白芍柔肝缓急，又升阳胜湿，合白术、陈皮、白芍共奏扶土抑木之功，主治脾虚肝郁之腹痛泄泻。疏风解表、祛风除湿为防风在解表、祛风湿剂中之用；散寒止痛非本方所取；升阳举陷虽防风有升散之性，但此处重在疏肝解郁以抑木，A、B、C、E项偏颇，D项符合防风在痛泻要方中疏肝抑木之配伍"},{"q":"四神丸取","o":["枣肉为丸","炼蜜为丸","蒸饼为丸","水泛为丸","山药为丸"],"a":0,"e":"四神丸补骨脂温肾暖脾、助阳止泻为君，肉豆蔻温中涩肠，五味子敛酸固涩，吴茱萸温中散寒，以生姜、大枣同煮，取枣肉为丸，温肾暖脾、固肠止泻，主治脾肾阳虚之五更泄泻。炼蜜为丸、水泛为丸、蒸饼为丸、山药为丸皆非四神丸原方制法，B、C、D、E项不符，A项枣肉为丸体现本方温补脾肾、缓和安全之制丸用意"},{"q":"疏肝理脾的基础方是","o":["小柴胡汤","四逆散","痛泻要方","大柴胡汤","四逆汤"],"a":1,"e":"四逆散柴胡疏肝解郁、透邪外出，枳实理气行滞，芍药、甘草柔肝缓急和中，一疏肝一理脾，为疏肝理脾、调和肝脾之基础方，阳郁厥逆、肝郁脾虚诸证皆可加减。小柴胡汤和解少阳，主往来寒热；痛泻要方扶土抑木，专治痛泻；大柴胡汤和解少阳、内泻热结；四逆汤回阳救逆，A、C、D、E项各有专主，B项符合四逆散疏肝理脾之基础方地位"},{"q":"下列不属于清燥救肺汤的辨证要点是","o":["身热夜甚","干咳少痰","气逆而喘","脉虚大而数","舌红少苔"],"a":0,"e":"清燥救肺汤桑叶、石膏、甘草、人参、胡麻仁、阿胶、麦冬、杏仁、枇杷叶清燥润肺、养阴益气，主治温燥伤肺之身热、干咳少痰、气逆而喘、舌红少苔、脉虚大而数。身热夜甚为热入营分之特征，宜清营汤、犀角地黄汤类，非清燥救肺汤燥热伤肺所见，A项符合否定式提问；B、C、D、E均为本方主证要点"},{"q":"主治大头瘟的方剂是","o":["黄连解毒汤","普济消毒饮","清瘟败毒饮","仙方活命饮","甘露消毒丹"],"a":1,"e":"普济消毒饮黄芩、黄连清热泻火，牛蒡子、连翘、薄荷、僵蚕、柴胡、桔梗、升麻等疏散风热、解毒利咽，玄参、马勃、板蓝根清热解毒，陈皮、甘草理气和中，主治风热疫毒上攻之大头瘟，见头面红肿焮痛、咽喉不利。黄连解毒汤泻三焦火毒，清瘟败毒饮气血两燔，仙方活命饮消痈散结，甘露消毒丹利湿化浊，A、C、D、E项各有主证，B项符合普济消毒饮疏风清热解毒、专治大头瘟之主治"},{"q":"症见汗出恶风，小便不利，苔白，脉浮者，治宜","o":["桂枝汤","五苓散","五皮散","猪苓汤","防己黄芪汤"],"a":4,"e":"防己黄芪汤防己祛风利水，黄芪益气固表，白术健脾燥湿，甘草、姜、枣调和，主治风湿或风水之表虚证，见汗出恶风、小便不利、苔白、脉浮，功益气祛风、健脾利水。桂枝汤解肌调和营卫，主汗出恶风而无小便不利；五苓散利水渗湿、温阳化气，主膀胱气化不利；五皮散利水消肿，猪苓汤利水养阴清热，A、B、C、D项均不兼顾表虚汗出与风湿，E项符合本方证"},{"q":"下列各项中，属于真武汤药物组成的是","o":["茯神","芍药","干姜","肉桂","苍术"],"a":1,"e":"真武汤附子温肾助阳、化气行水为君，茯苓、白术健脾渗湿利水，生姜温散水气，芍药利小便、缓急止痛、敛阴和营，防温燥伤阴，共奏温阳利水之功。茯神为茯苓之抱木者，偏宁心安神，非本方所用；干姜、肉桂温中，苍术燥湿，均不在真武汤原方，A、C、D、E项排除，B项芍药为方中唯一养血柔肝、利水和营之品"},{"q":"桃核承气汤中配伍桂枝的用意是","o":["温经散寒","散寒通脉","助阳化气","通行血脉","平冲降逆"],"a":3,"e":"桃核承气汤桃仁破血逐瘀，大黄、芒硝泻热通便，甘草调和，桂枝辛温通行血脉、助桃仁活血祛瘀，并防大黄、芒硝寒凉凝滞，使瘀热去而血脉通，主治下焦蓄血之少腹急结、小便自利。温经散寒、散寒通脉偏当归四逆汤、桂枝汤；助阳化气为苓桂术甘汤、五苓散中桂枝之用；平冲降逆是桂枝加桂汤、苓桂术甘汤之意，A、B、C、E项各归他方，D项符合桂枝在桃核承气汤中通行血脉之配伍"},{"q":"保和丸的君药是","o":["神曲","莱菔子","半夏","陈皮","山楂"],"a":4,"e":"保和丸山楂酸甘微温，善消肉食油腻之积，用量最重而为君药，神曲消酒食陈腐之积，莱菔子消面食痰气之积，半夏、陈皮、茯苓和胃化痰，连翘清热散结，主治食积停滞之脘腹胀满、嗳腐吞酸。神曲、莱菔子为臣药，半夏、陈皮理气化痰为佐，均非君药，A、B、C、D项各有分工，E项山楂针对食积主要成因，体现本方消食导滞之主药地位"},{"q":"保和丸的服药时间应该是","o":["食后","睡前","食远","晨起","食前"],"a":2,"e":"保和丸消食导滞，宜食远服之，俾药力与食积相值，缓消渐化而不伤胃气。食后服药多针对上部病证或刺激性药；睡前服主安神；晨起服多取升阳之意；食前服侧重补益或驱虫，均非消食剂常规服法，A、B、D、E项不合，C项食远（约两餐之间）符合保和丸消食和胃之服药时间要求"},{"q":"大柴胡汤的功用是","o":["和解少阳，内泻热结","疏风解表，泻热通便","峻下热结","调和营卫","泻下逐水"],"a":0,"e":"大柴胡汤小柴胡汤去人参、甘草，加枳实、大黄、芍药，柴胡、黄芩和解少阳，大黄、枳实内泻阳明热结，芍药缓急、半夏生姜和胃降逆，主治少阳阳明合病，功用和解少阳、内泻热结。疏风解表、泻热通便非少阳阳明双解之法；峻下热结是三承气汤；调和营卫属桂枝汤；泻下逐水为十枣汤，B、C、D、E项各有专主，A项准确概括本方表里双解之功用"},{"q":"属于清营汤组成药物的是","o":["沙参","苦参","丹参","人参","天冬"],"a":2,"e":"清营汤水牛角、生地黄、玄参、竹叶心、麦冬、丹参、黄连、银花、连翘清营解毒、透热养阴，其中丹参清心活血、凉血除烦，使热不致与血相结。沙参养阴润肺，苦参清热燥湿，人参大补元气，天冬滋阴润燥，四药均不在清营汤原方之列，A、B、D、E项排除，C项丹参为方中凉血活血、防热入血分之要药"},{"q":"主治少阳湿热证之常用方是","o":["半夏泻心汤","小柴胡汤","蒿芩清胆汤","龙胆泻肝汤","茵陈蒿汤"],"a":2,"e":"蒿芩清胆汤青蒿、黄芩清泄少阳湿热，竹茹、枳壳、陈皮、半夏、茯苓、碧玉散清胆和胃、理气化痰，主治少阳湿热之寒热如疟、寒轻热重、口苦膈闷、吐酸苦水。半夏泻心汤寒热平调、消痞散结，主心下痞；小柴胡汤和解少阳，主伤寒少阳证而无湿热；龙胆泻肝汤清肝胆实火、利肝经湿热；茵陈蒿汤清热利湿退黄，A、B、D、E项病机有别，C项符合少阳湿热之常用方"},{"q":"理中丸与四君子汤组成中相同的药物是","o":["白术、干姜、人参","甘草、人参、干姜","人参、茯苓、甘草","甘草、人参、白术","人参、茯苓、白术"],"a":3,"e":"理中丸人参、干姜、白术、炙甘草温中祛寒、补气健脾；四君子汤人参、白术、茯苓、炙甘草益气健脾。两方共有药物为人参、白术、甘草，即理中丸去干姜、四君子汤去茯苓之异。干姜仅理中丸有，茯苓仅四君子汤有，故含干姜的A、B项与含茯苓的C、E项均非两方共有，D项甘草、人参、白术准确列出共有药物"},{"q":"十灰散中配伍大黄的意义是","o":["攻下积滞","活血祛瘀","清热凉血","温下寒积","导热下行"],"a":4,"e":"十灰散用大黄苦寒，泻热通便、导热下行，使上炎之血热随大便而去，折其上升之势，与诸凉血止血药相伍，共治血热妄行之吐血、咯血。攻下积滞为承气汤类之用；活血祛瘀指桃仁、丹参；清热凉血是大蓟、生地、栀子之能；温下寒积属温脾汤、大黄附子汤，A、B、C、D项不合，E项导热下行体现大黄在十灰散中降泄上炎之火、引血归经之配伍"},{"q":"八正散的功用是","o":["清热泻火，利水养阴","清热泻火，利水通淋","清热泻火，通淋排石","清热凉血，利水通淋","凉血止血，利水通淋"],"a":1,"e":"八正散车前子、瞿麦、萹蓄、滑石、木通清热利水通淋，栀子、大黄清热泻火、泄浊通便，甘草梢缓急和中，灯心草引火下行，共奏清热泻火、利水通淋之功，主治湿热下注之热淋。利水养阴为猪苓汤；通淋排石偏石韦散；清热凉血、凉血止血非本方主功，A、C、D、E项各有偏重，B项准确概括八正散治湿热淋证之功用"},{"q":"温脾汤中用为君药的是","o":["人参、大黄","附子、大黄","大黄、芒硝","附子、干姜","人参、芒硝"],"a":1,"e":"温脾汤附子温壮脾阳、散寒凝，大黄泻下攻逐冷积，二药相须为君，温阳与攻下并行，主治脾阳不足、冷积内停之便秘腹痛、手足不温，功温补脾阳、攻下冷积。人参、当归益气养血为佐，芒硝助大黄软坚泻下，干姜助附子温中，均非君药，A、C、D、E项所列或偏补、或偏泻、或仅为佐助，B项附子、大黄体现本方温下法之核心配伍"},{"q":"功用为泻火逐痰的方剂是","o":["滚痰丸","清气化痰丸","贝母瓜蒌散","温胆汤","二陈汤"],"a":0,"e":"滚痰丸礞石煅后咸寒，消痰下气、软坚，黄芩、大黄清热泻火、荡涤实热，沉香行气降逆，共奏泻火逐痰之功，主治实热老痰之癫狂、咳喘痰稠。清气化痰丸清热化痰、理气止咳；贝母瓜蒌散润肺化痰；温胆汤理气化痰、和胃利胆；二陈汤燥湿化痰，均无泻火逐顽痰之力，B、C、D、E项化痰之力与适应证不同，A项符合滚痰丸攻逐实热老痰之功用"},{"q":"大承气汤与大柴胡汤共有的药物是","o":["大黄、芍药","枳实、厚朴","柴胡、黄芩","当归、升麻","大黄、枳实"],"a":4,"e":"大承气汤大黄、芒硝、枳实、厚朴峻下热结；大柴胡汤柴胡、黄芩、大黄、枳实、芍药、半夏、生姜、大枣和解少阳、内泻热结。两方共有大黄、枳实，均取泻热通腑、行气除痞之功。厚朴仅大承气汤有，柴胡、黄芩、芍药仅大柴胡汤有，当归、升麻两方皆无，故A、B、C、D项所列均含非共有之品，E项大黄、枳实符合两方共有药物"},{"q":"参苓白术散中除人参、茯苓、白术、甘草和桔梗外，尚有","o":["黄芪、当归、陈皮、升麻、柴胡","莲子肉、薏苡仁、砂仁、白扁豆、山药","莲子肉、薏苡仁、砂仁、当归、陈皮","黄芪、当归、砂仁、白扁豆、山药","黄芪、当归、陈皮、白扁豆、山药"],"a":1,"e":"参苓白术散即四君子汤（人参、白术、茯苓、甘草）加山药、莲子肉、白扁豆、薏苡仁、砂仁、桔梗，益气健脾、渗湿止泻。黄芪、当归、升麻、柴胡为补中益气汤之属，非本方药物，A、C、D、E项所列均含黄芪、当归等，与参苓白术散健脾渗湿之组方不符，B项准确列出莲子肉、薏苡仁、砂仁、白扁豆、山药五味"},{"q":"羚角钩藤汤证的病机是","o":["温热病邪传入厥阴，肝经热盛，热极动风","温病迁延日久，邪热灼伤真阴","邪热久羁，耗伤阴血，虚风内动","肝肾不足，肝阳偏亢，生风化热","肝肾阴虚，肝阳偏亢，阳亢化风，气血逆乱"],"a":0,"e":"羚角钩藤汤羚羊角、钩藤凉肝息风，桑叶、菊花清热疏肝，贝母、竹茹清热化痰，生地、白芍、甘草、茯神滋阴柔肝、宁心安神，主治温热病邪传入厥阴、肝经热盛、热极动风之高热不退、烦躁、手足抽搐。温病迁延、邪热灼伤真阴或虚风内动属大定风珠、三甲复脉汤；肝肾不足、肝阳化风宜镇肝熄风汤，B、C、D、E项病机属虚风或阳亢，A项符合本方热极生风之病机"},{"q":"不属于《温病条辨》白虎汤禁忌证的是","o":["脉沉者","不渴者","汗不出者","脉浮弦而细者","伤寒脉浮，发热无汗，其表未解"],"a":4,"e":"《温病条辨》明列白虎汤四禁：脉沉者、不渴者、汗不出者、脉浮弦而细者，皆因表里寒热虚实不合，投之反致变证。伤寒脉浮，发热无汗，其表未解虽亦属表证未解、不可早用清里，但不在《温病条辨》所载白虎汤禁忌之列，E项符合题干不属于之问；A、B、C、D四项即原文四禁，故排除"},{"q":"小建中汤的药物组成不包括","o":["芍药、桂枝","生姜、大枣","炙甘草","黄芪","饴糖"],"a":3,"e":"小建中汤桂枝、芍药、生姜、大枣、炙甘草、饴糖温中补虚、和里缓急，重用饴糖甘温质润、缓急止痛，主治中焦虚寒之腹痛喜温喜按。芍药、桂枝、生姜、大枣、炙甘草皆为原方药物；黄芪乃黄芪建中汤所加，小建中汤原方并无，D项符合否定式提问，A、B、C、E项均属小建中汤组成，故排除"},{"q":"四逆散的主治证是","o":["血虚寒厥证","心肾阳衰证","阳郁厥逆证","肝郁克脾证","脾胃气虚证"],"a":2,"e":"四逆散柴胡、枳实、芍药、甘草透邪解郁、疏肝理脾，主治外邪传经入里、气机郁遏、阳气内郁不达四末之阳郁厥逆，见手足不温、脉弦。血虚寒厥宜当归四逆汤；心肾阳衰之寒厥宜四逆汤；肝郁克脾之痛泻宜痛泻要方；脾胃气虚宜四君子汤，A、B、D、E项病机与方证各异，C项阳郁厥逆体现本方四逆而非虚寒之本质"},{"q":"完带汤主治","o":["白带","青带","黄带","赤带","黑带"],"a":0,"e":"完带汤白术、山药健脾益气、固摄带脉，苍术、陈皮、荆芥穗、车前子、柴胡等燥湿疏肝、化湿止带，白芍、甘草柔肝和中，主治脾虚肝郁、湿浊下注之白带，见带下色白或淡黄、清稀无臭。青带多属肝经湿热，黄带属湿热下注（易黄汤），赤带多肝郁血热或湿热伤络，黑带多脾肾亏虚或血瘀，B、C、D、E项各有病机，A项白带为完带汤主治"},{"q":"四磨汤中槟榔的配伍意义是","o":["补气扶正","降气平喘","行气破滞","调肝顺气","杀虫消积"],"a":2,"e":"四磨汤人参、槟榔、沉香、乌药四味磨汁煎服，槟榔辛苦温，行气破滞、下气导滞，助乌药、沉香降气解郁，人参益气扶正，使破气而不伤正，主治肝郁气逆之胸膈痞满、喘促。补气扶正为人参之用；降气平喘为沉香、乌药，调肝顺气偏乌药、香附；杀虫消积为槟榔驱虫之功，非本方配伍意图，A、B、D、E项不合，C项符合槟榔在四磨汤中行气破滞之作用"},{"q":"症见尿频尿急，溺时涩痛，舌苔黄腻，脉滑数者，治宜","o":["茵陈蒿汤","萆薢分清饮","石韦散","八正散","小蓟饮子"],"a":3,"e":"八正散车前子、瞿麦、萹蓄、滑石、木通、栀子、大黄、甘草梢、灯心草清热泻火、利水通淋，主治湿热下注膀胱之热淋，见尿频尿急、溺时涩痛、淋沥不畅、苔黄腻、脉滑数。茵陈蒿汤退黄，萆薢分清饮温肾利湿、分清化浊，主膏淋白浊；石韦散偏治石淋；小蓟饮子凉血止血，主血淋，A、B、C、E项各有主证，D项符合热淋湿热下注之治"},{"q":"心脾气血两虚证当以何方治之","o":["当归补血汤","四物汤","八珍汤","十全大补汤","归脾汤"],"a":4,"e":"归脾汤人参、黄芪、白术、甘草益气健脾，当归、龙眼肉养血安神，酸枣仁、茯苓、远志宁心安神，木香理气醒脾，姜、枣调和，益气补血、健脾养心，主治心脾气血两虚之心悸怔忡、健忘失眠、体倦食少及脾不统血。当归补血汤补气生血，主血虚发热；四物汤补血调血；八珍汤气血双补但无养心安神；十全大补汤温补气血，A、B、C、D项均不专主心脾两虚，E项准确"},{"q":"保和丸主治","o":["脾虚食积","食积证","湿热食积","酒积伤脾","痢疾，食积"],"a":1,"e":"保和丸山楂、神曲、莱菔子消食化积，半夏、陈皮、茯苓、连翘和胃化痰、清热散结，主治食积停滞之脘腹胀满、嗳腐吞酸、恶食呕逆，功消食和胃。脾虚食积宜健脾丸、枳术丸；湿热食积宜枳实导滞丸；酒积伤脾宜葛花解酲汤；痢疾食积另宜芍药汤、白头翁汤加减，A、C、D、E项均夹虚、夹湿或兼痢，非单纯食积，B项符合保和丸消食导滞之主治"},{"q":"阳和汤中所用的姜是","o":["生姜","干姜","炮姜","姜炭","煨姜"],"a":3,"e":"阳和汤熟地黄、鹿角胶养血助阳、填精益髓，姜炭、肉桂温阳散寒、通脉，麻黄、白芥子散寒通滞、化痰结，生甘草调和，主治阴疽之漫肿无头、皮色不变、酸痛无热。生姜走表发散、干姜温中燥烈、炮姜温经止血、煨姜和中止呕，均非本方所用，姜炭温阳入血、散寒通滞，切合阴疽温补之需，D项姜炭符合本方用药特点"},{"q":"黄连阿胶汤的功用是","o":["滋阴降火，清热平肝","滋阴降火，交通心肾","滋阴降火，除烦安神","滋阴降火，燥湿除满","滋阴降火，健脾益气"],"a":2,"e":"黄连阿胶汤黄连、黄芩清心泻火，阿胶、鸡子黄、芍药滋阴养血，主治少阴病阴虚火旺、心肾不交之心烦不得眠、口燥咽干，功用滋阴降火、除烦安神。滋阴降火、清热平肝非本方所有；交通心肾为交泰丸黄连配肉桂之功用；燥湿除满、健脾益气与阴虚火旺之治无关，A、B、D、E项不合，C项体现本方育阴清热、安神除烦之制"},{"q":"阴虚气滞而致脘胁疼痛的代表方剂是","o":["百合固金汤","一贯煎","炙甘草汤","益胃汤","小柴胡汤"],"a":1,"e":"一贯煎北沙参、麦冬、当归、生地黄、枸杞子滋阴养血、柔肝，川楝子疏肝理气、泄热止痛，主治肝肾阴虚、肝气不舒之脘胁疼痛、吞酸吐苦，功滋阴疏肝。百合固金汤滋阴润肺、止咳化痰；炙甘草汤益气滋阴、通阳复脉；益胃汤养阴益胃；小柴胡汤和解少阳，A、C、D、E项均不主治阴虚气滞之胁痛，B项符合一贯煎滋阴疏肝之主治"},{"q":"三物备急丸的主治是","o":["寒实腹痛","肾虚便秘","气滞腹痛","瘀血腹痛","津枯便秘"],"a":0,"e":"三物备急丸大黄、干姜、巴豆霜三味，巴豆辛热峻下、干姜温中散寒、大黄荡涤肠胃，共奏攻逐寒积之功，主治寒实冷积内停之心腹暴痛、便秘、气急。肾虚便秘宜济川煎；气滞腹痛宜柴胡疏肝散、四磨汤；瘀血腹痛宜桃核承气汤、失笑散；津枯便秘宜增液汤、麻子仁丸，B、C、D、E项病机与治法各异，A项寒实腹痛符合本方温下寒积之主治"},{"q":"主治水热互结之大结胸证的方剂是","o":["大承气汤","大柴胡汤","小承气汤","大陷胸汤","小陷胸汤"],"a":3,"e":"大陷胸汤大黄、芒硝、甘遂泻热逐水、破结通便，甘遂攻逐水饮之力尤峻，主治水热互结于胸腹之大结胸，见心下硬满疼痛、按之石硬、大便不通。大承气汤峻下热结，主阳明腑实；大柴胡汤和解少阳、内泻热结；小承气汤轻下热结；小陷胸汤清热化痰、宽胸散结，主痰热互结之小结胸，A、B、C、E项病机与结胸轻重不同，D项符合大结胸水热互结之治"},{"q":"竹叶石膏汤中半夏与麦门冬的配伍比例是","o":["2∶1","1∶2","1∶7","1∶5","7∶1"],"a":1,"e":"竹叶石膏汤原方半夏用半升、麦门冬用一升，二者用量之比为1∶2，麦冬倍于半夏，意在滋阴生津为主，半夏量少和胃降逆、止呕，与竹叶、石膏、人参、甘草、粳米共奏清热生津、益气和胃之功。1∶1、2∶1、1∶7、7∶1均不合原方用量，A、C、D、E项排除，B项1∶2准确反映本方麦冬倍半夏、润燥相济之配伍"},{"q":"防风在玉屏风散中的作用是","o":["疏风透疹","祛风散寒","祛风解痉","走表祛风","祛风升阳"],"a":3,"e":"玉屏风散黄芪益气固表为君，白术健脾固表为臣，防风走表祛风为佐，与黄芪相伍散中寓补、补中兼疏，使表气固密而邪不能侵，主治表虚自汗、易感风邪。疏风透疹为蝉蜕、牛蒡子类；祛风散寒属荆芥、防风在解表剂中；祛风解痉是白僵蚕、全蝎；祛风升阳偏羌活、柴胡，A、B、C、E项各归他药他方，D项走表祛风符合防风在玉屏风散中助黄芪实卫之配伍"},{"q":"泻白散与白虎汤共有的药物是","o":["石膏","粳米","知母","桑白皮","地骨皮"],"a":1,"e":"泻白散桑白皮、地骨皮、甘草、粳米清泻肺热、止咳平喘；白虎汤石膏、知母、甘草、粳米清热生津，主治气分热盛。两方均用粳米益胃生津、甘草和中，共有药物为粳米（甘草亦共有但选项中未列）。石膏、知母仅白虎汤有，桑白皮、地骨皮仅泻白散有，A、C、D、E项均非两方共有，B项粳米体现两方清泄肺胃之热而护中焦之共同用药"},{"q":"参苏饮的组成中不含有","o":["生姜","紫菀","干葛","前胡","半夏"],"a":1,"e":"参苏饮人参、紫苏叶、干葛、半夏、前胡、茯苓、陈皮、甘草、桔梗、枳壳、木香、生姜、大枣益气解表、理气化痰，主治气虚外感、内有痰湿。紫菀虽能润肺化痰止咳，但不在参苏饮原方之列，B项符合否定式提问。生姜、干葛、前胡、半夏均为本方药物，A、C、D、E项属参苏饮组成，故排除"},{"q":"小陷胸汤、贝母瓜蒌散、清气化痰丸共有的药物是","o":["瓜蒌","黄连","半夏","甘草","细辛"],"a":0,"e":"小陷胸汤黄连、半夏、瓜蒌清热化痰、宽胸散结；贝母瓜蒌散贝母、瓜蒌、天花粉、茯苓、橘红、桔梗润肺清热、理气化痰；清气化痰丸胆南星、黄芩、瓜蒌仁、半夏、陈皮、茯苓、杏仁、枳实、生姜清热化痰、理气止咳。三方均用瓜蒌以清热化痰、宽胸利气。黄连仅小陷胸汤有，半夏小陷胸汤与清气化痰丸有而贝母瓜蒌散无，甘草、细辛三方皆不用，B、C、D、E项排除，A项瓜蒌为三方共有"},{"q":"《医宗金鉴》所谓“以大寒之剂，易为清补之方”的方剂是","o":["竹叶石膏汤","清暑益气汤","白虎加人参汤","白虎加桂枝汤","白虎加苍术汤"],"a":0,"e":"《医宗金鉴》谓竹叶石膏汤以大寒之剂，易为清补之方，本方即白虎汤去知母，加人参、麦冬、半夏、竹叶，石膏、竹叶清热，人参、麦冬、甘草、粳米益气养阴，半夏和胃降逆，主治伤寒解后虚羸少气、气逆欲吐。白虎加人参汤仍偏清气分实热；白虎加桂枝汤温通；白虎加苍术汤燥湿；清暑益气汤养阴解暑，B、C、D、E项不合，A项体现本方清热兼清补之特点"},{"q":"小柴胡汤的功用是","o":["疏肝解郁","清热泻火","和解少阳","平调寒热","解表散寒"],"a":2,"e":"小柴胡汤柴胡、黄芩一散一清，和解少阳，半夏、生姜和胃降逆，人参、甘草、大枣益气和中，主治伤寒少阳证之往来寒热、胸胁苦满、默默不欲饮食、心烦喜呕，功用为和解少阳。疏肝解郁偏四逆散、逍遥散；清热泻火属白虎汤、黄连解毒汤；平调寒热是半夏泻心汤；解表散寒属麻黄汤、桂枝汤，A、B、D、E项治法各异，C项准确对应小柴胡汤和解少阳之基本功用"},{"q":"不属于清营汤辨证要点的是","o":["身热夜甚","神烦少寐","斑疹隐隐","舌绛而干","舌绛苔白滑"],"a":4,"e":"清营汤清营解毒、透热养阴，主治热入营分，辨证以身热夜甚、神烦少寐、斑疹隐隐、舌绛而干、脉数为要点。舌绛苔白滑提示湿浊或寒象，与热入营分、津伤液耗之舌绛而干相反，非清营汤证所见，E项符合否定式提问；A、B、C、D均反映热入营分、阴液受损之象，故排除"},{"q":"羚角钩藤汤与蒿芩清胆汤共有的组成药物是","o":["桑叶、菊花","黄芩、生地","白芍、半夏","茯苓、枳实","竹茹、甘草"],"a":4,"e":"羚角钩藤汤羚羊角、钩藤、桑叶、菊花、贝母、竹茹、生地、白芍、甘草、茯神凉肝息风、增液舒筋；蒿芩清胆汤青蒿、黄芩、竹茹、半夏、枳壳、陈皮、茯苓、碧玉散清胆利湿、和胃化痰。两方均用竹茹清热化痰、和胃，甘草调和诸药，为共有药物。桑叶、菊花、白芍仅羚角钩藤汤有，黄芩、枳实、茯苓仅蒿芩清胆汤有，A、B、C、D项排除，E项竹茹、甘草符合"},{"q":"银翘散中辛而微温可助君药开皮毛以解表散邪的配伍是","o":["荆芥穗、豆豉","芦根、竹叶","薄荷、牛蒡子","银花、连翘","牛蒡子、生甘草"],"a":0,"e":"银翘散银花、连翘清热解毒、轻宣透表为君，荆芥穗、淡豆豉辛而微温，辛散透邪、开皮毛以助君药解表散邪，且温而不燥，无悖于辛凉之剂。芦根、竹叶清热生津，薄荷、牛蒡子辛凉疏散风热，银花、连翘为君，牛蒡子配甘草利咽，均无辛温开皮毛之特性，B、C、D、E项不合，A项荆芥穗、豆豉体现本方辛凉之中少佐辛温之配伍"},{"q":"治疗外感凉燥证的方剂是","o":["杏苏散","桑杏汤","麦门冬汤","清燥救肺汤","三仁汤"],"a":0,"e":"杏苏散苏叶、前胡、杏仁、桔梗、陈皮、半夏、茯苓、甘草、生姜、大枣轻宣凉燥、理肺化痰，主治外感凉燥之头微痛、恶寒、咳嗽痰稀、鼻塞咽干。桑杏汤清宣温燥，主外感温燥；麦门冬汤养阴润肺、降逆下气；清燥救肺汤治温燥伤肺重证；三仁汤宣畅气机、清利湿热，治湿温，B、C、D、E项燥湿性质与病机不同，A项符合凉燥外感之治"},{"q":"症见咳嗽气喘，痰中带血，咽喉燥痛，头晕目眩，午后潮热，应选用","o":["当归六黄汤","百合固金汤","养阴清肺汤","杏苏散","桑杏汤"],"a":1,"e":"百合固金汤百合、麦冬、生地、熟地滋阴润肺、补肾，玄参、桔梗、甘草清热利咽，当归、白芍养血和血，贝母润肺化痰，主治肺肾阴虚、虚火上炎之咳嗽气喘、痰中带血、咽喉燥痛、午后潮热。当归六黄汤滋阴泻火、固表止汗；养阴清肺汤治白喉；杏苏散治凉燥；桑杏汤治温燥，A、C、D、E项病机与主治不同，B项符合肺肾阴虚、虚火灼肺之证"},{"q":"九味羌活汤为哪位医家所创制","o":["李东垣","王好古","张元素","刘完素","朱丹溪"],"a":2,"e":"九味羌活汤为张元素（洁古）所创，羌活、防风、苍术、细辛、川芎、白芷、生地、黄芩、甘草发汗祛湿、兼清里热，主治外感风寒湿邪、内有蕴热之恶寒发热、肢体酸重疼痛、口苦微渴。李东垣创补中益气汤、脾胃论诸方；王好古为张元素弟子；刘完素主寒凉、创防风通圣散；朱丹溪创越鞠丸、大补阴丸，A、B、D、E项医家与代表方不符，C项张元素即九味羌活汤之创制者"},{"q":"温胆汤所治证的病机是","o":["火热犯肺，灼津为痰","邪热内盛，痰热结胸","脾湿生痰，风痰上扰","胆胃不和，痰热内扰","胆胃不和，痰浊内扰"],"a":4,"e":"温胆汤半夏、陈皮、茯苓、甘草（二陈）理气化痰，枳实破气消痞，竹茹清热化痰、和胃止呕，生姜、大枣调和，主治胆胃不和、痰浊内扰之虚烦不眠、惊悸、呕恶、口苦。火热犯肺、灼津为痰是清气化痰丸证；邪热内盛、痰热结胸为小陷胸汤；脾湿生痰、风痰上扰属半夏白术天麻汤；痰热内扰为黄连温胆汤，A、B、C、E项病机偏热、偏风，D项符合温胆汤痰浊内扰之病机"},{"q":"定喘汤的组成中不包括","o":["苏子","生姜","半夏","白果","麻黄"],"a":1,"e":"定喘汤麻黄、白果、苏子、杏仁、半夏、款冬花、桑白皮、黄芩、甘草宣肺降气、清热化痰，主治风寒外束、痰热内蕴之哮喘，方中并无生姜。苏子降气化痰，半夏燥湿化痰，白果敛肺定喘，麻黄宣肺平喘，均为原方药物，A、C、D、E项属定喘汤组成，B项生姜不在其列"},{"q":"下列各项中不属于和法范畴的是","o":["透达膜原","疏肝和胃","分消上下","调和营卫","消食和胃"],"a":4,"e":"和法包括和解少阳（小柴胡汤）、透达膜原（达原饮）、疏肝和胃（逍遥散、柴胡疏肝散）、分消上下（三仁汤类）、调和营卫（桂枝汤）等，重在调和表里、寒热、虚实。消食和胃为消法（消食导滞，如保和丸）范畴，非和法，E项符合否定式提问；A、B、C、D四项均为和法具体运用，故排除"},{"q":"升麻葛根汤的功用是","o":["解肌发汗","解肌清热","解肌透疹","疏风止痛","疏风清热"],"a":2,"e":"升麻葛根汤升麻、葛根解肌透疹、升阳，芍药、甘草养血和营、缓急，主治麻疹初起、疹发不透之发热恶风、咳嗽、疹出不畅，功用解肌透疹。解肌发汗偏桂枝汤、葛根汤；解肌清热为柴葛解肌汤；疏风止痛属川芎茶调散；疏风清热是银翘散，A、B、D、E项治法有别，C项准确对应升麻葛根汤透发麻疹之主治"},{"q":"左归丸组成中有","o":["茯苓","牛膝","泽泻","枸杞子","牡丹皮"],"a":3,"e":"左归丸熟地黄、山药、山茱萸、枸杞子、菟丝子、鹿角胶、龟板胶、牛膝纯补无泻，滋阴补肾、填精益髓，枸杞子补肝肾、益精血，为方中补益肝肾之要药。茯苓、泽泻、牡丹皮乃六味地黄丸三泻之品，左归丸去掉三泻、纯用滋填，故A、C、E项均非本方药物；B项牛膝活血通经、引药下行，非滋阴填精之主药，D项枸杞子滋补肝肾、益精明目，正合本方纯补真阴之旨"},{"q":"藿香正气散主治证的病机是","o":["风寒在表，水饮内停","风寒在表，湿滞脾胃","风寒在表，内有蕴热","风热在表，湿滞脾胃","风湿在表，内有蕴热"],"a":1,"e":"藿香正气散藿香芳香化湿、解表和中为君，紫苏、白芷、桔梗散风寒、宣肺，半夏、陈皮、茯苓、苍术、厚朴、大腹皮燥湿理气、和胃止呕，甘草、姜、枣调和，主治外感风寒、内伤湿滞之霍乱吐泻、发热恶寒、腹痛。风寒在表、水饮内停为小青龙汤；内有蕴热当用石膏、黄芩类；风热在表宜银翘散；风湿在表宜羌活胜湿汤，A、C、D、E项病机有别，B项符合本方外散风寒、内化湿浊之主治"},{"q":"六味地黄丸与左归丸的组成中共有药物是","o":["熟地黄","茯苓","泽泻","枸杞子","牛膝"],"a":0,"e":"六味地黄丸熟地黄、山茱萸、山药、泽泻、茯苓、牡丹皮滋补肾阴，三补三泻；左归丸熟地黄、山药、山茱萸、枸杞子、菟丝子、鹿角胶、龟板胶、牛膝纯补无泻。两方共有熟地黄、山药、山茱萸，选项中熟地黄为共有且为君药。枸杞子、牛膝仅左归丸有，茯苓、泽泻仅六味地黄丸有，B、C、D、E项非两方共有，A项符合"},{"q":"以下关于小活络丹的药物组成描述错误的是","o":["川乌","乳香","草乌","天南星","地黄"],"a":4,"e":"小活络丹川乌、草乌温经散寒、祛风止痛，天南星燥湿化痰、散结，地龙通经活络，乳香、没药活血止痛，共奏祛风除湿、化痰通络、活血止痛之功。方中并无地黄，E项描述错误；川乌、草乌、天南星、乳香均属原方药物，A、B、C、D项描述正确，故排除"},{"q":"症见小便不利，苔白，脉浮或缓者，治宜","o":["利水渗湿，清热养阴","利水渗湿，温阳化气","利水渗湿，益气健脾","利水渗湿，温补肾阳","利水渗湿，温阳化饮"],"a":1,"e":"五苓散猪苓、茯苓、泽泻利水渗湿，白术健脾燥湿，桂枝温阳化气、解表，主治膀胱气化不利之水湿内停，见小便不利、头痛发热、苔白、脉浮或缓，功利水渗湿、温阳化气。兼清热养阴为猪苓汤；益气健脾是参苓白术散；温补肾阳偏真武汤、肾气丸；温阳化饮属苓桂术甘汤，A、C、D、E项治法各有对应方，B项符合五苓散化气行水之治"},{"q":"养阴清肺汤中少佐薄荷的意义是","o":["疏散肝郁","清利头目","芳香辟秽","散邪利咽","清热透疹"],"a":3,"e":"养阴清肺汤主治白喉，属阴虚肺燥、疫毒上攻，方以生地、麦冬、玄参养阴清热，少佐薄荷意在辛凉散邪、宣肺利咽，使邪从外达而咽喉得利。A项疏散肝郁为逍遥散中柴胡、薄荷之用；B项清利头目多见于桑菊饮；E项清热透疹为银翘散中薄荷、牛蒡子之职，均非本方佐薄荷之义"},{"q":"下列描述苏子降气汤的各项中哪一项是错误的","o":["苏子降气祛痰，止咳平喘","半夏、厚朴、前胡祛痰止咳平喘","肉桂温肾祛寒，纳气平喘","当归补血柔肝","生姜、苏叶宣肺散寒"],"a":3,"e":"苏子降气汤主治上实下虚之喘咳，紫苏子降气化痰止咳，半夏、厚朴、前胡降逆祛痰，肉桂温肾祛寒、纳气平喘，生姜、苏叶宣散风寒。方中当归意在养血和血、降逆下气，兼顾上实下虚与气血不和，并非补血柔肝，柔肝乃白芍、当归在逍遥散一类方中的配伍，故D项表述错误"},{"q":"下列哪首方剂不是二陈汤化裁而来","o":["茯苓丸","温胆汤","半夏白术天麻汤","清气化痰丸","涤痰汤"],"a":0,"e":"二陈汤由半夏、陈皮、茯苓、甘草组成，温胆汤加竹茹、枳实，涤痰汤更益以胆南星、石菖蒲、人参，半夏白术天麻汤加白术、天麻，清气化痰丸加黄芩、瓜蒌、胆南星，皆在其基础上加减。茯苓丸用半夏、茯苓配枳壳、风化硝，去陈皮、甘草，功偏燥湿行气、软坚化痰，主治痰停中脘、流注四肢之臂痛，与二陈汤化裁脉络不同"},{"q":"理中丸的功用是","o":["温中补虚、降逆止呕","温中散寒、补气健脾","温中补虚、和里缓急","温经散寒、养血通脉","温中散寒、降逆止呕"],"a":1,"e":"理中丸以干姜温中散寒，人参、白术、甘草补气健脾，共奏温中散寒、补气健脾之效，主治脾胃虚寒之脘腹绵绵作痛、喜温喜按、呕吐、大便溏泻。A项温中补虚、降逆止呕为吴茱萸汤功用；C项温中补虚、和里缓急是小建中汤所主；D项温经散寒、养血通脉属当归四逆汤，三者各有所主"},{"q":"峻下逐水法的基础方剂是","o":["禹功散","十枣汤","大陷胸汤","济川煎","黄龙汤"],"a":1,"e":"十枣汤以芫花、甘遂、大戟三味峻下逐水，用大枣十枚煎汤送服以缓毒护中、培土制水，为峻下逐水法之基础方，主治悬饮及水肿实证。C项大陷胸汤虽泻热逐水，专为水热互结之结胸而设；D项济川煎温肾益精、润肠通便，属润下；E项黄龙汤攻下兼补气血，均非峻下逐水之基础方"},{"q":"下列哪项不属于理中丸的主治证候","o":["脘腹绵绵作痛","畏寒肢冷","大便溏泻","恶心呕吐","脉弦数"],"a":4,"e":"理中丸主治脾胃虚寒，中焦虚寒则脘腹绵绵作痛、喜温喜按，胃失和降则恶心呕吐，脾失运化则大便溏泻，阳气不足则畏寒肢冷，脉当沉细或沉迟无力。脉弦数主肝郁化火或里热，与虚寒病机相反，不属于理中丸主治；A、B、C、D四项均为其中焦虚寒证的常见表现"},{"q":"羚角钩藤汤配伍的臣药是","o":["生地、白芍","羚羊角、钩藤","川贝母、淡竹茹","茯神木、生甘草","桑叶、菊花"],"a":4,"e":"羚角钩藤汤以羚羊角、钩藤凉肝息风为君，主治肝热生风之高热不退、手足抽搐。桑叶、菊花助君凉肝明目、疏散肝风，是为臣药。B项羚羊角、钩藤是本方君药而非臣药；A项生地、白芍滋阴柔肝，C项川贝母、淡竹茹清热化痰，均为佐药；D项茯神木安神、生甘草调和，属佐使，皆非臣药"},{"q":"八正散与连朴饮共同的药物是","o":["黄连","甘草","栀子","滑石","木通"],"a":2,"e":"八正散以车前子、瞿麦、萹蓄、滑石、栀子、木通、大黄、甘草清热泻火、利水通淋；连朴饮以厚朴、黄连、栀子、半夏、石菖蒲、香豉、芦根清热化湿、理气和中，两方均用栀子清热泻火除烦。黄连、半夏、石菖蒲为连朴饮所有而八正散不用；滑石、木通、瞿麦、萹蓄利水通淋，仅见于八正散，非两方共有"},{"q":"厚朴温中汤主治","o":["脾胃气滞证","寒热互结证","肝郁化火证","寒湿气滞证","气滞寒凝证"],"a":3,"e":"厚朴温中汤以厚朴、陈皮、草豆蔻、木香行气燥湿，干姜、生姜温中散寒，茯苓渗湿，甘草调和，主治脾胃寒湿气滞之脘腹胀满疼痛、不思饮食、苔白腻、脉沉弦。A项脾胃气滞无明显寒象，多属木香顺气丸一类；B项寒热互结为半夏泻心汤所主；E项气滞寒凝强调寒邪凝滞、疼痛剧烈，非本方温中行气燥湿之所宜"},{"q":"珍珠母丸的病位以（ ）为主","o":["心和脾","肝和肾","心和肝","脾和肝","心和肾"],"a":2,"e":"珍珠母丸以珍珠母、龙齿镇心安神、平肝潜阳，当归、熟地、酸枣仁、柏子仁滋阴养血，人参、茯神益气宁心，沉香摄纳浮阳，主治阴血不足、肝阳上扰之惊悸失眠、头目眩晕，病位以心、肝为主。A项心脾两虚为归脾汤所主；E项心肾不交多见天王补心丹、交泰丸证；B项肝肾阴虚当用杞菊地黄丸，均非本方病位"},{"q":"以下关于羚角钩藤汤的组成，表述错误的是","o":["桑叶、菊花","浙贝母、茯苓","白芍、甘草","生地、竹茹","羚羊角、钩藤"],"a":1,"e":"羚角钩藤汤由羚羊角、钩藤、霜桑叶、滁菊花、鲜生地、生白芍、川贝母、淡竹茹、茯神木、生甘草组成，主治肝热生风。方中用川贝母清热化痰，用茯神木宁心安神，并非浙贝母与茯苓，故B项表述错误。其余桑叶、菊花、生地、竹茹、白芍、甘草、羚羊角、钩藤均为本方药物，A、C、D、E表述正确"},{"q":"下列选项中，不属于济川煎组成的是","o":["当归","牛膝","泽泻","升麻","白芍"],"a":4,"e":"济川煎由肉苁蓉、当归、牛膝、泽泻、升麻、枳壳组成，主治肾虚便秘，肉苁蓉温肾益精、润燥，当归养血润肠，牛膝引药下行，泽泻渗湿，升麻升清，枳壳宽肠。方中并无白芍，白芍养血敛阴、柔肝止痛，非本方用药，故E项不属于济川煎组成"},{"q":"血府逐瘀汤主治的病证是","o":["膈下血瘀证","少腹血瘀证","胸中血瘀证","两胁血瘀证","头部血瘀证"],"a":2,"e":"血府逐瘀汤由桃红四物汤合四逆散加桔梗、牛膝而成，活血化瘀、行气止痛，主治胸中血瘀之胸痛、头痛日久不愈、痛如针刺有定处、舌暗红或有瘀斑。A项膈下血瘀为膈下逐瘀汤所主；B项少腹血瘀属少腹逐瘀汤；E项头部血瘀当用通窍活血汤，三者虽同为逐瘀方而病位各异"},{"q":"真武汤主治","o":["阳虚水泛证","阴水","风水","蓄水证","中阳不足之痰饮"],"a":0,"e":"真武汤以附子温肾助阳、化气行水，茯苓、白术健脾渗湿，生姜温散水气，白芍利小便、缓急止痛，主治脾肾阳虚、水湿泛溢之阳虚水泛证，见小便不利、四肢沉重疼痛、苔白、脉沉细。C项风水多见越婢加术汤证；D项蓄水证属五苓散；E项中阳不足之痰饮为苓桂术甘汤所主；B项阴水仅为水肿辨证大类，不能确切对应本方病机"},{"q":"朱砂安神丸与酸枣仁汤组成中共有的药是","o":["朱砂","酸枣仁","甘草","川芎","当归"],"a":2,"e":"朱砂安神丸由朱砂、黄连、生地、当归、炙甘草组成，镇心安神、泻火养阴；酸枣仁汤由酸枣仁、知母、川芎、茯苓、甘草组成，养血安神、清热除烦，两方均用甘草调和诸药。朱砂、黄连、生地、当归仅见于朱砂安神丸；酸枣仁、知母、川芎、茯苓为酸枣仁汤独有，A、B、D、E均非共有药物"},{"q":"主治证病机为“外感风寒，气郁不舒”的方剂是","o":["藿香正气散","正柴胡饮","香薷散","葱豉汤","香苏散"],"a":4,"e":"香苏散以紫苏叶疏风散寒，香附疏肝理气，陈皮理气和中，甘草调和，主治外感风寒兼气郁不舒，症见恶寒身热、头痛无汗、胸脘痞闷、不思饮食。A项藿香正气散主治外感风寒、内伤湿滞；C项香薷散主治夏月阴暑、外寒内湿；B项正柴胡饮解表散寒，均无疏肝理气之配比，与气郁不舒的病机不符"},{"q":"主治脾不统血证的方剂是","o":["四物汤","当归补血汤","归脾汤","胶艾汤","人参养荣汤"],"a":2,"e":"归脾汤以人参、黄芪、白术、甘草补气健脾，当归、龙眼肉养血，酸枣仁、茯神、远志宁心安神，木香理气醒脾，益气与养血并重，主治心脾气血两虚及脾不统血之便血、崩漏、皮下出血。D项胶艾汤养血止血、调经安胎，主治冲任虚寒之崩漏；B项当归补血汤重在补气生血，治血虚发热；A项四物汤为补血调血基础方，均非脾不统血所主"},{"q":"主治元气不升，气阴不足，脾肾两虚之消渴，宜首选的方剂是","o":["玉液汤","增液汤","百合固金汤","麦门冬汤","杏苏散"],"a":0,"e":"玉液汤以黄芪、山药益气健脾、补益脾肾，知母、天花粉、葛根滋阴清热、生津止渴，五味子固肾涩精，鸡内金助运化，主治气阴不足、脾肾两虚之消渴，益气升阳与滋阴固肾并行。B项增液汤增液润燥，主治阴虚肠燥便秘；C项百合固金汤养阴润肺，治肺肾阴虚咳嗽；D项麦门冬汤清养肺胃，均非消渴脾肾两虚之首选"},{"q":"苏子降气汤中当归的功效是","o":["补血活血","调经止痛","润肠通便","降逆下气","温中补虚"],"a":3,"e":"苏子降气汤主治上实下虚之喘咳，痰涎壅肺、肾不纳气，方中当归既养血和血以顾下虚，又辛散温通、降逆下气以助苏子、半夏降泄肺气，使气降则痰消喘平。A项补血活血、B项调经止痛是当归在四物汤中治血虚血瘀的常规功效；C项润肠通便多取当归用于血虚肠燥便秘；E项温中补虚非当归所长，均非本方用当归之专义"},{"q":"阳和汤的组成药物除麻黄、白芥子外其余是","o":["熟地、龟板、胶干姜、肉桂、川芎","熟地、鹿角胶、姜炭、肉桂、甘草","熟地、鹿角霜、炮姜、桂枝、甘草","熟地、鹿角胶、炮姜、细辛、甘草","生地、真阿胶、姜炭、桂枝、细辛"],"a":1,"e":"阳和汤由熟地黄、鹿角胶、姜炭、肉桂、麻黄、白芥子、生甘草组成，温阳补血、散寒通滞，主治阴疽患处漫肿无头、皮色不变、酸痛无热。方中鹿角胶温阳益精，姜炭温中散寒，肉桂温经通脉，不可易为鹿角霜、桂枝或细辛。A项龟板、川芎，C项鹿角霜、桂枝，D项细辛，E项生地、阿胶、桂枝均非本方组成，B项正确"},{"q":"苓桂术甘汤主治","o":["蓄水证","水热互结阴伤证","肾著病","中阳不足之痰饮","阳虚水泛证"],"a":3,"e":"苓桂术甘汤以茯苓健脾渗湿、祛痰化饮，桂枝温阳化气，白术健脾燥湿，甘草益气和中，共奏温阳化饮、健脾利湿之效，主治中阳不足之痰饮，见胸胁支满、目眩心悸、短气而咳。A项蓄水证为五苓散所主；B项水热互结、阴虚者属猪苓汤；C项肾著病为甘姜苓术汤证；E项阳虚水泛当用真武汤，均非本方主治"},{"q":"以下关于《温病条辨》之加减复脉汤的组成表述错误的是","o":["炙甘草","熟地黄","阿胶","生白芍","麦冬"],"a":1,"e":"加减复脉汤由炙甘草、干地黄、生白芍、麦冬、阿胶、麻仁组成，滋阴养血、生脉固脱，主治温病后期、邪伏阴分、阴虚脉结代。方中用的是干地黄而非熟地黄，熟地黄滋腻偏温、偏于补血，与温病养阴生津之旨不合，故B项表述错误。炙甘草、阿胶、生白芍、麦冬均为本方药物，A、C、D、E表述正确"},{"q":"温燥伤肺，气阴两伤证，治宜选用","o":["麦门冬汤","桑杏汤","杏苏散","清燥救肺汤","沙参麦冬汤"],"a":3,"e":"清燥救肺汤以桑叶清宣燥热，石膏、麦冬清热润燥，人参、甘草益气生津，杏仁、枇杷叶降利肺气，阿胶、胡麻仁、桑白皮养阴润肺，主治温燥伤肺、气阴两伤之干咳无痰、气逆而喘、咽干口渴、脉虚大。B项桑杏汤主治外感温燥轻证，无气阴两伤；C项杏苏散主治外感凉燥；E项沙参麦冬汤养阴润肺，主治燥伤肺胃阴分而热象不重者"},{"q":"由龟板、熟地黄、知母、黄柏、猪脊髓组成的方剂是","o":["左归丸","六味地黄丸","大补阴丸","知柏地黄丸","缩泉丸"],"a":2,"e":"大补阴丸以熟地黄、龟板滋阴填精、潜阳，知母、黄柏滋阴降火、清虚热，猪脊髓填精补髓，共奏滋阴降火之效，主治阴虚火旺之骨蒸潮热、盗汗遗精、咳嗽咯血。D项知柏地黄丸虽用知母、黄柏，但以六味地黄丸为底，含山药、山茱萸、泽泻、茯苓、丹皮，无龟板、猪脊髓；A项左归丸纯用滋阴填精之品，不含知母、黄柏，均可资鉴别"},{"q":"六味地黄丸和大补阴丸两方组成中均不含有的药物是","o":["泽泻、茯苓","知母、黄柏","生地黄、怀牛膝","牡丹皮、山茱萸","炙龟板、熟地黄"],"a":2,"e":"六味地黄丸由熟地黄、山茱萸、山药、泽泻、茯苓、牡丹皮组成，大补阴丸由熟地黄、龟板、知母、黄柏、猪脊髓组成，两方均用熟地黄而不用生地黄，亦都不含怀牛膝。A项泽泻、茯苓为六味地黄丸所有；B项知母、黄柏见于大补阴丸；D项牡丹皮、山茱萸属六味；E项龟板、熟地黄为大补阴丸主药，均非两方共缺之品"},{"q":"症见大便秘结，口渴，舌干红，脉沉无力，宜首选的方剂是","o":["玉液汤","增液汤","调胃承气汤","玉女煎","麻子仁丸"],"a":1,"e":"增液汤以玄参壮水制火、增液润燥，麦冬、生地养阴生津，取增水行舟之意，主治阴虚液亏之大便秘结、口渴、舌干红、脉沉无力，非硝黄攻下所宜。C项调胃承气汤主治阳明燥热结实，脉当有力；E项麻子仁丸主治脾约便秘，见大便干结、小便频数；A项玉液汤治消渴，均非本证首选之剂"},{"q":"用治血热妄行之上部出血证的方剂是","o":["十灰散","六一散","归脾汤","理中丸","芍药汤"],"a":0,"e":"十灰散集大蓟、小蓟、荷叶、侧柏叶、茅根、茜根、山栀、大黄、牡丹皮、棕榈皮十味烧灰存性，凉血止血，主治血热妄行之上部出血，见吐血、咯血、衄血、血色鲜红。C项归脾汤主治脾不统血之气虚出血，血色淡；D项理中丸温中祛寒，可治脾胃虚寒之便血；E项芍药汤清热燥湿、调气和血，主治湿热痢疾，均非上部血热出血之剂"},{"q":"黄土汤中附子配白术的意义是","o":["温中止泻","回阳救逆","温阳健脾","温阳利水","温经散寒"],"a":2,"e":"黄土汤主治脾阳不足、统摄无权之便血、崩漏，附子温壮脾阳，白术健脾燥湿、助脾统血，二者相配意在温阳健脾以复统摄之权，使血归经而不外溢。B项回阳救逆为四逆汤中附子配干姜之用；D项温阳利水多见于真武汤附子配茯苓、白术；E项温经散寒属当归四逆汤一类，均非本方附术配伍之义"},{"q":"桂枝茯苓丸的主治证是","o":["瘀阻胞宫证","下焦蓄血证","中风后遗证","瘀滞脉络证","产后血虚寒凝证"],"a":0,"e":"桂枝茯苓丸以桃仁、丹皮活血化瘀，桂枝温通经脉，芍药养血和血，茯苓渗湿健脾，共奏活血化瘀、缓消癥块之效，主治瘀阻胞宫之癥块、经闭痛经、产后恶露不尽。B项下焦蓄血为桃核承气汤所主；C项中风后遗症属气虚血瘀，用补阳还五汤；E项产后血虚寒凝当用生化汤，病机与病位各异"},{"q":"清气化痰丸主治何种咳嗽","o":["湿痰","热痰","燥痰","风痰","顽痰"],"a":1,"e":"清气化痰丸以黄芩、瓜蒌仁、胆南星清热化痰，半夏、陈皮、茯苓、枳实理气化痰，杏仁降肺气，主治痰热互结之咳嗽痰黄、稠厚胶结、胸膈痞满，故所治为热痰。A项湿痰咳嗽痰白量多，为二陈汤所主；C项燥痰干咳少痰、黏稠难咯，属贝母瓜蒌散；E项顽痰怪证当用礞石滚痰丸，均非清气化痰丸主治"},{"q":"清燥救肺汤与养阴清肺汤共有的药物是","o":["杏仁、枇杷叶","沙参、麦冬","麦冬、甘草","白芍、贝母","杏仁、甘草"],"a":2,"e":"清燥救肺汤含桑叶、石膏、人参、杏仁、枇杷叶、麦冬、阿胶、胡麻仁、甘草；养阴清肺汤含生地、麦冬、玄参、贝母、丹皮、白芍、薄荷、甘草，两方共用麦冬、甘草以养阴润肺、调和诸药。杏仁、枇杷叶为清燥救肺汤降肺气之品；白芍、贝母只见于养阴清肺汤；沙参并非两方组成，A、B、D、E均非共有"},{"q":"五积散的“五积”是","o":["风、寒、暑、湿、火","热、痰、气、血、湿","气、血、食、火、痰","寒、湿、气、血、痰","火、痰、热、湿、食"],"a":3,"e":"五积散以麻黄、白芷、干姜、肉桂散寒解表，苍术、厚朴、陈皮、半夏燥湿理气化痰，当归、川芎、芍药养血和血，桔梗、枳壳升降气机，主治寒、湿、气、血、痰五积互结之恶寒发热、身体疼痛、胸腹胀满、呕吐泄泻。A项风、寒、暑、湿、火为外感五气；B、C、E所列热、食等积均非五积散所主，名实不符"},{"q":"具有益气健脾，养血安胎之功的方剂是","o":["归脾汤","泰山磐石散","补中益气汤","八珍汤","保产无忧散"],"a":1,"e":"泰山磐石散以人参、黄芪、白术、甘草益气健脾，当归、熟地、白芍、川芎养血和血，续断、黄芩、砂仁固肾清热、理气安胎，主治气血两虚之滑胎、胎动不安，功专益气健脾、养血安胎。A项归脾汤益气补血、健脾养心，主治心脾两虚；C项补中益气汤升阳举陷；D项八珍汤平补气血；E项保产无忧散兼理气催生，均非专于益气养血固胎"},{"q":"一贯煎与益胃汤共有的药物是","o":["沙参、玉竹","麦门冬、冰糖","沙参、麦门冬、生地黄","生地黄、玉竹","生地黄、玉竹、川楝子"],"a":2,"e":"一贯煎以生地黄为君，配北沙参、麦冬、枸杞子、当归滋阴养肝，川楝子疏肝泄热；益胃汤以沙参、麦冬、生地黄、玉竹、冰糖滋养胃阴，两方共有沙参、麦门冬、生地黄。玉竹、冰糖仅见于益胃汤；川楝子、当归、枸杞子为一贯煎所独有，A、B、D、E均非两方共有之品"},{"q":"当归补血汤中当归与黄芪的配伍用量比例是","o":["1∶1","1∶2","1∶5","2∶1","5∶1"],"a":2,"e":"当归补血汤由黄芪一两、当归二钱组成，当归与黄芪用量比为1∶5，重用黄芪大补脾肺元气以资生血之源，配当归养血和营，体现有形之血不能速生、无形之气所当急固及阳生阴长之理，主治血虚发热。E项5∶1实为黄芪与当归之比，比例倒置；A、B、D均不合本方五倍用量之制"},{"q":"藿香正气散的功用是","o":["芳香化湿，理气和中","解表化湿，理气和中","解表化湿，升清降浊","解表散寒，升清降浊","解表散寒，祛湿化浊"],"a":1,"e":"藿香正气散以藿香外散风寒、内化湿浊，紫苏、白芷解表散寒，半夏、陈皮、厚朴、茯苓燥湿理气和中，桔梗、生姜、大枣宣降调和，共奏解表化湿、理气和中，主治外感风寒、内伤湿滞之霍乱吐泻。A项只言芳香化湿，遗漏解表散寒之力；C、D项升清降浊多属葛根芩连汤、五苓散类方功用；E项祛湿化浊未突出理气和中，均不确切"},{"q":"小承气是大承气汤减去哪味药物而成","o":["大黄","芒硝","枳实","厚朴","甘草"],"a":1,"e":"大承气汤由大黄、芒硝、厚朴、枳实组成，泻下与行气并重，主治阳明腑实重证痞满燥实俱全；小承气汤去芒硝，仅用大黄、厚朴、枳实，泻下力较缓，主治阳明腑实轻证。A项大黄、C项枳实、D项厚朴两方均有，E项甘草本不在大承气汤中，均非所减之品"},{"q":"芍药汤的功用","o":["清热解毒，凉血止痢","清热燥湿，行气化滞","清热燥湿，调气和血","清热止利，和中止痛","温中补虚，涩肠止泻"],"a":2,"e":"芍药汤以黄芩、黄连清热燥湿解毒，芍药、当归养血和血，木香、槟榔行气导滞，大黄通因通用，甘草调和，共奏清热燥湿、调气和血，主治湿热痢疾之腹痛、便脓血、里急后重。A项清热解毒、凉血止痢为白头翁汤所主；B项偏重行气化滞而略于和血；E项温中补虚、涩肠止泻属真人养脏汤一类，均非芍药汤功用"},{"q":"炙甘草汤的脉象特点是","o":["脉细数","脉沉迟","脉浮数","脉结代","脉弦数"],"a":3,"e":"炙甘草汤以炙甘草益气和中，人参、大枣补气，桂枝、生姜温通心阳，生地、麦冬、阿胶、麻仁滋阴养血，主治气血阴阳俱虚、心脉失养之心动悸、脉结代，故其脉象特点为结代。A项脉细数主阴虚内热；B项脉沉迟多属里寒；C项脉浮数主表热；E项脉弦数主肝郁化火或肝胆湿热，均非炙甘草汤所主之脉"},{"q":"黄连配伍肉桂，使心火得降，肾阳得复，肾水上承，心肾相交，《韩氏医通》赞其“能使心肾交与顷刻”。此方剂为","o":["天王补心丹","黄连阿胶汤","朱砂安神丸","桂枝甘草龙骨牡蛎汤","交泰丸"],"a":4,"e":"交泰丸仅黄连、肉桂两味，黄连清降心火，肉桂温肾助阳、引火归元，一清一温使心肾相交，主治心火偏亢、心肾不交之失眠，被赞能使心肾交于顷刻。B项黄连阿胶汤滋阴降火，主治阴虚火旺、心烦失眠；C项朱砂安神丸镇心安神、泻火养阴；A项天王补心丹滋阴养血、补心安神，均非连桂相配之交泰丸"},{"q":"济川煎的主治证是","o":["脾约便秘","津枯便秘","肾虚便秘","阳虚便秘","热结便秘"],"a":2,"e":"济川煎以肉苁蓉温肾益精、润燥通便，当归养血润肠，牛膝引药下行，泽泻渗湿，升麻升清，枳壳宽肠下气，主治肾虚精亏之大便秘结、小便清长、腰膝酸软，故为肾虚便秘。A项脾约便秘属麻子仁丸；B项津枯便秘当用增液汤增水行舟；D项阳虚便秘范围较宽，冷秘多取半硫丸温阳通便；E项热结便秘宜承气类，均非本方所主"},{"q":"下列药物不是玉女煎组成的是","o":["牛膝","石膏","知母","升麻","麦门冬"],"a":3,"e":"玉女煎由石膏、熟地黄、麦冬、知母、牛膝组成，清胃热、滋肾阴，主治胃热阴虚之牙痛、头痛、消渴及吐血衄血，牛膝引热下行。方中并无升麻，升麻发表透疹、清热解毒、升举阳气，多用于柴葛解肌汤、补中益气汤等，不属玉女煎组成，故D项错误"},{"q":"四逆汤的组成是","o":["附子、人参、干姜","人参、干姜、甘草","人参、附子、甘草","附子、干姜、甘草","附子、干姜、葱白"],"a":3,"e":"四逆汤由附子、干姜、炙甘草组成，附子温壮元阳，干姜温中散寒，二者相须回阳救逆，甘草益气和中、缓急并缓附姜之烈，主治少阴病阴盛阳衰之四肢厥逆、恶寒蜷卧、脉微细。A、C项含人参，分别为四逆加人参汤一类加减方；B项人参、干姜、甘草缺附子，无回阳之力；E项附子配葱白为白通汤，均非四逆汤原方"},{"q":"败毒散的功用是","o":["发汗解表，散风祛湿","助阳益气，解表散寒","益气解表，理气化痰","散寒祛湿，益气解表","清热解毒，祛风除湿"],"a":3,"e":"败毒散以羌活、独活、川芎、柴胡祛风散寒除湿，前胡、桔梗、枳壳宣降肺气、化痰，人参、茯苓、甘草益气健脾，扶正祛邪，共奏散寒祛湿、益气解表，主治气虚外感风寒湿邪之憎寒壮热、无汗、头项强痛。C项益气解表、理气化痰为参苏饮所主；B项助阳益气、解表散寒属再造散；A项未体现益气扶正，均非败毒散功用"},{"q":"酸枣仁汤中用量最少的药物是","o":["酸枣仁","茯苓","川芎","知母","甘草"],"a":4,"e":"酸枣仁汤原方酸枣仁二升为君，重用养心安神；知母、茯苓、川芎各二两，滋阴清热、宁心、调血；甘草仅一两，用量最轻，取其和中缓急、调和诸药，故用量最少者为甘草。A项酸枣仁为君药用量独重；B、C、D三味用量相等且均重于甘草，均非最少之品"}];
